                values: new object[,]
                {
                    { 745, "طه حسين", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الفتنة الكبرى على وبنوه\n \"أمام هذه الأمور العظام، وفي قلب هذه الفتنة المظلمة البغيضة وجد عليٌّ نفسه كأحسن ما يجد الرجلُ نفسه، صدقَ إيمانٍ بالله، ونصحًا للدين، وقيامًا بالحق واستقامةً على الطريق المستقيمـة، لا ينحـرف ولا يميل ولا يُدهـن من أمـر الإسـلام في قليـل ولا كثير، وإنما يرى الحقَّ فيمضي إليه، لا يلوي على شيء، ولا يحفل بالعاقبة ولا يعنيه أن يجد في آخر طريقه نُجحًا أو إخفاقًا، ولا أن يجد في آخر طريقه حياةً أو موتًا، وإنما يعنيه كل العناية أن يجد أثناء طريقه وفي آخرها رضى ضميره ورضى الله\". طه حسين من خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته. وما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلٌّ في مجاله.\n اسم المؤلف :- طه حسين\n سنة النشر :- 2023", "/images/products/9789777954259.webp", "9789777954259", "الفتنة الكبري - علي وبنوه", null, 200m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 746, "طه حسين", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"وكان أصدقاؤه إذا سمعوا منه هواجسَ الأحلام أو خواطرَ اليقظة، ألحُّوا عليه في أن يذيع ذلك وينشره، فيبتسم ثم يهزأ، ثم يمتنع عليهم ويلحُّ في الامتناع؛ لأنه كان يؤمن بأن ما يكتبه لم يصل بعد إلى أن يكون خليقا بأن يقدَّم إلى المطبعة. فهو كان يخافُ المطبعةَ ويُكْبرها ويحيطها بشيء من التقديس غريب. وكان يتحدث بأن ما يقدَّم إلى المطبعة من الآثار المكتوبة أشبه شيء بما كان يقدمه الوثنيون القدماء إلى آلهتهم من الضحية والقربان، وبما يتقدم به الآن المؤمنون المُترفون إلى إلههم من الصلاة والدعاء. فمن الحق أن تُصطفى الضحيةُ وأن يُتخيَّر القربان، وأن تكون الصلاةُ قطعةً من النفس، وأن يكون الدعاءُ صورةً للقلب والعقل جميعًا\". طه حسين من خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته. وما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلٌّ في مجاله.\n اسم المؤلف :- طه حسين\n سنة النشر :- 2023", "/images/products/9789777954228.webp", "9789777954228", "أديب", null, 110m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 747, "إبراهيم عبد المجيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "آفة حارتنا النسيان.. مقولة شاعت لنجيب محفوظ صارت مريحة لتفسير كل ما يحدث حولنا وأسبابه على مر التاريخ. صارت نوعًا من العلاج النفسي المؤقت للشعور باليأس في بعض الأحيان. هنا الكاتب إبراهيم عبد المجيد يحاول أن يتذكر ويلقي ضوءًا على ما تم نسيانه أو إهماله، من صفحات التاريخ الروحي والمادي للوطن. التاريخ الروحي بما فيه من أفكار وكفاح من أجل الحرية، والتاريخ المادي بما فيه من بقايا حضارة ونهضة في العمارة والطرق والحدائق وما تشاء. الكاتب يدعونا أن نتذكر معه ولا نستسلم ففي الذاكرة حياة. هنا مقالات أقرب إلى التأملات تعكس رحلة عميقة مع الدراسة والفهم عبر التاريخ والتجارب، فيها إجابات لكنها تذكرنا بالأسئلة الكبرى للحياة، وليست مجرد تعليقات عابرة، ونشرت في صحف ومواقع هامة في مصر وخارجها. فضلًا عن متابعات لبعض الكتب الرائعة التي صدرت في الأعوام الأخيرة لها بصمتها على حياتنا الثقافية. هنا أحاديث عن فيض الأرض وخيرها من الفكر والبشر الذي يتجاوز أي حصار، فكل حصار زائل مهما طال.\nـــــــــــــــــــــــــــــــ\nإبراهيم عبد المجيد هو الروائي صاحب الأعمال الشهيرة، مثل روايات \"بيت الياسمين\"، و\"ثلاثية الإسكندرية\"، و\"في كل أسبوع يوم جمعة\"، و\"البلدة الأخرى\"، وثلاثية \"الهروب من الذاكرة\"، و\"العابرة\" وكتب فكرية، مثل \"رسائل إلى لا أحد\" وغيرها، والذي عرفت أعماله طريقها إلى اللغات الأجنبية، والذي حاز على جوائز عديدة، مثل جائزة نجيب محفوظ من الجامعة الأمريكية، وجائزة الدولة التقديرية، وجائزة كتارا في الرواية، وجائزة الشيخ زايد، وآخرها جائزة النيل في الآداب عام 2022.\nاسم المؤلف :- ابراهيم عبد المجيد \nسنة النشر :- 2023", "/images/products/9789777954204.webp", "9789777954204", "افة حارتنا - بين الذاكرة والنسيان", null, 330m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 748, "ت. ج. دي بور", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إن هذه السلسلة من كلاسيكيات الفلسفة تأليفًا وترجمة هي أبرز ما قامت عليه نهضتنا الحديثة، وهي ما تربت عليه الأجيال السابقة.\nوما أحوجنا اليوم لإعادة نشر هذه الكلاسيكيات من مؤلفات ومترجمات رائدة لتستفيد منها أجيالنا الشابة، وخاصة في ظل ندرة ما يكتبه المتخصصون المعاصرون في الفلسفة ومجالاتها المختلفة، وفي ظل غياب المنهج الفلسفي للتفكير في حياتنا المعاصرة، مما كان السبب المباشر لما نراه من تطرف وتعصب وجمود وعدم تقبل الآخر وفقدان القدرة على التحليل ونقد الأفكار.\n***\nاستشعر دي بور نقصًا كبيرًا في الدراسات الغربية حول الفكر الإسلامي، إذ إن أغلبها جزئي، لا يسمح لمفكري الغرب برسم خارطة عامة لأنساق هذا الفكر، وعلاقته بنظيره اليوناني واللاهوت المسيحي وأثره على الفكر الغربي في العصور الوسطى، فقرر دي بور وضع هذا الكتاب الموسوعي، ليكون توطئة للباحثين الغربيين المهتمين بالفلسفة الإسلامية. ولعله لم يدر بخلده – وهو يخط كتابه هذا - أنْ سيأتي مترجم عربي ينقل جهده إلى اللغة العربية؛ شارحًا ومصوِّبًا بصياغة عربية لا يستشعر معها القارئ أنه بصدد نص أجنبي، هذا المترجم هو المخضرم والبحّاثة محمد عبد الهادي أبو ريدة.\nاستطاع أبو ريدة أن يحوِّل هذا الكتاب من عمل يستهدف الغرب إلى مرجع فلسفي للمتخصصين العرب في الفلسفة الإسلامية، وإذا نظر القارئ إلى المساحة التاريخية والجغرافية الشاسعة التي يتعرض لها هذا المصنف لفهم مدى الجهد الهائل الذي بذله أبو ريدة في إخراج الكتاب بعد ترجمته على نحو فعال.\nوكان ضروريًّا أن يعود هذا المرجع إلى أرفف مكتبة الفلسفة بعد تحقيق جديد؛ يضيف إلى العمل، من خلال مراجعة الترجمة على النص الأصلي لدي بور، وتصويب بعض الأخطاء الإملائية والنحوية، ومراجعة بعض المفاهيم وشرحها.\nاسم المؤلف :- ت.ج.دي بور \nترجمة :- محمد عبد الهادى أبو ريدة \nسنة النشر :- 2023\n\nترجمة محمد عبد الهادي أبو ريدة تقديم وتحقيق ومراجعة على الاصل الالماني د. كريم الصياد", "/images/products/9789772937714.webp", "9789772937714", "تاريخ الفلسفة فى الاسلام", null, 425m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 749, "محمد مصطفى عرفي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قلبه الطيب تفتت بانقلاب «الكيزان»، أو الإخوان مثلما يُسميهم السودانيون، وربيبهم ومُنظِّرهم الترابي.. تبًّا لهم! ماذا فعلوا بك يا سوداننا الحبيب؟ كيف غدروا بك وألقوك في غياهب جُب حالك الظلمة ومستنقع للعنف لا ينقضي؟ هوس ديني أهوج عمَّ السودان حتى تم إيهام عوام الناس وآحادهم بأن جَلْد فتاة ضُبطت متلبسة بجرم ارتداء البنطلون الجينز بالشارع هو انتصار حضاري للإسلام..\n***\nهذه الرواية تحاول تفسير ما جرى للسودان الشقيق، انطلاقًا من الماضي القريب إلى الحاضر الـمَعيش، شاخصة إلى مستقبلٍ غامضٍ ومُربك، وذلك من خلال شخصية محمود، الذي يستكمل رسالته للدكتوراه في جامعة لندن، ورغم برودة الأجواء، يستدفئ بعلاقة عاطفية تشتعل بينه وبين فتاة سودانية، وحتى يستكمل رسالته حول تطور الفكر السياسي لحركة الإخوان بالسودان، يطير إلى الخرطوم لنتعرَّف على حقيقة ما تعرَّض له السودان والسودانيون، على أيدي نظام قفز على السلطة متدثرًا بالأسمال الدينية.\nــــــــــــــــــــــــــــ\nمحمد مصطفى عرفي.. كاتب ومحاضر أكاديمي، حاصل على درجتي الماجستير والدكتوراه في القانون والعلوم السياسية من لندن. صدرت له روايات: الحب في لندن، ودموع ماتريوشكا، ووردة في حقل الصبار، وظلال الكولوسيوم.\nاسم المؤلف :- محمد مصطفى عرفى \nسنة النشر :- 2023", "/images/products/9789777954181.webp", "9789777954181", "حلو مر", null, 245m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 750, "عبدالله محمد على تلمساني", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يشهد العالم العربي بوادر \"وعي مجتمعي جديد\"، تظهر بشائره في بداية تحرُّر بعض دوله من أوهام، ومظاهر مجتمعية وموروثات تاريخية ومؤثرات سياسية تؤدّي إلى استمرار تخلفه. ولقد انعكس هذا الوعي على تركيز هذه الدول على قضايا التنمية وتطوير مجتمعاتها، ومن ثَمّ تحقيق تقَدُّم على مؤشرات تطوُّر عالمية.\nهناك عدد من الظروف التاريخية، والتنموية، والسياسية، والتِّقَنِيَّة، التي تَبْدو وكأنها قد توَفرَت مجتمعةً لإعطاء العالم العربي \"فُرْصةً أخيرة\" للحاق بالدول المتقدمة، قبل إسْدال السِّتار علينا لِقَرنٍ آخر.\nينطلق كتاب \"بين الوعي والأوهام\" في تناول هذه الظواهر من منظور أوسع؛ يُقدِّم المؤلف من خلاله نظرة \"غير تقليدية\" للكون من حولنا، ومظاهر للمؤثرات على توجهنا المتوازن كأفراد ومجتمعات، وسُبل الاستجابة لتحديات يواجهها \"الجيل العربي الجديد\" بشكل خاص والعالم العربي بشكل عام، وخطوات عملية للاستفادة من فرص مواتية في تحقيق قَفزة حضارية تستحقها دول عالمنا العربي.\nــــــــــــــــــــــــــــ\nد.عبدالله تلمساني، كاتب ومفكر في مجال التطوير الذاتي والمجتمعي، ومستشار في مجالات التخطيط. خريج جامعتي هارفارد وبيركلي، ودارس التنمية الاقتصادية فيMIT .\nصدر له عدد من المؤلفات، أهمها كتاب \"طَريق التَّوازُن\"، باللغتين العربية والإنجليزية، الذي أشارت إليه مُؤلِّفَة الكتاب رقم (1) في قائمة \"نيويورك تايمز\"، شيري كارتر سكوت، بأنه يمثل \"دَليلًا لِعَيْش حياة مُفعَمَة بالرِّضا\".\nاسم المؤلف :- عبدالله محمد على تلمسانى \nسنة النشر 2023", "/images/products/9789777954167.webp", "9789777954167", "بين الوعى والاوهام", null, 145m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 751, "نهي داود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الظلم ظلمات يوم القيامة، ولكن ماذا عن الظلم في الدنيا؟ هل يحق للمظلوم أن ينتفض وأن ينتقم؟ وهل يحرق الانتقام الظالم فقط؟ أم قد يقع المظلوم أيضا ضحية لانتقامه؟ في هذه الرواية نرى حكايتين متوازيتين، حكاية رضا الفتاة البسيطة التي تنحصر كل أحلامها في الزواج من ابن الجيران الثري الوسيم. وحكاية نانسي، سيدة المجتمع الجميلة التي تصالحها الحياة أخيرًا بالزواج من رجل يحترمها ويحتويها. وهناك حكاية ثالثة تدور في الخفاء. ضحايا تقع وقتل ينفذ وأيادي الشر المتوارية تعبث وراء الستار. فمن هو الظالم ومن هو المظلوم في تلك الحكايا؟ ــــــــــــــــــــــــــــنهى داود كاتبة مصرية، ولدت في إنجلترا وتخرجت في كلية الهندسة بجامعة القاهرة. عملت بمجالها لعدة سنوات قبل أن يغمرها تيار الشغف، وتجد نفسها عاكفة على كتابة أولى رواياتها البوليسية! حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، وتخصصت في أدب الجريمة.صدر لها 7 روايات منها: جريمة السيدة هـ ، وجريمة العقار 47 ، وجثتان والثالثة عند قدمي. حصلت على جائزة الأكثر مبيعًا لعامين متتالين 2021 و 2022 من منصة iRead.اسم المؤلف :- نهى داود سنة النشر :- 2023", "/images/products/9789777954174.webp", "9789777954174", "رضا", null, 195m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 752, "اشرف العشماوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "‎\"تفصلني عن المَلِك بضعة أمتار، وفي جيبي مسدس، المسألة مسألة وقت، وكل شيءٍ يُنال بالصبر\".\n \n                                                                                                                                        شكري تاج الدين\n \n\"في كل محطات حياتي كانت لي جولات كثيرة، لكني لم أنَلْ سوى شرف المحاولة.. إن كان هذا شرفًا\".\n \n                                                                                                                                          فهمي تاج الدين\n \n\"لولا أنني رأيت بعض الدنيا بلونها الوردي، لظللت معتقدة أن الأسود هو لون الحياة.. مع أننا لا نرتديه إلا وقت الموت\".\n \n                                                                                                                                                 أمينة سعادة\n \n\"لا تتفاءل إذا ما رأيت الغراب يقف على حافَّة نافذتك في الصباح.. فهو لن يُغرد أبدًا\".\n \n                                                                                                                                                   فايز حبشي\n اسم المؤلف :- اشرف العشماوى\nسنةالنشر :- 2023", "/images/products/9789777954150.webp", "9789777954150", "السرعة القصوى صفر", null, 300m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 753, "هشام الخشن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مَن منَّا لا يسمع أصواتًا بداخله؟ أصواتًا تتحول في كثيرٍ من الأحيان إلى شخوصٍ تحاورنا ونحاورها، نُحسن إخفاءها فتكون أسرارًا لا نقوى على إعلانها، وحين نقدر على التحدُّث بما يجول في داخلنا، تتكاثر علينا الموانع، ثم لا تلبث أن تجيء اللحظة التي لا نستطيع معها كتمانًا، أو ربما نجد الأشخاص الذين نرجو منهم استماعًا غير مشروط. حينئذٍ تتكامل الأصوات لتصبح، إن قُدِّر لها، صوتًا واحدًا؛ لذلك لم يكن غريبًا أن تتناوب على «ناعومي» أصوات «نعيمة» و«نعمت» و«نوني»، وإن خفتت الأصوات، أو حاولت هي إسكاتها.\nفي هذه الرواية، يأخذنا هشام الخشن في رحلةٍ عبر تعقيدات النفس البشـرية، لتخوض البطلة صراعاتها الحياتية من منطقةٍ تختلط فيها الأصوات وتتحوَّل إلى شخوصٍ لها ملامح وأفكار متباينة، لكنها في النهاية تسعى إلى أن تصل لمستقبل بلا صدمات جديدة.\nــــــــــــــــــــــــــــ\nهشام الخشن.. روائي وقاص مصري، يعمل مهندسًا مدنيًّا. له عدد من الروايات منها: «ما وراء الأبواب»، «وتلال الأكاسيا»، و«حدث في برلين»، و«شلة ليبون»، و«بالحبر الأزرق». تحوَّلت روايته «7 أيام في التحرير» إلى ملسلسل تلفزيوني، ووصلت روايته «جرافيت» إلى القائمة الطويلة لجائزة البوكر العربية عام 2014م. له مجموعتان قصصيتان هما: «حكايات مصرية جدًّا»، و«دويتو».\nاسم المؤلف :- هشام الخشن \nسنة النشر :- 2023", "/images/products/9789777954136.webp", "9789777954136", "ناعومى واخواتها", null, 215m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 754, "عبير حامد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليست “ختام” في هذه الرواية سوى رمز للإنسان العربي بهمومه وأحلامه وإخفاقاته وانتصاراته، فقد واجهت “ختام” ببساطتها تعقيدات الحياة في رحلة الهجرة من الوطن المحتل بحثًا عن مصدر رزق وحياة كريمة برفقة شريكها؛ لتظل في صراعها مع الحياة باحثة عن مكان وزمان لحلمها البسيط في أن تعيش حياةً بلا منغصات.\nوكما تعدَّدت الأزمنة في الرواية، كذلك تعدَّدت البيئات والأمكنة، بداية من فلسطين المحتلة، مرورًا بلبنان والأردن وسوريا، ثم الإمارات التي تجد «ختام» فيها وطنًا وملجأً لها ولأبنائها، وتنتهي الرواية بالعودة إلى مشهد البداية في محاولةٍ لإقناع القارئ بأنه أمام عملٍ حقيقي، وليس مجرد خيال كاتبة قررت الانطلاق إلى فضاء الرواية.\nاسم المؤلف :- عبير حامد \nسنة النشر :- 2023", "/images/products/9789777954082.webp", "9789777954082", "ختام برائحة المسك", null, 245m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 755, "كريم فهمي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "دائمًا ما تكون هذه هي البداية، عندما يكون الهدف هو القوة والسيطرة تجد قوتين متكافئتين تتصارعان عليهما، ومع كل محاولاتهما فيالقضاء على بعضهما البعض، فإن أول من يتأثر بهذا الصراع مَن ليس لهم أية مكاسب أو منافع في هذه المعركة ... حتى بعد انتهائها،فعلى مر العصور دائمًا ما يدفع الضعيف ثمن رغبات القوي، لكن في مملكة الموت … البداية لا تكون مثل هذه البدايات! «اللي ليك جايلك.. كله متشال ومكتوب» «لو خانك الشخص مرة فده ذنبه، ولو خانك مرتين فده ذنبك إنت» «ياللي إنت صابر عالوجع.. اصبر كمان خليك جدع».\nاسم المؤلف :- كريم فهمى \nسنة النشر :- 2023", "/images/products/9789777954129.webp", "9789777954129", "مملكة الموت", null, 245m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 756, "فتحية النمر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه رواية تتقاطع فيها خطوط الزمن، تاركة للقارئ مساحة للربط وبناء الصور الذهنية، سواء للأزمنة أو الأمكنة التي تتناولها، فرغم أن الأحداث تبدأ مطلع عام 1980 على لسان إحدى بطلات الرواية، إلا أن صوتًا آخر يروي لنا الحكاية بتفاصيل أكثر، تعود بنا إلى أزمنةٍ بعيدة، أو كما تقول الكاتبة: «في ذلك المكان والزمان البعيدين اليوم جدًّا عن أفق النظر والسمع»، ومن خلال الأحداث المرتبطة بشخصيات الرواية وصراعاتها الداخلية ومصائرها التي تتقاطع بشكلٍ درامي يمنح العمل مزيدًا من الإثارة، ومن خلال التصاعد الدرامي المتشابك، نتعرَّف بشكلٍ عام على شكل وطبيعة الحياة في دولة الإمارات، وبشكلٍ خاص في قرية الصيادين بإمارة الشارقة حيث تدور أحداث الرواية.\nاسم المؤلف :- فتحية النمر \nسنة النشر :- 2023", "/images/products/9789777954099.webp", "9789777954099", "رسائل عشاق", null, 335m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 757, "وسيم السيسي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب، عرض لعلوم شتى بطريقة مبسطة ومشوقة وإضفاء الحياة عليها، وجعل الموضوع يتحدث عن ذاته كأنه إنسان، فمصر تتحدث عن نفسها وتاريخها وحضارتها العريقة وجغرافيتها، والقلب يتحدث عن طبيعته التشريحية ودلالة استخدامه في التعبير عن الحب والعواطف بين الشعراء، والمرأة وتكريمها عند القدماء المصريين ومقارنة وضعها وطريقة حياتها لديهم ولدى اليونان والرومان والهند وغيرها من الحضارات المختلفة، أو الأهرام وأسرارها وعجائبها وسبب بنائها، أو تحتمس الثالث وشجاعته وحكمته الحربية وأثرها في وضع الخطط العسكرية الحديثة.\nوكان منطلق د. وسيم أن القراءة معرفة، والمعرفة قوة، والذين يقرأون لا ينهزمون، وأن حفظ الأفكار في كتاب أعظم ما وصل إليه الإنسان، ولولا هذا الحفظ لما تقدمت البشرية خطوة واحدة. وأن هذه العلوم يجب أن تقدم للقارئ بشكل بسيط ومشوق وبه مسحة أدبية، فالعلم جميل إذا أحسنا عرضه.\nــــــــــــــــــــــــــــــــــــــ\nالدكتور وسيم رشدي السيسي، أستاذ جراحة المسالك البولية وأمراض الذكورة. إلى جانب نشاطه وإسهامه الطبي في مجال تخصصه، اهتم بقضايا وطنه، فتوصَّل بعد تفكيرٍ عميقٍ إلى أن مصر لن يعود لها وجهها الحضاري، وتصبح رائدة من روَّاد العلوم والفنون، إلا بالاطلاع على تاريخها القديم، كما توصَّل إلى أن وحدة مصر وتوحدها لن يتمَّا  إلا بتاريخ موحَّد.. خصوصًا أن التاريخ الوحيد الذي أصبح عِلمًا يدرسه العالم كله هو علم المصريات (Egyptology)، وهو العلم الذي أبحر بين شاطئيه ليُخرج لآلئه، ويثبت من خلاله لمصر ريادتها في شتى مناحي الحياة. صدر له عدد من الكتب منها : \"مصر علمت العالم\" و\" هذه هي مصر\" و\" في البدء كانت مصر\" و\"المسكوت عنه في التاريخ\".\nاسم المؤلف :- وسيم السيسى \nسنة النشر :- 2023", "/images/products/9789777954112.webp", "9789777954112", "انا اتحدث اليكم", null, 225m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 758, "فرج كامل", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اسم المؤلف :- فرج الكامل \nسنة النشر :- 2023", "/images/products/9789777954105.webp", "9789777954105", "تأثير وسائل الاعلام والتواصل الاجتماعى", null, 330m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 759, "نهلة الجواهرجي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"الحوائط تهتزّ من حولي. تارة أراها حوائط غرفة نومي وتارة أخرى حوائط الكهف. جسدي يؤلمني، أرتجف بشدة... تتخبّط أسناني ببعضها... أشعر بعطش شديد... أرتعش بعنف كالذي أصابته صرعة، لا أرى جيدا... أشعر أنني أتجوّل داخل جسدي... نبضي ضعيف لا أشعر به\".\nفي داخل كل منا عالم خاص لا يعلمه إلا صاحبه. وبالرغم من عدم ظهوره، فإنه يؤثر كثيرًا علينا وعلى قراراتنا ورؤيتنا للحياة.\nبطلة الرواية تقرر اكتشاف هذا العالم الغامض بداخلها وتواجه نفسها الحقيقية لكي تكتشف أن أصعب مواجهة هي مواجهة النفس.\n اسم المؤلف :- نهلة الجواهرجى\nسنة النشر :- 2023", "/images/products/9789777954068.webp", "9789777954068", "أنا من جديد", null, 150m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 760, "كاميليا حسين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تبرع كاميليا حسين في محو واستبعاد كل ما يفيض عن الحاجة، ويمكن استنتاجه من بين السطور، ومعيار البراعة هنا أن هذا المحو لا يجلب تعتيمًا بقدر ما يُكثِّف حضور المكتوب ويُضيئه، على طريقة الرسام الفرنسي جورج دي لاتور في توظيف التضاد بين الضوء والعتمة للوصول إلى أقصى درجات التعبيرية في لوحاته.\nمنصورة عز الدين\nلا تحمل «استغماية» شيئًا من عثرات الأعمال الأولى لكُتَّابها، حيث يتجلى إحكام البنية، وتتجلى مهارة الحذف والقدرة على قول الكثير من خلال القليل من الكلمات.\nعزت القمحاوي\n«استغماية» نص مدهش، مكتوب بسلاسة سردية لافتة، من خلال لغة بها الكثير من العذوبة، وصدق عظيم في نقل المشاعر ينم عن موهبة حقيقية.\nأشرف العشماوي\nهذه هي الرواية القصيرة الفائزة بجائزة «ورشة أصوات وخطوط لرواية الجريمة الأدبية» التي نظمتها «ستوريتل» للكتب الصوتية بالتعاون مع  الدار المصرية اللبنانية خلال الفترة من 15 مارس حتى 15 سبتمبر 2022، وقد أفرزت الورشة سبع روايات قصيرة تضخ دماءً جديدة ومبشرة في شرايين الإبداع المصري والعربي.\nالناشر\nالرواية نتاج ورشة كتابة «ستوريتل» للكتب الصوتية بالتعاون مع  الدار المصرية اللبنانية\nاسم المؤلف :- كاميليا حسين \nسنة النشر :- 2023", "/images/products/9789777954075.webp", "9789777954075", "استغماية", null, 150m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 761, "شريف عرفة", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أعتقد أن ترتيب وأسلوب الكتاب هو إبداع وابتكار وتجديد للفكر، خاصةً في كيفية التغلب على الكروب دون الدخول في دهاليز الطب النفسي. أهنئ الكاتب وأشكره على هذا المجهود والتجديد\".\nبروفيسور أحمد عكاشة\nالرئيس الأسبق للجمعية العالمية للطب النفسي\nاعتدت أن أحدثكم عن السعادة والنجاح، والآن أحدثكم عن الجانب الآخر.\n- حيث تتحطم الأحلام على صخور الواقع، وتقهر الظروف أكثر خطط النجاح إحكامًا، و  يكدر الفقدان رغد استقرار الحياة..\n- حيث يطل الألم برأسه، وتعصف الأيام بنضارة الصبا وصحة الشباب..\n- حيث يفرض الأمر الواقع سطوته وتدرك أن بذل أقصى ما في وسعك، لم يكن كافيًا..\nما معنى السعادة في عالم يملؤه الألم والمعاناة؟!\nيتناول هذا الكتاب فكرة السعادة وسط صعاب الحياة.. من خلال موضوعات مثل (السعادة السامة، الأوهام الإيجابية، مشكلات الحياة، اللاسعادة الزوجية، السعادة والشعر الأبيض، وتجاوز الصدمات، والموت الإيجابي…) بطريقة مسلية مليئة بالرسوم الكاريكاتورية والحكايات الحقيقية، واستنادًا لأحدث الدراسات والتجارب النفسية.\nعن السعادة الواقعية نتحدث..\nفهل تريد التعرف عليها؟\nـــــــــــــــــــــــــــــــــ\nد.شريف عرفة فنان كاريكاتير وباحث في علم النفس الإيجابي. والكاتب الأكثر مبيعًا في هذا المجال. حاصل على ماجستير علم النفس الإيجابي التطبيقي من جامعة إيست لندن، وماجستير إدارة الموارد البشرية من الأكاديمية العربية وبكالوريوس طب وجراحة الفم والأسنان من جامعة القاهرة. حصد العديد من الجوائز التقديرية لأعماله مثل جائزة بوكوفينا للفنون، وجائزة الكاريكاتير العربي، وجائزة محمود كحيل، جائزة تريم عمران، وتم ترشيحه لجائزة الصحافة العربية.\nاسم المؤلف :- شريف عرفة \nسنة النشر :- 2023", "/images/products/9789777954051.webp", "9789777954051", "السعادة الواقعية", null, 260m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 762, "مصطفى عبد الرازق باشا", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إن هذه السلسلة من كلاسيكيات الفلسفة تأليفًا وترجمة هي أبرز ما قامت عليه نهضتنا الحديثة، وهي ما تربت عليه الأجيال السابقة.\n \nوما أحوجنا اليوم لإعادة نشر هذه الكلاسيكيات من مؤلفات ومترجمات رائدة لتستفيد منها أجيالنا الشابة، وخاصة في ظل ندرة ما يكتبه المتخصصون المعاصرون في الفلسفة ومجالاتها المختلفة، وفي ظل غياب المنهج الفلسفي للتفكير في حياتنا المعاصرة، مما كان السبب المباشر لما نراه من تطرف وتعصب وجمود وعدم تقبل الآخر وفقدان القدرة على التحليل ونقد الأفكار.\n \n***\n \nعالج هذا الكتاب ثلاثة موضوعات يكمل بعضها بعضًا، ويرتبط بعضها ببعض أوثق الارتباط، وهي الدين والوحي والإسلام. فأولها بحث في حقيقة الدين على العموم؛ وثانيها تفسير لظاهرة هامة صاحبت معظم الأديان وتوقفت عليها نشأتها وهي ظاهرة الوحي؛ وثالثها توضيح للدين القائم على الوحي بمثالٍ عالٍ من أمثلته وهو الإسلام.\n \n\"إنه كتاب تأسيسي تجلت فيه قدرة الشيخ مصطفى عبد الرازق على التجديد في المنهج الذي اتبعه في دراساته وأبحاثه المختلفة، وفي قدرته على تطبيق هذا المنهج ببراعة في الموضوعات التي درسها حيث مكنه هذا المنهج والقدرة على تطبيقه من أن يقدم آراء جديدة مستقلة في اتجاهها وفي نتائجها عن كل ما سبقها من أبحاث ودراسات في نفس هذه الموضوعات.\n \nومن هنا تأتي الأهمية القصوى لقراءته بإمعان وتدبر ففيه يجد القارئ العزيز الإجابة الشافية الصافية عن أي تساؤل يرد على ذهنه في هذه الموضوعات الثلاثة التي لا تزال موضع نظر ونقاش بين المتخصصين حتى اليوم\".\nاسم المؤلف :- مصطفى عبد الرزاق باشا \nتقديم وشرح :- مصطفى النشار \nسنة النشر :- 2023\n\nتقديم مصطفي النشار", "/images/products/9789772937707.webp", "9789772937707", "الدين والوحى والإسلام", null, 150m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 763, "عمار على حسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“رأيته في الأيام الأخيرة، وقد نحل جسده، وطالت لحيته، وتمزقت ملابسه، وأوقف الحديث عن حلمه الغريب، مكتفيًا بترديد اسم امرأة لا نعرفها. من هذه السيدة التي أدركنا من وصفه أنها لا مثيل لها في الحُسن والطيبة؟ بحثنا جيدًا في تاريخه فلم نجد أثرًا”.\n***\nتختلف رؤى النوم وأحلامه لكل شخص من ليلة إلى أخرى إلا بطل هذه الرواية، موظف التموين النزيه، فهو يعيش حلمًا متواصلًا بالغ الغرابة. ما أن يدخل إلى النعاس حتى يُستكمل الحلم من حيث انتهى الليلة السابقة. في النوم وحده يعيش حياة رغيدة بينما واقعه غاية في البؤس والتعاسة في ظل الفقر، ونكد الزوجة الطامعة، وقهر الوظيفة. حين يضيع الحلم يبدأ رحلة بحث عنه ملهوفًا على حافة الجنون. هذا البطل ليس فردًا إنما هو رمز للذين تطلعوا إلى تغير أحوالهم القاسية ثم استيقظوا على كابوس.\nاسم المؤلف :- عمار على حسن \nسنة النشر :- 2023", "/images/products/9789777954044.webp", "9789777954044", "احتياج خاص", null, 215m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 764, "زينب عفيفي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فى هذه اللحظة المتوهجة كنا نسير صامتين ننتظر لحظة الغروب دون ان يكشف احدنا للأخر ما يجول فى خاطؤه كنت أفكر فيك بشكل متواز مع جمال اللخظة وتمنيتك أن تشهدها معى كعادتى فى اقتسام الجمال والفرح وحتى الحزن معا اتخيلك تشد على يدى ضاغطاً بأناملك على كفى مثلما كنا نعبر الشوارع المزدحمة سارحاً معى فى خيال مشترك ماذا لو تعانقنا امام هذا المشهد الإلهي\"\n****\nفي قرية معزولة تتفجر الوحده والحكايات والذكريات مع مجموعة من الجيران تجمعهم اوجاع مشتركة رسمت ضحى الفنانة التشكيلية هذه الحكايات فى رسائل مكتوبة الى صديق التقته بالمصادفة انها صور لوجوه تعيش بيننا او هى صور وجوهنا حين تنفرد بأنفسنا . \nالمؤلف :- زينب عفيفى \nسنة النشر :- 2023", "/images/products/9789777954037.webp", "9789777954037", "عزيزى المستبد", null, 225m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 765, "محمد فريد بك", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب يُعد من بواكير الكتابات التاريخية الجديدة، فقد كُتب في نهاية القرن التاسع عشر ليؤرِّخ للدولة العثمانية ويُقدِّمها لقارئ اللغة العربية، وهو بشكلٍ عام يميل إلى السرد التاريخي بعيدًا عن النقد والتحليل، إلا فيما ندر.\nورغم أن هدف مؤلِّفه محمد فريد بك كان الاستقواء بالدولة العثمانية في مواجهة الاحتلال الإنجليزي لمصر، لكنه يبقى كتابًا تاريخيًّا ممتازًا؛ إذ إن المؤلف دقَّق في معلوماته، وضمَّنه نصوص المعاهدات والاتفاقيات التي ترجمها من اللغة التركية.\nوقد رصد محمد فريد طبيعة تحول السُّلطة وممارستها في الدولة العثمانية، بدايةً من تحديد سُلطة الصدر الأعظم وضرب العُملة من الذهب والفضة، وتحويل الجيوش إلى نظامية منضبطة، بعد أن كانت تُستدعى وقت الحرب من القبائل.\nكما أشار المؤلف إلى بداية تلقيب سلاطين آل عثمان بخلفاء المسلمين، حيث بدأها السلطان عبد العزيز في القرن التاسع عشر، كمحاولةٍ للتغلب على ضعف الدولة العثمانية واهتزاز صورتها، بهدف تكتيل الرأي العام واستغلال انتشار المسلمين حول العالم.\nويرصد الكتاب كذلك قيام الدولة العثمانية بمنح الدول الأورُبية امتيازات لم تكُن سوى هِبات سُلطانية ومِنح لها عوائد ماليَّة ضخمة على حساب الدولة وشعبها دون مقابل يُذكر سوى الصداقة والمحبة!\nاسم المؤلف :- محمد فريد بك \nسنة النشر :- 2023\n\nتقديم وتعليق خالد عزب", "/images/products/9789777953993.webp", "9789777953993", "تاريخ الدولة العلية العثمانية", null, 485m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 766, "عزت القمحاوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا تكفي المهارة وحدها لكتابة رواية أو طهو  طبق جيد، لابد من النار؛ ولو لهب شمعة في قلب الكاتب والطاهي. \nفي هذا الكتاب يضع عزت القمحاوي شغفه بالكتابة والطهو. يعتقد أنهما توأم، وكانا في البدء عملًا أنثويًّا، لهذا يظل الكاتب الرجل بحاجة إلى تأنيث روحه؛ إلى تعلم التواضع والصبر والحيلة عبر الطبخ.\nيتأمل القمحاوي مهارات البناء في الطبق والكتاب، ويقارن نتائج «العجن واللت» في المخبوز والمكتوب. ويحاول كشف الغش الذي يمارسه بعض الكُتَّاب والطهاة بتصعيد الدسم والملح والحار. ويحتفي بأعمال المهرة من الأدباء: نجيب محفوظ، مارسيل پروست وبورخيس. ومن الطهاة: إميريل لاجاسي، جيمي أوليفر، ونادية حسين. ويعود دائمًا إلى مطبخ العظمة «ألف ليلة وليلة».\nاسم المؤلف :- عزت القمحاوى\nسنة النشر :2023", "/images/products/9789777953986.webp", "9789777953986", "الطاهى يقتل الكاتب ينتحر", null, 245m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 767, "مصطفي عبيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سبع خواجات سير رواد الصناعة الاجانب فى مصر\nهذا بحث منصف يعيد قراءة التاريخ قراءة واعية ليرد الاعتبار لعظماء مروا على مصر من خلال سير سبعة من رواد الصناعة الذين أسسوا صناعات عظيمة مازال صداها قائمًا. في هذا الكتاب ستعرف حكاية البلجيكي هنري نوس، الذي أسس اتحاد الصناعات المصرية، ورحلة صامويل سورناجا رائد صناعة الطوب، وقصة إرنست ترامبلي الأب الروحي لصناعة الأسمنت، وما فعله السويسري لينوس جاش لتطوير صناعة النسيج، وسيرة اليوناني ثيوخارس كوتسيكا إمبراطور السبرتو، فضلًا عن بصمات جوزيف ماتوسيان على صناعة السجائر، وما أحدثه الكونت دي زغيب في صناعة المربى. هو عمل غير معتاد من باحث جاد، بلغة جذابة شيقة يصحح انطباعًا خاطئًا يتصور كل أجنبي مستغلًّا. \nإبراهيم عيسى\nهذا الكتاب يمثل نقطة تحول ومراجعة لدور الأجانب في الصناعة ويجعلهم أعمدة أساسية في هذا التحول، بل إن الكتاب يجعل من سيرة هؤلاء الرواد جزءًا من تاريخ مصر وليس جزءًا من تاريخ بلادهم، وهذا منهج صحيح بلا شك، بل إنهم أهم من أن ننظر إليهم كمستثمرين أجانب عابرين ولكنهم جزء أصيل من المجتمع المصري الكوزمبوليتاني..\nمحمود عبد الشكور\n اسم المؤلف :- مصطفى عبيد \nسنة النشر :- 2023", "/images/products/9789777953900.webp", "9789777953900", "سبع خواجات", null, 245m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 768, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ولكنها لم تستسلم طويلًا لهذه الدوامة الهائلة من الخواطر الممزقة التي تمر بها سحب الجراد على الشجرة الخضراء لتتركها جرداء يابسة.. وأحست بنفسها تقاوم خواطرها كأنها تقاوم تيارًا جارفًا لا قبل لها به.. وانكفأت على وجهها تضرب وسادتها بكفيها وتضرب الفراش بقدميها وكأنها تطرد من حولها فئة من الشياطين  اجتمعت عليها لتقودها إلى بحر الجنون.\nوانتفضت واقفة، وأخذت تروح وتجيء في غرفتها وأقدامها لا تكاد تستقر على الأرض كأنها تخطو فوق لسع النار.. ثم وقفت أمام مرآتها.. ونظرت إلى نفسها طويلًا..\nاسم المؤلف :- احسان عبد القدوس \nسنة النشر :- 2023", "/images/products/9789777953979.webp", "9789777953979", "اين عمرى", null, 185m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 769, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«وقال محروس وهو يتنهد كأنه يتحسر:\n- والله لم يكن على بالي هذا الكار.. الخير كان كثيرا ولكن أولاد الحرام لم يرحموا.. كل شيء ضاع فماذا أفعل.. لم أجد إلا هذا الكار.. لم أجد إلا أن أسرق.. السرقة للمحتاج حلال!..\nوقال مرتضى ساهما:\n- العالم كله سرقات.. اللي فوق يسرق اللي تحت.. والشاطر يسرق البليد!..».\nاسم المؤلف :- احسان عبد القدوس \nسنة النشر :- 2023", "/images/products/9789777953948.webp", "9789777953948", "يا عزيزى كلنا لصوص", null, 215m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 770, "ستانلي لين بور", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يظلُّ السُّلْطان النَّاصِر صلاح الدِّين أيقونةَ الغرب قبل الشرق؛ إذ كانت أخلاقُه من وراء سلاحه، وبذلك كانت أسلحتُه نفسُها ذات أخلاقٍ! مَلَكَ فكان العفوُ منه سَجِيَّةً، وغدا على الأَسْرَى يَمُنُّ ويَصْفَحُ. ولعلَّ أعظمَ ما كُتِبَ عنه هو ما دبَّجه ورصَّعه العلَّامة ستانلي لين بول في جنبات هذا الكتاب. تتبَّع سِيرتَه بَدْءًا من المَهْد في تِكْرِيت، فالطفولةِ وشرْخ الشباب في بَعْلَبَكَّ ودِمَشْق، فالْتحاقِه بخدمة الملك العادِل نور الدِّين محمودٍ بدِمَشْق، فمَقدمِه الدِّيار المِصْريَّة مع عمِّه أسد الدِّين شِيرْكُوه، فوزارتِه للعاضِد العُبَيْديِّ بالقاهِرَة، فسَلْطنتِه وانتصارَيْه المُؤزَّرَيْنِ على الزَّنْكيين في قُرون حَمَاة وتلِّ السُّلْطان، فتوحيدِه بلاد الشَّام – لا سيَّما حَلَب - والجَزِيرَة الفُراتيَّة، فنصْرِه العظيم المُبِين في حِطِّينٍ، ففتْحِه مدينة القُدْس وقضائه على مملكة بيت المَقْدِس الإفرنجية، ثُمَّ تصدِّيه للحملة الصليبية الثالثة وسلامِه مع الملك رِتْشارَد الأوَّل، وانتهاءً بمماته في دِمَشْق. ثُمَّ عَطَفَ قلمَه نحو دحْض أساطير غربية عن سيرة صلاح الدِّين، وإزالة ما عَلِقَ بها من أوهامٍ ولَغَطٍ. إنَّه كتابٌ كحديقةٍ مُتنقِّلةٍ، يجول بك في مَرابِع صلاح الدِّين النَّضِرَة، ويأخذ بك في دُروبه العَطِرَة. (المترجم)\nاسم المؤلف :- ستانلى لين بول \nترجمة وتحقيق وتعليق :- علاء مصرى النهر \nمراجعة : ايمن فؤاد سيد \nسنة النشر :- 2023\n\nترجمة / علاء مصري النهر", "/images/products/9789777953955.webp", "9789777953955", "صلاح الدين وسقوط مملكة بيت المقدس", null, 520m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 771, "حسين صبري", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الإسلام وتحدياته\nلأن دين الإسلام هو الخاتم للدين كله، وآخر عهد الأرض بوحي السماء، فالكيدُ لهذا الدين دائمٌ لا يهدأ، لكنه يتغير ويتحور ويتفنن في أساليب الهدم والتشكيك والتعطيل لأكمل رسالات السماء، وكل كيد للإسلام هو تحدٍّ؛ تارة يمرق هذا الكيد إلى نصوص الوحي القرآني ليطعن في حقائقه ووقائعه ووجوه إعجازه، وتارة يبتغي الأذى برسول الإسلام في سنته وسيرته وإنسانيته ونبوته، فإن لم يستوف غرضه عرج إلى نظم الإسلام وحضارته وإنجازاته للتسفيه منها وتفتيتها والحط من قدرها، فإذا لم يفلح انطلق هذا الكيد إلى أهل هذا الدين القيِّم من جموع المسلمين (وهذا أشد الكيد وأعظم التحدي) ليصيبهم بالسوء في عقولهم أو هويتهم أو تدينهم أو أخلاقهم، مثلما ينتشر الآن.\nـــــــــــــــــــــــــــــــــــ\nالدكتور/ حسين صبري؛ أستاذ الفلسفة الإسلامية، صاحب خبرة تربوية في ثلاث دول عربية هي مصر والجزائر والإمارات لأكثر من أربعين عامًا في التدريس والبحث العلمي، له أبحاث علمية عديدة منشورة في المؤتمرات الدولية وفي المجلات المحكمة، له خبرة في تأليف المناهج التعليمية والإشراف على الرسائل العلمية الفلسفية والكتابة والنشر في مجالات الشعر والقصة القصيرة وفي تنفيذ دورات تدريبية لتنمية مهارات التفكير العليا وتطبيقات البحث العلمي. من كتبه المنشورة في الفلسفة الإسلامية: روّاد الشك المنهجي، رؤية الله في الإسلام، بناء الوعي، من الإرادة إلى الإصلاح، إنسانية محمد ﷺ، والإسلام وتحدياته. وفي التنمية البشرية: بتفكيري أنا إنسان، عتبات التميز، فن إدارة الوقت. وفي الأدب العربي: ديوان عناقيد السهر، ومجموعة (الأقنعة) القصصية، وفي مناهج البحث: مهارة البحث العلمي.\nاسم المؤلف :- حسين صبرى \nسنة النشر :- 2023", "/images/products/9789772937691.webp", "9789772937691", "الاسلام وتحدياته", null, 80m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 772, "سيدني سميث", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يمثل سيدني سميث استنساخًا حقيقيًّا لجوزيف بيل، طبيب الجراحة بأدنبرج الذي استوحى منه آرثر كونان دويل شخصية شارلوك هولمز.\nكيث سيمبسون. كبير الأطباء الشرعيين في لندن\nلقد وجد سيدني سميث في مصر حقلًا نموذجيًّا لمختلف الجرائم نتيجة تنوع أساليب القتل.\nتوماس راسل. حكمدار البوليس في القاهرة 1918-1946\nبين العظام، والأشلاء المجهولة، وفوارغ الطلقات حكايات مدهشة عن القتل، ترسم إرث قابيل الذي يطارد البشرية إلى الأبد. وفي سيرة الطبيب الشرعي الإنجليزي سيدني سميث (1884-1969) جانب من جرائم غامضة حقق فيها طلبًا للحقيقة، وسعيًا للعدالة، جرى معظمها في مصر خلال النصف الأول من القرن العشرين، وكانت اكتشافاته سببًا للوصول للجناة مثلما حدث في قضية ريا وسكينة، وغيرها من القضايا المرعبة التي تمكن من فك غموضها.\nاسم المؤلف :- سيدنى سميث \nترجمة :- مصطفى عبيد \nسنة النشر :- 2022\n\nترجمة مصطفي عبيد", "/images/products/9789777953924.webp", "9789777953924", "قارئ الجثث", null, 315m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 773, "دعاء الشريف", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يطرح الكتاب قضية التربية والتنوير من منظور جديد يستجيب لضغوط العصر وشروطه، فيقتحم بنا عوالم الـ«ما بعد» مركزًا على حركة ما بعد الحداثة التي قوضت الدعائم الفكرية التي استندت إليها الحداثة، مؤسسة لعقل جديد يقوم على النسبوية واللا يقين في عالم تعصف به تكنولوجيات جامحة، وتتزعزع مكانة الإنسان فيه، وتضيق فيه الفجوة بين الإنسان والآلة، وتلوح في الأفق تباشير ظهور جيل جديد مختلف.\nإذ يبدأ بالطواف بنا بمختلف مراحل تطور الفكر التنويري منذ نشأته في إطار زخم الفكر الحداثي وقواعده العقلانية الصارمة، وقوانين المادية التاريخية، والاندفاع الرأسمالي استجابة لمتطلبات المجتمع الصناعي الناشئ، ويعرض الكتاب لكل ذلك في تجلياته الفلسفية والمعرفية والتربوية والعوامل التاريخية التي شكلته.\nوتظهرأهمية هذا الكتاب في تأسيسه لرؤية تنويرية للتربية العربية، وذلك من خلال خطوتين:\nالأولى: يعرض فيها ما قام به رواد التنوير من الحداثيين المصريين منذ أكثر من قرن من الزمان محاولًا إعادة بعثه لعله يشع نورًا يضيء السبيل للجيل القادم.\nوالثانية: يطرح رؤيته التنويرية للتربية العربية التي شملت تأسيس نسق للقيم المعرفية وخصائصها، وترسيخ العقلانية والعقل النقدي والمعرفة العلمية، وبناء الهوية المتفتحة والمستجيبة للتغير في إطار من الحرية، والابتعاد عن الإرهاب الفكري والتعصب.\nاسم المؤلف :- دعاء الشريف \nسنة النشر :- 2023", "/images/products/9789777953931.webp", "9789777953931", "التربية تنوير", null, 365m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 774, "رمضان عبد اللطيف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بُنيت القصة الرئيسية لهذا العمل على أحداث حقيقية من حياة المشاركين في حرب القوقاز، الذين تركوا جبالهم بسبب مرارة الهزيمة، فقد انتقل المؤلف إلى سرد القيم الإنسانية الأساسية المشتركة للمهجَّرين من أوطانهم: الوطن الأم، الحنين إلى الديار، الحقيقة، الحب، النبل والشجاعة حتى ارتقى بأسلوبه الفلسفي في سرد أحداث روايته.\nيتعاطف رمضان عبد اللطيف (أو \"رامازان عبد اللطيبوف\" كما يحب أن يُنادى) بإخلاص مع معاناة أبطال الرواية وإرادتهم القوية وتعطشهم للحياة. كما صوَّر شخصياته بشكل مميز في لغة سردية رائعة مع الحفاظ على أصالة أدب القوقاز والشرق القديم.\nهذه الرواية للمهتمين بأحداث القوقاز التي استمرت لمئات السنين.\nرمضان عبد اللطيف: اُنتخب بالإجماع رئيسًا لجمهورية داغستان سابقًا في الفترة من 2013 حتى 2017، ولد في عام 1946، وعمل أستاذًا مساعدًا في كلية الفلسفة بجامعة سانت بطرسبرغ، وعضو الدوما (مجلس النواب الروسي)، وسفيرًا فوق العادة والمفوض الروسي في جمهورية طاجيكستان. حصل على العديد من الجوائز السياسية، منها وسام الشرف، ووسام الصداقة، ووسام الاستحقاق أمام جمهورية داغستان.\nاسم المؤلف :- رمضان عبد اللطيف \nترجمة :- محمد حاج حسين بن يونس \nسنة النشر :- 2022\n\nترجمة محمد حاج حسين بن يونس", "/images/products/9789777953917.webp", "9789777953917", "مخطوطة المهاجر", null, 165m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 775, "ولاء كمال", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في أرض الأقحوان العجيبة يولد طفل باسم غريب… \"سيد\"، ومع ولادته تتحقق النبوءة بانكسار لعنة الكسل حين تستجيب الحيوانات لصراخه… وتخرج من الغابة المقدسة منحنيةً أمامه... فينقذ بذلك أهالي مدينته من الموت. \nولكنها مجرد البداية...\nفي روايته الأكثر اختلافًا يواصل ولاء كمال بجرأته الأدبية المعهودة استكشاف عوالم روائية متنوعة وخصبة، ليأخذنا هذه المرة في رحلة خيالية تستلهم تراث الفانتازيا الثري، من رسائل إخوان الصفا وألف ليلة وليلة إلى تولكين ورايدر كيبلينج، ليقدم لنا عملاً قد تخدعنا بساطته الممتعة من النظرة الأولى.. ولكنه كعادة الكاتب يحمل مستويات عدة من القراءة والرمزية.. لنكتشف بانتهاء صفحات الرواية أن مغامرات سيد وأصدقائه المثيرة بين أراضي الكون السبعة تدعونا للتفكير والتأمل بقدر ما تثير الدهشة والإعجاب.\nاسم المؤلف :- ولاء كمال \nسنة النشر :- 2022", "/images/products/9789777953887.webp", "9789777953887", "سيد والعصابة", null, 275m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 776, "مجدى مصطفي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لم تكن أمراض القلب وتصلب الشرايين معروفة في العالم، وكانت نسبة الوفاة بسبب القلب لا تتعدى %0.5 في عشرينيات القرن الماضي وكلها لأمراض صمامات القلب وليست الشرايين، وأصبحت النسبة %30 في خمسينيات القرن نفسه وكلها بسبب شرايين القلب. فما السر وراء هذا التغير الكارثى؟ تفاصيل السر ستجدها في هذا الكتاب؟\nهذا الكتاب هو سباحة ضد التيار القوي الذي تقوده توصيات جمعيات القلب الأمريكية والأوروبية والمحلية، فالتوصيات مستمرة لأنها تحقق مصلحة ممولي الجمعيات العلمية من تكتلات شركات الدواء العملاقة وشركات صناعة الأغذية والمشروبات العالمية.\nالكتاب يشرح بالدلائل العلمية الموثقة براءة الكوليسترول من هذه التهمة، كما يوضح لماذا فشلت كل أدوية خفض الكوليسترول في تقليل نسب الوفاة بسبب شرايين القلب، وبالدلائل أيضا يعرِّف بالأسباب الحقيقية لحدوث تصلب الشرايين وكيف نتفادى حدوثها وكيف نشخصها مبكرا وكيفية العلاج الصحيح من خلال روشتة غذائية صحية وحركية.\nاسم المؤلف :- مجدى مصطفى \nسنة النشر :- 2022", "/images/products/9789777953863.webp", "9789777953863", "الكوليسترول المتهم البرىء", null, 185m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 777, "محمد أحمد جاد المولى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تعد هذا الكتاب للأستاذ محمد أحمد جاد المولى، وقد أصدر من كتابه ثلاث طبعات، أولها سنة 1391 م، وثانيها سنة 2391م، وثالثها سنة 7391، ويدل توالي الطبعتين الأولى والثانية على ذيوع الكتاب وانتشاره، وقد حوت الطبعة الثالثة تغييرات كثيرة وإصلاحات واسعة على الكتاب، وضمّن فيه الكثير من الآراء والتقريظات التي وردته.\nولأهمية هذا الكتاب التي لم يطوها الزمن اضطلع الدكتور حسام عبد الظاهر بتحرير طبعته الثالثة ودراستها لتمكين الأجيال الجديدة من الوقوف على سيرة النبي ﷺ بشكل واعٍ شامل بلغة جميلة أدبية وعقل متأمل كبير.\nالكتاب جاء في ثلاثة عشر بابًا بدأ بفضائل النبي محمد ﷺ الذاتية والاجتماعية، ثم تحدث عن الأسباب الاجتماعية التي اقتضت بعثته ﷺ، وعرَّج الكتاب في حياة محمد ﷺ تفصيلًا، ثم ختم بإدحاض بعض المفتريات عليه وعلى الإسلام وذِكْر موجز للسيرة النبوية بلغة بليغة رائقة عذبة.\nمن أكثر أدبيات التراث الإنساني انتشارًا واستمرارًا عبر التاريخ ولعلها من أكثرها إلهامًا للشعوب والمجتمعات وبخاصة القديمة منها، فإننا لا نجد مجتمعًا من المجتمعات القديمة إلا ويزخر تراثه الشفهي والمكتوب بعدد وفير من الأساطير.\nفي هذا الكتاب يقدم مؤلفه -قدري قلعجي- تسع قصص تاريخية، لتسعة  مجتمعات وحضارات مختلفة، بعضها أساطير وبعضها قصص أدبية أو قصص أطفال والبعض الأخير حكايات خرافية وأطلق عليها جميعًا أساطير. غير أنه أعاد صياغتها بلغة معاصرة وسهلة، حتى لا تكون مجرد ترجمة لهذه القصص القديمة.\nوقد شرح المحقق الأسطورة من خلال المداخل اللغوية والفلسفية والنفسية والتاريخية، وغيرها من المداخل التي تساعدنا على فهم وتعريف الأسطورة، والفرق بينها وبين الحكاية الشعبية والقصص الأدبي. كما اهتم بتعريف ثقافة الحضارات والمجتمعات صاحبة تلك الأساطير؛ فالأساطير ليست نتاج خيال فردي أو حكمة شخص بعينه، بل هي ظاهرة جمعية تعبر عن أفكار الجماعة وتأملاتها وحكمتها وخلاصة ثقافتها.\nوقدري قلعجي هو صحفي وكاتب ومفكر، ولد بسوريا عام 7191، وتوفي عام 6891، عمل صحفيًا في لبنان، ورأس مكتب \"دار الهلال\" المصرية. من أهم أعماله \"أبو ذر الغفاري\"، \"إبراهيم لنكولن\"، والكتاب الذي بين أيدينا وقد صدر عام 1491.\nاسم المؤلف :- محمد احمد جاد المولى \nسنة النشر :- 2022", "/images/products/9789777953825.webp", "9789777953825", "محمد صلى الله علية وسلم المثل الكامل", null, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 778, "السيد الباز العريني", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحققت الوحدة الإسلامية زمن صلاح الدين الأيوبي، بفضل ما أفاده من جهود سابقيه، وبما أسهم به هو وأسرته في بناء هذه الوحدة، وبفضل إدراكه ما للخلافة من قوة روحية في تحقيق غرضه. يضاف إلى ذلك ما التمسه من الوسائل في كسب الأنصار بما بذله من الإقطاعات، وبما اتصف به من العفو عن أخطاء خصومه، وبما جرى عليه من التزام أحكام الدين في سياسته، فضلًا عما اشتهر به من السخاء والمروءة.\nعلى أن صلاح الدين لم يقلل من خطورة خصومه الصليبيين بل إنه أدرك أنه للتغلب عليهم لا بد من جمع كلمة المسلمين، وتنظيم الجيش والأسطول، وتوفير الموارد المالية، والقيام بإصلاحات اقتصادية وإدارية شاملة.\nوأفاد صلاح الدين من تجاربه في قتال الصليبيين، ومن التيارات السياسية المختلفة التي أثرت في أوضاع الصليبيين، وفي كشف عوامل ضعفهم، فاستمر على تشجيع تجارة المدن الإيطالية، واستطاع بذلك أن يحصل على ما يحتاجه من أدوات الحرب والقتال، وأن يمنع الصليبيين من استخدام جانب من السفن الإيطالية في نقل الجنود إلى الشرق الأوسط.\nوعلى الرغم من الحروب الداخلية، التي نشبت بين أفراد البيت الأيوبي بعد صلاح الدين، وبرغم ما تعرضت له أملاك الأيوبيين من أخطار خارجية، مصدرها المغول والصليبيون، فإن ما اتخذه صلاح الدين من الوسائل لإقامة الوحدة الإسلامية، أفاد منها أخلافه من الأيوبيين، ومن جاء بعدهم من سلاطين المماليك في قتال الصليبيين والمغول.\nاسم المؤلف :- السيد الباز العرينى \nسنة النشر :- 2022\n\nتحقيق وتعليق مصطفي وجيه مصطفي مراجعة وإشراف أيمن فؤاد سيد", "/images/products/9789777953894.webp", "9789777953894", "الايوبيون", null, 275m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 779, "تحرير", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ومضت أيامي وأحلامي تتحقق، وظلت أمي رمانة الميزان وصمام الأمان في حياتي، ورغم تعلقي بأمي إلا أن قوة داخلية كانت تجذبني إلى حياة الرهبنة، أتوق إليها، أرغبها بكل جوارحي، وحينما استشعرت أمي هذا الأمر، خاصة أنها عرضت عليَّ الزواج كثيرًا، قالت لي: «لو تريد أن تترهبن فلتفعلها ولا تؤجل الأمر»، وكانت هي العبارة الفاصلة وطوال الرحلة من الطفولة والشباب والدراسة والرغبة في الرهبنة وخدمة الكنيسة مرورًا بكوني راهبًا إلى أن وصلت لأسقف، لم أكن أسعى أو أتخيل أن أكون بطريرك الكنيسة، حتى إن أمي كانت تُشفق عليَّ من هذا الأمر الجلل، إلى أن أصبحت بطريرك الكنيسة القبطية العظيمة، وأنا أضع نفسي في خدمة الكنيسة وشعبها ووطني مصر.\n *** \nمحبة الله، ومحبة الوطن، ومحبة الإنسان، هي الأساسيات التي نشأنا عليها في الأسرة والمدرسة والكنيسة.\nوهذه الصفحات التي بين يديك -عزيزي القارئ- هي رحلة في فترة زمنية هامة في تاريخ مصر، كانت حوارًا امتد بالساعات، وصار كتابًا فيه رؤية وطنية لأهم أحداث تلك الفترة ..\nاسم المؤلف :- البابا تواضروس \nتحرير :- شيرين عبد الخالق \nسنةالنشر :- 2022\n\nشيرين عبد الخالق", "/images/products/9789777953870.webp", "9789777953870", "البابا تواضروس الثانى سنوات من المحبة", null, 525m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 780, "نهى داود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تزوجت \"نجية\" منذ خمسة عشر عاما ثم لم تر زوجها سوى ليلة الزفاف. ولكن هذا ليس موضوعنا الآن، فعند قدميها جثة يجب التخلص منها سريعا، وتاجر الأعضاء لا يبدي التعاون المعتاد.\nفي هذه الرواية، نلتقي بامرأة حائرة أمام جثة متحللة، ثم لا تلبث أن تظهر جثة ثانية، ثم ثالثة.. ونتساءل نحن، أهو مجرم طليق؟ أم هي محاولات امرأة يائسة للتشبث بالحياة؟\nما بين أوراق \"نجية\" وذكرياتها المشوشة، وبين التقرير الصحفي الذي تعده عنها صحفية شديدة الهشاشة، وبين التحقيق الجنائي الذي يقوده ضابط المباحث الغاضب دائما، وبين أياد الشر المتوارية خلف الستار، تدور هذه الرواية.\nاسم المؤلف :- نهى داود \nسنة النشر :- 2022", "/images/products/9789777953856.webp", "9789777953856", "جثتان والثالثة عند قدمى", null, 250m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 781, "السيد الباز العرينى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«لقي النظام الحربي عند المسلمين شيئًا من الاهتمام عند مؤرخي الغرب من مستشرقين وغير مستشرقين، فظفرت الدولة العثمانية كما ظفرت الدولة المملوكية بقسط من هذا الاهتمام، دون أن تنال الفروسية المملوكية حظها من الدراسة مع العلم بأنها محور النظام المملوكي كله.\nوليس هذا البحث سوى محاولة لتكوين صورة واضحة للأسس التي قام عليها نظام الفروسية المملوكية وما طرأ عليها خلا عصر سلاطين المماليك ( 0521م-7151م ) من تغيير وتعديل.\nوتناول هذا البحث دراسة الأوضاع التاريخية في الشرق الأوسط في القرن الثاني عشر الميلادي، وشرح العناصر التي تألف منها الجيش المملوكي، ووصف حياة المملوك منذ أن جلبه تاجره إلى مصر حتى تحرر بعد أن فرغ من دراسته بالطباق وغدا فارسًا. يضاف إلى ذلك ما ورد في هذا البحث عن العوامل التي تحكمت في مستقبل الفارس وموارده والعلاقات التي تربطه بأستاذه وزملائه في الرق والعتق والتربية والخدمة وأهمية ذلك كله في قوة نظام الفروسية وضعفه».\nاسم المؤلف :- السيد الباز العربى \nترجمة :- خالد عزب \nسنة النشر :- 2022", "/images/products/9789777953832.webp", "9789777953832", "المماليك", null, 200m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 782, "جمال أبو الحسن", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الخوف والقلق صاحبنا منذ ظهور أول كائن بشري قبل حوالي 300000 عام.. الخوف صنع قصتنا! \n وجدنا أنفسنا أمام شفرات غامضة تتغلغل في كل شيء حولنا على الكوكب، وفي الفضاء الشاسع، وفي داخل أجسادنا وأدمغتنا.. رأينا العالم كما لم يره أي كائن آخر، وسعينا لكسر الشفرات واختراع أخرى تمكننا من العيش معًا.\n هكذا صنعنا أكثر الأشياء تعقيدًا في الكون: المجتمع المكون من أدمغة بشرية!\n روّضنا الحيوان والنبات.. ثم كان علينا أن نروّض أهم بطل في قصتنا: أنفسنا!\nبزغت المدن والدول والإمبراطوريات الكبرى.. ولكن كان كل شيء ينهار فجأة كبيتٍ من ورق الكوتشينة!\n نحن لا نسعى فقط للبقاء، وإنما نُطارد الخلود. رحلتنا سوف تأخذنا إلى أكثر الأماكن غموضًا: إلى داخل أدمغتنا، وإلى ما وراء عالمنا!\n إنها قصتك، وقصتي، وقصة كل إنسان عاش، أو يعيش على الأرض.. قصة البشر كما رويتُها لابنتي في عشر رسائل.. من بداية الكون وحتى بدء التوحيد الإبراهيمي.\n المؤلف :- جمال ابو الحسن\nسنة النشر :- 2022", "/images/products/9789777953801.webp", "9789777953801", "300,000 عام من الخوف", null, 315m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 783, "نهاد ابو القمصان", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا كتاب عن الحب، ليس بمفهومه الرومانسي الحالم المُحلِّق في فضاء الخيال، ولكن بمنطقه النابع من العقل، والمستند إلى العِشرة والتفاهم والهدف المشترك.\nومن خلال حكايات هذا الحب، تتناول المحامية المعروفة نهاد أبو القمصان قصة زواجها من المحامي والحقوقي الراحل حافظ أبو سعدة، منذ التقته لأول مرَّة في كلية الحقوق فأحبَّته بعقلها قبل قلبها، ثم معركتها التي خاضتها في ظل رفض والدها الزواج من «الشاب بتاع السجون» كما كان يُطلق عليه!\nإنها رحلة مثيرة خاضها شابَّان جمع بينهما الحب العاقل، والرغبة في تحقيق النجاح، والحلم بغدٍ أفضل.\nوبعد أن فقدت زوجها - ومُعلمها - اكتشفت معاني جديدة لمفردات كانت تسمعها أو تُرددها من قبل ولا تُدرك معناها الحقيقي، فأدركت أنها لم تفقد زوجًا، بل أكثر من ذلك بكثير.\nنهاد أبو القمصان لا تتحدث في هذا الكتاب عن زوجها الراحل فحسب، ولكنها ترصد مرحلة مهمة مرَّت بها مصر، ومرَّ بها المصريون، وتلقي الضوء على كواليس أحداث شهدت مولد أول حركة حقوقية في مصر، وذلك عَبْرَ سيرة رجل عشق مصر وظل حتى آخر لحظة في حياته مخلصًا لها.\nاسم المؤلف :- نهاد ابو القمصان\nسنة النشر :- 2022", "/images/products/9789777953849.webp", "9789777953849", "حكايات الحب", null, 270m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 784, "قدري قلعجي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تعد الأساطير من أكثر أدبيات التراث الإنساني انتشارًا واستمرارًا عبر التاريخ ولعلها من أكثرها إلهامًا للشعوب والمجتمعات وبخاصة القديمة منها، فإننا لا نجد مجتمعًا من المجتمعات القديمة إلا ويزخر تراثه الشفهي والمكتوب بعدد وفير من الأساطير.\nفي هذا الكتاب يقدم مؤلفه -قدري قلعجي- تسع قصص تاريخية، لتسعة  مجتمعات وحضارات مختلفة، بعضها أساطير وبعضها قصص أدبية أو قصص أطفال والبعض الأخير حكايات خرافية وأطلق عليها جميعًا أساطير. غير أنه أعاد صياغتها بلغة معاصرة وسهلة، حتى لا تكون مجرد ترجمة لهذه القصص القديمة.\nوقد شرح المحقق الأسطورة من خلال المداخل اللغوية والفلسفية والنفسية والتاريخية، وغيرها من المداخل التي تساعدنا على فهم وتعريف الأسطورة، والفرق بينها وبين الحكاية الشعبية والقصص الأدبي. كما اهتم بتعريف ثقافة الحضارات والمجتمعات صاحبة تلك الأساطير؛ فالأساطير ليست نتاج خيال فردي أو حكمة شخص بعينه، بل هي ظاهرة جمعية تعبر عن أفكار الجماعة وتأملاتها وحكمتها وخلاصة ثقافتها.\nوقدري قلعجي هو صحفي وكاتب ومفكر، ولد بسوريا عام 7191، وتوفي عام 6891، عمل صحفيًا في لبنان، ورأس مكتب \"دار الهلال\" المصرية. من أهم أعماله \"أبو ذر الغفاري\"، \"إبراهيم لنكولن\"، والكتاب الذي بين أيدينا وقد صدر عام 1491.\nاسم المؤلف :- قدرى قلعجى\nسنة النشر :- 2022", "/images/products/9789777953818.webp", "9789777953818", "اساطير الامم", null, 140m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 785, "أحمد الشهاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقتحم أحمد الشهاوي مجهُولًا جديدًا في مُغامرة الكتابة، يُجَرِّبُ تَرْسَانَةَ العِشق التي أَثْرَاهَا طويلًا بِمدَّخراتٍ وافرة، ويخرُجُ إِلينا بنَصٍّ روائيٍّ – هذه المرة – فيه الكثيرُ من رُوح البحث، والكثيرُ من خزائنِ السَّفَر، والكثيرُ من المحكيات والتفاصيل والشَّذرات الشِّعرية، والكثيرُ من الجرأة والكثيرُ من الشَّفافية، والكثيرُ من الحفر، والكثيرُ من الاستعادة، والكثيرُ من التَّوَاضعُ أَمام بَذَخِ العَالَم وسِحْر اللغة الذي يتَدَاخلُ مع سِحْرِ الآخرين.. وسِحْرِ الواقع الذي يُنْتجُ الأَلَم والفقدان.\nفي هذا النَّصِّ السَّرْدي البِلَّوري، يضعُ الشَّاعِرُ السَّاردُ أوراقَهُ فوقَ الطَّاولة كاشفًا عن أَسراره الظليلة، عن شذراتٍ من حياتِهِ، من ذاكرته، من قراءاته، من مسموعاته، من رحلاته، من صَداَقِاته. يكادُ القارئ الخَبيرُ يرسُمُ للكاتب \"بروفايل\" من خلال مَجْرى الأحداث وتعالُقِ الشخصيات وعُرْيِ الأمكنة الشخصية، البعيدة والقريبة. كأنَّ ضَوْءَ نهارٍ يَتَدلَّى، في هذا العمل الروائي الذي أحببتُه على جدار الليل\". حسن نجمي\n• المؤلف :- احمد الشهاوى\n• سنةالنشر :- 2022", "/images/products/9789777953795.webp", "9789777953795", "حجاب الساحر", null, 275m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 786, "حسام بدراوي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"إنني أؤكد على المتعة البالغة التي ‏شعرت بها عند قراءة فصول من الكتاب تمر بالميتوكوندريا والكروموسومات ‏والوعي والتصوف وفيزياء الكم، ‏وتربط بين جسم الإنسان وجسم المدينة.\nوأخيرًا ‏وليس آخرًا، ‏كانت مفاجأة جميلة أن أكتشف أن الدكتور حسام فنان موهوب بالإضافة إلى قدرته على الكتابة بأسلوب يتميز بالسلاسة ويجمع في عبارات سهلة موجزة بين سعة المعرفة وعمق العلم وبين وضوح المعنى.. إنه السهل الممتنع. ولكن لوحاته الفنية تضعه في صحبة عدد من الكتاب والأدباء والفلاسفة الذين عبروا عن مشاعرهم أيضًا بالرسم والتصوير مثل ويلم بليك (1827-1757) وخليل جبران (1931-1883) وآخرين.\nختامًا، ‏علَّي أن ‏أهنئ الدكتور ‏حسام على هذا الكتاب الممتع، و‏الذي يدعو إلى المزيد من التفكير في موضوعاته المتعددة ‏في حوارات مع الذات قبل أن تكون مع الآخر، وهي دعوة يستجيب لها كل من يؤمن بقيمة تفعيل العقل وإطلاق العنان للخيال ‏في تطوير عالمنا ومجتمعاتنا إلى الأفضل\". إسماعيل سراج الدين\nالمؤلف :- حسام بدراوى\nسنة النشر :- 2022", "/images/products/9789777953764.webp", "9789777953764", "دعوة للتفكير", null, 155m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 787, "مينا عادل جيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو هناك جزيرة  كل سكانها توائم ملتصقة؟ على جزيرة للتوائم الملتصقة تقع في مكان ما وزمان ما، كل أبطالها يبحثون عن شيء ما. يأخذنا الكاتب عبر أحداث ذات طابع أسطوري مليئة بالسخرية والتشويق وشخصيات لاتنسى نعيش مغامراتهم في البر والبحر ليطرح اسئلة ملحة عن ماهية الوجود الإنساني. والشعور بالوحدة، وكيف يمكن للإنسان أن ينفق عمره بحثًا عن السعادة الكاملة. أحداث تبدو مضحكة في ظاهرها بينما فيما يحمله معناها شيء يستحق التوقف والتأمل. ابتكر الكاتب في جزيرة إلخ إلخ عالمًا خرافيًّا متكاملًا مستقلًّا؛ له ثقافته ودينه وتاريخه وسياسته وجغرافيته واقتصاده وأحلامه، بطريقة كلام مختلفة، والاهتمام بصغائر الأمور لا بكبائرها والمصيري منها. جزيرة إلخ إلخ هي نافذة على أرواحنا المختبئة، عدسة مكبرة لما يحدث داخل رؤوسنا من ازدواجية وهواجس ومخاوف وعبث في بعض الأحيان.\n• المؤلف :- مينا عادل\n• سنة النشر :- 2022", "/images/products/9789777953788.webp", "9789777953788", "جزيرة الخ الخ", null, 200m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 788, "ميرنا الهلباوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه الصفحات كتبتها لي قبل أن أكتبها لك. أرجو مِن كل مَن سيقرأ ألا ينتظر من هذه الصفحات عِبرة، أو تنظيرًا، أو رواية، أو حدوتة.  هو مجرد تفريغ لمشاعر عشوائية مختلطة متفرعة ولكنها كُتبت من نفس الجرح. لا تنتظر من هذه الصفحات أن تجعلك تنسى، لن ننسى. هذه الصفحات إليّ وإلى كل من جُرح، إلى كل من يجرح، إلى كل من سيُجرَح.  هذه الصفحات كي لا تشعر أنك تعاني أو عانيت وحيدًا.. هذه الصفحات كي لا أشعر أنني عانيت في صمت.  هذه الصفحات تحتوي على الكلمات والمشاعر التي لم أستطع صياغتها في جمل مفهومة وقتها. هذه الصفحات تؤكد أنه على الرغم من اختلافنا لكننا متشابهون تمامًا.  هذه الصفحات كتبتها حتى تنذكر ما تنعاد..\n• المؤلف :- ميرنا الهلباوى\n• سنة النشر :- 2022", "/images/products/9789777953771.webp", "9789777953771", "تنذكر ما تنعاد", null, 220m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 789, "رؤوف غبور", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أحد ابرز رموز الاعمال والصناعة في مصر والعالم العربي . هو مؤسس مجموعة شركات \"جى بي اتو\". طريقة حافل بالإنجازات والمصاعب والدورس. نجح في التغلب على أزمات كبرى .                                                                                                                     درس رءوف الطب في جامعة عين شمس وتخرج فيها عام 1976، واتخذ قراراً مصيرياً ، ترك الطب واتجه للتجارة والأعمال. عمل لسنوات في شركة العائلة \" إخوان غبور \" إلى أن وصل لمنصب العضو المنتدب للشركة، واستطاع في هذهالمرحلة أن يتخطي بالشركة صعوبات عديدة.      \nفي عام 1990 استقال رءوف من \" إخوان غبور \" وبدأ التركيز في نشاط شركاته واستثماراته، وتوسع في مجالات عديدة: تجارة السيارات والإطارات وقطع الغيار والموتوسيكلات والتوك توك والشاحنات والأتوبيسات والمعدات الإنشائية والزيوت. وفي مرحلة لاحقة أنشأ مصانع لتجميع السيارات وصناعة المكونات وهياكل الأتوبيسات والموتوسيكلات والتوك توك. وبسبب الظروف الاقتصادية التي مرت بها مصر خلال هذه الفترة تعرضت شركاته لأزمة مالية عنيفة كاد بسببها أن يعلن إفلاسه لكنه واجه هذه الأزمة بأفكار ابتكارية لا تخلو من جرأة ومغامرة.\nهنا في مذكراته ( خبرات و وصايا ) يتعمق في هذه المسائل بأسلوب سهل وممتع وجريء . كما يكتب بالتفصيل عن ظروف حبسه لأكثر من ستة أشهر في قضية رفض أن يشي خلالها بموظف حكومي نظيف اليد ومظلوم.\nيشرح غبور هنا محطات مهمة في حياته، وصولاً لمرحلة مرضه التي تناولها بكل رضا وتسليم، وكأنه فارس نبيل قرر أن يتعالى ويسمو بروحه عن الآلام والأوجاع، لكي يصل الى خط النهاية وهو منتصر، قوي، ورأسه للسماء.\n• المؤلف :- رؤوف غبور  \n• سنة النشر :- 2022", "/images/products/9789777953733.webp", "9789777953733", "مذكرات رؤوف غبور خبرات و وصايا", null, 440m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 790, "لنا عبد الرحمن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا العمل الروائي، تنتقل الكاتبة بين عصور مختلفة في أسفار زمنية سريعة، من مصر مع آلارا الفرعونية إلى القاهرة المعاصرة، ومن جبل لبنان في الستينيات مع ميري، إلى حكاية جدتها آني في أذربيجان مطلع القرن العشرين، مرورًا بما حدث مع رحمة في بغداد، وشمس الصباح في أشبيلية وفاس. بين الماضي والحاضر والمستقبل تحضر الحرب، ويهيمن الحب والفن على حيوات بطلات الرواية، في صراع أزلي، تمضي كل منهن في مسارها وارتحالها من مدينة إلى أخرى، بحيث تنعكس الأقدار والمصائر على مرايا الذاكرة، فتسعى \" زينة\" الآتية من الغد وراء نداء مجهول لكي تستعيد ماضيًا سحيقًا تحدسه ولا تدركه. تقدم الرواية أيضًا إشارات للزمن المستقبلي بكل ما فيه من مخاوف في علاقة الإنسان مع التكنولوجيا، وما تحمله من مخاطر تقلص من حضور المشاعر الإنسانية لصالح الآلة. سنة النشر : 2022 المؤلف : لنا عبد الرحمن", "/images/products/9789777953726.webp", "9789777953726", "تميمة العاشقات", null, 200m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 791, "حسام بدراوي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "التقيت بصديقي العزيز الدكتور حسام بدراوي، وعلمت منه أنه في الوقت الذي انشغلتُ فیه بموضوع «الجمهوریة الجديدة» وبدأت أتحدث فیه علنًا، انتهى هو من كتابٍ يتفاعل مع الموضوع نفسه، هنَّأته ورحَّبت بكتابه وقُلت له: «كم أود الاطلاع على نقاشٍ جادٍّ لتلك الفكرة التي أطلقها الرئيس عبد الفتاح السيسي والتي تستحق أخذها بالجدية نفسها التي تحدث بها الرئيس»، كنت متوقعًا أن یُركز فیه على التعليم، ولكني وجدت في قراءتي السريعة الأولية نظرة شاملة إلى مضمون هذه الجمهوریة، وإسهامًا متفردًا في طرحها طرحًا سلیمًا قائمًا على حوارات مع الشباب باعتبار أن المستقبل هم أصحابه. عمرو موسى *** عندما رفع السيد رئيس الجمهورية شعار «الجمهورية الجديدة» أيقن الدكتور حسام بدراوي أن صفحة جديدة في تاريخ مصر يُمكن أن تُفتح ويتعين على النخبة أن تُشارك على الأقل بالرأي في وضع أُسسها وتشكيل سماتها. وفي هذا الكتاب، يدعو د. حسام بدراوي كل الوطنيين، بل وكل صاحب فكر ورؤية ورأي للمشاركة في مناقشة هذا الطرح ونقده. منير عبد النور                                 سنة النشر :- 2022             المؤلف :- حسام بدراوي", "/images/products/9789777953740.webp", "9789777953740", "حوارات مع الشباب", null, 165m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 792, "لوتس عبد الكريم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أنا بطبيعتي قلقة ومُتوجِّسة، وأخشى الحَرْفَ على الورق؛ لأنَّ الكتابةَ أمرٌ مقدَّسٌ بالنسبة لي. وأنا منذ عرفتُ الكتابةَ، وأنا أبحثُ عن السَّهل العميق، والبسيط الدَّال، من دون إخلالٍ أو  مرورٍ عابرٍ على الفكرة التي أتناولها. لا أحبُّ الكتابةَ إلا عمَّن أعرفُ، وأومنُ، وأعتقدُ من أفكارٍ ورؤى. فكُنتُ قريبةً وصديقة لأبرز وجوه الكِتابة والأدب والموسيقى والغناء في مصر، وقد كتبتُ عنهم في كتابيَّ \" سيرتي وأسرارهم\"، و\"عاشوا معي\"، ومن قبلهما كتابي الأساسي \" رحلة البحث عنِّي .. رواية حياة \". ويأتي كتابي \"ما يشبه السيرة\" ليكملَ سلسلة كُتبي في أدب السيرة الذاتية للآخرين عبر صلتي بهم، و كنتُ قريبةً ممن كتبتُ عنهم، وبعضهم لم  تسمح لي حياتي بأن أعرفهم، لكنَّني عشتُ في ظلال ما أبدعوا من فنونٍ وآداب، وقدَّموا أشكالًا جديدة واختراقات أدبية غير مسبوقة. إنَّ ذاتي في هذا الكتاب تصفُ نفسها، مثلما تصفُ الآخرين الذين رافقوا رحلتي الحياتية والثقافية، ولذا سمَّيته \"ما يشبه السيرة\" لي ولهم. \"ما يشبه السيرة\" هو كتابٌ يمزج بين سيرتي والسيرة الغيرية للآخر الذي أنتمي إليه أو ينتمي هو إليَّ، الذي كتبتُهُ مُنطلقةً من  وجهة نظري الشخصيّة، مُتحليةً بالموضوعية من دون تجنٍّ أو انتقاصٍ ما؛ لأنَّ الكتابةَ في هذه الحالة تتحوَّلُ إلى نوعٍ من  أنواع التاريخ، كما أنها شهادتي عن نفسي، وعن هؤلاء.\nالمؤلف : لوتس عبد الكريم\nسنة النشر :2022", "/images/products/9789777953696.webp", "9789777953696", "ما يشبه السيرة", null, 150m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 793, "مصطفى النشار", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب يتناول واحدًا من أهم الأطروحات الفلسفية حيوية بوجه عام وأهمها على الإطلاق وهي الفلسفة القديمة عمومًا، واليونانية خصوصًا، فهو يركز على أحد جوانب مشروع المؤلف الفكري، وهو إثبات أن للحضارات الشرقية فلسفات وفلاسفة سبقوا نشأة الفلسفة عند اليونان. ومن ثم يساهم ذلك في دحض ما يسمى بالمعجزة اليونانية في نشأة الفلسفة، ويؤكد أن الفلسفة كأي نشاط فكري آخر للإنسان قديمة قدم وجوده، وأنه لم يوجد منذ بدء وجوده على ظهر الأرض إلا ليتساءل، أي ليفكر، وكان أهم مظاهر هذا التفكير، التفكير الفلسفي في أصل الوجود، وأصل الكون وما وراءهما، وطبيعة الإنسان ومصيره. ولقد جاء هذا الكتاب أيضًا ليؤكد أن الفلسفة طبعت في كل عصر من عصورها بخصائص هذه الحقبة أو تلك من حقب التاريخ الحضاري للإنسان، ومن ثم فقد اختلفت صورة التفكير الفلسفي وتأملات الإنسان الفلسفية وتطورت حسب تطور حياته من عصر إلى آخر، وأن كل واحدة من الحضارات الإنسانية الفلسفية الكبرى ظهرت وتميزت بخصائص فكرية معينة. وكان المفكرون والفلاسفة هم دائمًا قادة الفكر ورواد الإبداع في كل العصور، بل هم من صنعوا بأفكارهم وتأملاتهم ومذاهبهم الفكرية الفارق بين عصر وآخر، وهم من أيقظوا الناس وقادوهم إلى كل القفزات الحضارية الكبرى عبر التاريخ الإنساني.\n المؤلف : مصطفى النشار\n سنة النشر :2022", "/images/products/9789777953603.webp", "9789777953603", "مدخل الى فلسفات الشرق القديم", null, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 794, "محمد الشحات", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يؤسِّس هذا الكتاب منهجيّته الخاصة عبر ممارسة أربع مقاربات نقدية متضافرة؛ أولاها اعتماد اللابنية أو اللامركز كمنطلق لعمليّات التحليل الثقافي، ثانيتها مقاربة المتون الأدبية ثقافيّا، ثالثتها الممارسة النقدية الحرّة التي تبحث عن سياقات طازجة لبناء دوائر التأويل، رابعتها تأكيد النبرة الذاتية للناقد من خلال الهوامش الثقافية المكتنزة. لا يمثّل كتاب (خارج المنهج) هروبًا من حدود المناهج النقدية أو خروجًا على تقاليدها أو تعاليًا على أطروحاتها. ولا يعني ذلك كونه ضدّ المنهج أو ضدّ النظرية أو ضدّهما معًا، لكنّه كتابٌ نقديٌّ يقف موقفًا مضادًّا لكل حَرْفيّة نظرية أو شكلانيّة منهجية ستغدو عاجلًا أو آجلًا سجنًا لغويًّا واصطلاحيًّا يؤدّي إلى المزيد من عُزلة الناقد (العربي) عن مجتمعه وثقافته وتاريخه. (خارج المنهج) حوارٌ متّصلٌ بين ذات الناقد وموضوعه الذي هو جزء منه؛ حوارٌ بين العالم والنصّ الذي يتعاطى الناقد من خلاله مع خطاب العلوم الإنسانية بوصفه خطابًا بينيًّا وثقافيًّا يجب أن يحتلّ موقعه من حركة التاريخ والمجتمع\n المؤلف : محمد الشحات\n سنة النشر :2022", "/images/products/9789777953689.webp", "9789777953689", "خارج المنهج", null, 275m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 795, "ضحى عاصي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«ظل الصياد جالسًا ساعات طويلة يفكر ماذا يفعل الآن؟ ماذا يفعل بعروسة البحر بعد أن اصطفته هو لتقع في شباكه؟!.. عروسة البحر.. عروسة الأساطير، ليست امرأة ليحبها ويتزوجها، وليست سمكة ليشويها ويأكلها. وبكل محبة وحسرة احتضنها، وبكل ألم الفراق ألقى بها مرة ثانية في البحر. والآن نقدح كأسينا ونشرب هذا الكأس في صحة الأحلام الكبرى التي يبدو تحقيقها مستحيلًا، ولكنها إذا جاءت لنا وتحققت نكتشف أنها لا تناسبنا؛ فنتركها بمحض إرادتنا»\nالمؤلف : ضحى عاصى\n سنة النشر :2022", "/images/products/9789777953641.webp", "9789777953641", "صباح 19 أغسطس", null, 225m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 796, "إبراهيم عبد المجيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بين الروايات والكتب ونوستالجيا المكان يعرّج بنا الكاتب إبراهيم عبد المجيد في أزمان متباينة، وقوالب نشر مختلفة، وإبداعٍ يتباين من مقال لآخر، فيجد القارئ نفسه بين التعجب لما يحكيه عن نفسه أيام المدرسة والشباب: أهكذا كانت حياة هذا الجيل؟! وبين الانبهار لما وصل إليه، ومَن قابله، ومَن حاوَره، وما قرأه من كتب بلغاتها الأصلية، وما كشف عنه من إبداعات ومبدعين مسكوت عنهم.. ويظل القارئ هكذا متنقلًا بين قسم وآخر في الكتاب؛ تعلو وتيرة اهتماماته، وتتغير رؤيته للأمور، ويسعى للسير على الخطوات نفسها لهذا الكاتب الكبير. وقد ضم الكتاب مقالات نُشِرت في صحف ومجلات مصرية وعربية كالنهار العربي والقدس والأخبار المصرية وأخبار الأدب والمصور والعربي الكويتية وديوان الأهرام ومجلة فنون ومجلة الفيصل والمصور المصرية وبعض المواقع الإلكترونية، مقسمة إلى أقسام تدور متقاربة من موضوع واحد بصرف النظر عن مكان وزمان النشر.\n\n المؤلف : ابراهيم عبد المجيد\n سنة النشر :2022", "/images/products/9789777952528.webp", "9789777952528", "رسائل إلى لا أحد", null, 275m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 797, "توبياس بيك", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"المتذمر المزمن\" هو المصطلح الذي يطلقه توبياس بيك على الأشخاص السلبيين الذين يحيطون بنا طوال الوقت. في هذا الكتاب الفريد، يشرح مدرب ومحاضِر التنمية الذاتية الأول في ألمانيا جميع السمات التي نستطيع من خلالها التعرف على الشخص السلبي، ويساعدنا على إدراك خطورة السلبية التي قد تحيط بنا من كل جانب: في أفراد العائلة، الأصدقاء، زملاء العمل، وحتى أنفسنا! ولا يكتفي الكاتب بإظهار الآثار المدمرة التي قد تصيبنا نتيجة التواجد بالقرب من المتذمر المزمن، ولكنه يضع لنا حلولًا عملية للتخلص منه! يتميز هذا الكتاب التفاعلي بابتعاده عن كل القوالب التحفيزية المستهلكة لكتب التنمية البشرية، حيث يحكي الكاتب بأسلوب سلس وممتع عشرات القصص التي تحمل عدة قيم إيجابية كالرضا ومساعدة الآخرين، وكيف يمكننا السعي بشكل فعَّال نحو تحقيق النجاح والتوازن اللازمين للتمتع بالسعادة في الحياة.\n المؤلف : توبياس بيك\n سنة النشر :2022\n\nترجمة/ ولاء كمال", "/images/products/9789777953702.webp", "9789777953702", "ابتعد عن المتذمر المزمن", null, 250m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 798, "مهدي مبارك", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"لمح مهدي ما لا يمكن أن تلمحه غير عين رحيمة بالعناء البشري، فكانت الهند السرمدية أمامه رحابا «يتنافس فيه الأتباع، لكن لا أحد يخرج من أرض «الآلهة والخرافات» خائب الرجاء». لكن العين الرحيمة ذاتها لم يمكنها أن تكون متجاهلة لنقيض ذلك مما جرته حداثة الأيام على هذا الرحاب العريق العتيق، فلمح الوثنية المستجدة، وثنية توابع رأس المال العالمي وأشباحه الذين يسوقون جحافل البشر في إدارة طواحين حداثة ما بعد الإنسانية وعبادة الآلهة الجدد التقنيين في دلهي المتخمة بالفقر والمليارديرات، من جانب، ومن جانب آخر عباد أصنام تحويل الإيمان إلى احتراب بشري يمول بتجارة الحشيش وتفخيخ أضرحة أولياء الله. وبين هذا وذاك كان هناك من يموتون بثمار جوز الهند التي تقع على رؤوسهم من قمم نخلاتها الشواهق. ودعارة البؤس وفنادق الأرصفة، وبنات الديسكو اللائي يخبئن ملابس قصيرة يرتدينها حين يدخلن ويغيرنها حين يخرجن\".\n المؤلف : مهدى مبارك\n سنة النشر :2022", "/images/products/9789777953658.webp", "9789777953658", "البحث عن شاروخان - 40يوما في الهند", null, 185m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 799, "إسعاد يونس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب يأخذ قارئه ببراعةٍ ونعومةٍ إلى زمنٍ جميلٍ، تميَّز بأحداثه، وأشخاصه، وآماله، وحتى مآسيه وإحباطاته؛ وذلك عَبْرَ اثنتين وعشرين حكاية مُدهشة، ترويها إسعاد يونس «الكاتبة»، بقُدرات وموهبة وتفرُّد إسعاد يونس «الفنانة» المُبدعة، وبحضور وبساطة إسعاد يونس «الإعلامية»، صاحبة الأسلوب المتميِّز في تقديم برنامجها «صاحبة السعادة». وتتنوَّع حكايات الكتاب بين قصصٍ حقيقيَّةٍ، تنقلها الكاتبة بأسلوبها الخاص، الذي «يُضفِّر» العاميَّة بالفُصحى؛ وقصصٍ خياليَّةٍ ترصد ظواهر اجتماعية انتشرت في فترتي الثمانينيات والتسعينيات من القرن العشرين، فضلًا عن حكايات تدور في إطار فانتازي، تُلقي الضوء على بعض سلبيات المجتمع المصري، ترويها الكاتبة بأسلوبٍ مشوِّق، يجعل القارئ مشدودًا للأحداث من أوَّل كلمةٍ لآخرها.. وتنزعه ببراعةٍ من الواقع الذي يعيشه؛ لتدخل به إلى عالم الحكاية المدهش.\n المؤلف : اسعاد يونس\n سنة النشر :2022", "/images/products/9789777953665.webp", "9789777953665", "في استقبال فخامة الرئيس", null, 200m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 800, "مني الدغيدي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "منى الدغيدي الشهيرة بالست أم آسر وإسلام وساعات بأبقى نوني ومازي وتوتا، اتولدت في بورسعيد وعشت في القنطرة وزي ما بيقولوا ترعرعت في المحروسة واتحبيت في لندن ودرَّست في نيچيريا وحبيت في إسكندريه وعشت في السويس وبكده أبقي غطيت خط الكنال كله واتغربت في بلاد الأناضول واستقريت في أبو ظبي وبعد اللفة دي كلها رسيت على بر مصر المحروسة.\n المؤلف : منى الدغيدى\n سنة النشر :2022", "/images/products/9789777953672.webp", "9789777953672", "نونى وحكاويها", null, 275m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 801, "عمار علي حسن", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"جلس الشيخ بين مريديه شاردًا، مغمض العينين. قال بعضهم: الشيخ يسري إلى السماء ويعود. قال آخرون: إنه يخاطب كائنات من عالم آخر، لا يسمعها غيره. حين فتح هو عينيه قال لهم: أجاهد كل ليلة، لأستعيد لحنًا شجيًا، يسكن نفسي منذ سنوات بعيدة، لكنه يروغ مني\". \"كلما أنصَتَ إلى وجيب قلبه، سمع صرخات أبيه التي كانت تفزعه صغيرًا، وصرير القلم على ورقة الامتحان، وزعيق بوق عربة الشرطة، وضربة سوط سجان مكابر، وثغاء ماعز صغير انفرد به ذئب جائع في حقلهم ذات ليلة بعيدة، ونفضة يده التي تخرج خاوية من جيبه بعد نفاد راتبه الضئيل. مع هذا كان عليه أن يَطمئنَّ إلى نجاته من وعيد ما بعد الموت\". *** هذا كتاب سردي، يحوي مقامات صوفية جديدة، تجمع بين تجليات روحية، وأوضاع اجتماعية، وتأملات فلسفية، وأذواق أدبية، وأحوال نفسية، وطقوس دينية، وظروف سياسية. إنه نص عابر لأنواع الكتابة، لا يمكن تصنيفه على مستوى الشكل، لكن مضمونه يمكن وصفه، في سهولة، بأنه تعبير طبيعي عن شوق الإنسان إلى المحبة والحرية والعدل والسكينة، في مجتمع يتوحش.\nالمؤلف : عمار علي حسن\nسنة النشر :2022", "/images/products/9789777953634.webp", "9789777953634", "مقام الشوق", null, 250m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 802, "سعيد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما الذي يشير إليه مفهوم «علم الجمال الإسلامي»؟ ما هو المقصود هنا بصفة «إسلامي» التي يُفترض أنها تضيف شيئًا جديدًا إلى مفهومنا عن «علم الجمال»؟ هل المقصود هنا هو الإشارة إلى أننا يمكن أن نجد علمًا للجمال أو حتى إرهاصًا بنظرية جمالية في تراث الفكر الإسلامي، أي الفكر الذي أبدعه المسلمون؟ أم أن المقصود هو أننا يمكن أن نستمد هذا العلم من رؤية جمالية متضمنة في القرآن الكريم دستور المسلمين؟ الواقع أننا نجد كلا الاتجاهين في الكتابات المعاصرة الدائرة حول مفهوم أو قضية علم الجمال الإسلامي. فإن كان الاتجاه الأول في طرح القضية هو المقصود، فإنه اتجاه أو أسلوب مشروع في طرح القضية، أعيى أنه يكون من حيث المبدأ قابلاً للنقاش الذي يمكن أن يُظهِر لنا مدى صدق أو كذب مزاعمه. أما إذا كان الاتجاه الثاني في طرح القضية هو المقصود، فهو أسلوب غير مشروع من حيث المبدأ ومتناقض ذاتيًّا. وسنبرهن على موقفنا من هذين الاتجاهين أو الأسلوبين في طرح القضية. يقدم لنا هذا الكتاب رؤية تحليلية نقدية تكشف عن الخلط بين المفاهيم في الكتابات الدائرة حول ما يُسمَّى \"علم الجمال الإسلامي\"، وتكشف في النهاية عن جذور هذا الخلط التي تكمن في ضلالات الوعي الديني الشائعة في وعينا الثقافي، وهي ضلالات تختزل في الدين رؤيتنا للعالم والعلم والفن، بل هويتنا نفسها.\n المؤلف : سعيد توفيق\n سنة النشر :2022", "/images/products/9789777953627.webp", "9789777953627", "تهافت علم الجمال الإسلامي", null, 155m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 803, "عزت القمحاوي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مثلما تتشابك أغصان الشجر في الغابة والأيكة، تتشابك فنون الكتابة وموضوعاتها في هذا الكتاب: من التأمل الفلسفي إلى رصد الظواهر الاجتماعية إلى الحكاية، في سرد يستهدف إنعاش الحواس. تتوالى فتنة الأصابع، غوايات الصوت، روائح الحب، بهجة الاستحمام؛ المدخل الضروري للعبادة والمقدمة المستحبة للرغبة. وتتعدد أماكن الاحتفاء بالحب؛ من السينما حيث خفة الوجود، إلى المطارات ومحطات القطار التي تُذكِّر بهشاشة الإنسان ومحدودية العُمر. وقريبًا من ذلك يأتي تأمل الألفة في تخطيط المدن وجماليات العمارة الحنون بشرفاتها التي تخلق الصلة بين ساكن البيت والعابر، وعلى الضد منها تخطيط وعمارة الريبة. ولا نغادر قبل أن نتعرف على الفنون المحتفلة بالحواس: الطبخ وأطعمة الغواية، الأزياء بوصفها منتجًا اجتماعيًّا، الرقص الشرقي ومعاني ملابسه وحركاته، الفيديو كليب، والفوتوغرافيا وولع الصورة السيلفي. وهكذا، تمتد طرق «الأيك» المتشعبة أمام القارئ لاكتشافها ومواجهة التيه اللذيذ فيها، من دون مخاطر الضياع!\n المؤلف : عزت القمحاوى\n سنة النشر :2022", "/images/products/9789777953559.webp", "9789777953559", "الايك في المباهج والأحزان", null, 215m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 804, "أحمد الشهاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتابُ يسهمُ في إعادة بنائِك، وتنظيم رُوحك من جديدٍ، يرتِّب غرفَ قلبك، ويجعله يذهبُ حيثُ الـحُب الذي يقودُ الإنسانَ نحو الصَّفاء والارتقاء. فما الـحُبُّ العذريُّ إلا تصوفٌ أو طريقٌ إليه. وما الـحُبُّ إلا مقامٌ إلهيٌّ؛ لأنَّ المحبَّة أصلُ المقامات والأحوال، وأكمل مقامات العارفين. والذات العليا للإله تتمثل  في الـحُب، وبالمحبة يقتربُ الإنسانُ من الله. وفي الـحُبِّ يُعوِّلُ المرءُ على القلبِ أكثر مما يُعوِّل على العقلِ، فالـحُبُّ الصُّوفيُّ  أصلُ وجُود الـحُبِّ في العالم؛ لأنه مظهرٌ للحُب الإلهي؛ إذ إنَّ الـحُبَّ بطبيعته أصل الموجودات، والمتصوفة هم أهلُ المحبَّة ويُنسبون إليها. والـحُبُّ عند المتصوف أسلوب حياة، ودليل المعرفة الصوفية التي تعكس حال القلوب السامية. أحمد الشهاوي في هذا الكتاب يقدِّم الـحُبَّ الصوفي بلغةٍ شعريةٍ سهلةٍ وفهمٍ عميقٍ، مختارًا سلاطينَ للوجد أحبَّها وعاشَ مع آثارها الخالدة زمنًا طويلًا، من بينهم ذو النون المصري، وأبو بكر الشبلي، والنِّـفَّرِي.\nالمؤلف : احمد الشهاوى\nسنة النشر :2022", "/images/products/9789777953610.webp", "9789777953610", "سلاطين الوجد", null, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 805, "نهى داود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أرى أطيافًا... زوجي يعتبرني مجنونة، ماذا عنك.. هل تصدقني؟\" في هذه الرواية تخرج نهى داود عن المألوف في كتاباتها الواقعية لتقدم للقارئ خلطة شيقة تمزج فيها الواقع بالخيال. بطلة الرواية هي \"صفاء\" القاطنة بالعقار 47 والتي عانت مع الاكتئاب المرضي لسنوات وتكافح للتعافي من أجل زوجها وأبنائها. تقع صفاء على خاصية جهنمية تمكنها من كشف المستور. وما أن تبدأ باستخدامها محمومة حتى تقع جريمة مروعة في الشقة المقابلة لتفترش الأرض بالدماء. فهل تنجح صفاء في استخدام خاصية \"الأطياف\" للكشف عن غموض الحادث؟\nالمؤلف : نهى داود\nسنة النشر :2022", "/images/products/9789777953597.webp", "9789777953597", "جريمة العقار 47", null, 225m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 806, "فيصل دراج", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحاول هذه الدراسة النفاذ إلى فلسفة نجيب محفوظ الروائية، التي تميّزت بنظر ثابت، نسبيًّا، إلى العالم وبأشكال متغيّرة دائبة التطوّر. تُستهل قراءة النص المحفوظي بمداخل ثلاثة تضيئه تقنيةً وفلسفةً معًا: السلطة، المفارقة، والصدفة. رصد هذا النص الوجود الإنساني في وجوهه الأساسية المتمثّلة في: رعب الزمن ودلالة الموت، وفي ذلك \"السرّ\" الذي يعاني منه الإنسان ولا يستطيع تفسيره. أفضت هذه الوجوه إلى مقولة استقرت في ثنايا عالم محفوظ الروائي، عنوانها الأكبر: \"الشر\" في مراتبه المتعددة، التي تحايث الوجود كله وعوالم الإنسان المتنوعة. حاولت هذه الدراسة قراءة رواية محفوظ في استقلالها الذاتي، المحدّد النظر والبدايات والنهايات، واستُكملت القراءة بمقارنتها بإنجازات روائية عالمية، مثل رواية ديستويفسكي، الروسي الذي جمع بين الرواية والفلسفة، كما رواية توماس مان الألماني الواسع الثقافة، وتأملات الفرنسي أندريه بلزاك الذي كان مشدودًا إلى إخفاق الإنسان وهزيمته. وبداهة فإن محفوظ، المتعدد والمتجدّد معًا، لم يكن يحاكي أحدًا، بقدر ما كان يحقق حوارًا نوعيًّا بين العوالم الروائية الكبرى، التي تبدأ بالإنسان المغترب وتنتهي به. طوّر الروائي المصري الرواية العربية وهو يطوّر روايته، وطوّر روايته خلال خمسين عامًا، ومر بأشكال روائية مختلفة: الرواية التاريخية، ورواية النهج الواقعي، والرواية الرمزية، ورواية التجريب الطليق التي لم يحاولها غيره. كتب دائمًا ما يريد منفتحًا على آفاق لا تقبل بالانغلاق، وخلَّف وراءه موروثًا روائيًّا واسعًا لا يمكن النظر إلى تاريخ الرواية العربية من دونه، ولا يكون الناظر إلى الرواية العالمية عادلًا إن لم يتوقف أمام رواية نجيب محفوظ المصرية والعربية والكونية في آن.\n المؤلف : فيصل دراج\n سنة النشر :2022", "/images/products/9789777953573.webp", "9789777953573", "الشر والوجود", null, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 807, "صلاح فضل", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بدأت رواية الأرض (1953) لعبد الرحمن الشرقاوي بنقد صورة القرية كما تجسدت في المهاد القصصي السابق عليها، لتعلن بداية حقبة جديدة من التمثيل الجماليّ للحياة، طبقًا لشروط انعكاس الواقع فيها، يقول الراوي الصبيّ في المطلع: «كنت وأنا أجلس على الساقية أسترجع ما قرأت في الصيف.. كنت أسترجع دائمًا كتاب الأيَّام وإبراهيم الكاتب وكنت أرى في قريتي أطفالًا عديدين أكل الذباب عيونهم كالقرية التي عاش فيها صاحب الأيام، وتمنيت لو أن قريتي كانت هي الأخرى بلا متاعب كالقرية التي عاشت فيها «زينب» والفلاحون فيها لا يتشاجرون على الماء، والحكومة لا تحرمهم من الريّ ولا تحاول أن تنتزع منهم الأرض، أو ترسل إليهم رجالًا بملابس صفراء يضربونهم بالكرابيج،... وكانت النساء في قريتي يحملن الجرار كنساء القرية التي عاشت فيها زينب، وكانت لهنّ أيضًا نهود، ومن بينهنّ وصيفة ضاحكة ريَّانة، منعّمة بيضاء ممتعة تثير الخيال أكثر مما كانت زينب في الكتاب الذي قرأته ولم أجد فيه مأساة قريتي». اسم المؤلف :- صلاح فضل                                                  سنة النشر   :- 2022", "/images/products/9789777953542.webp", "9789777953542", "التمثيل الجمالي للحياة في الروايات العربية", null, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 808, "سماح أبو بكر عزت", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مغامرات شيقة وممتعة لفتى في الثانية عشرة من عمرة يتلقى رسالة غامضة بها عدة رموز، فيحاول في مغامراته تلك فهم ما تعنيه تلك الرموز. وفي رحلاته عبر الزمن يقابل علماء أجلاء بقي أثرهم إلى هذا الزمان بسبب تساؤلاتهم ودهشتهم أمام الظواهر التي لاحظوها، فنقابل مع بطل هذه الرحلة «نيوتن» فنعرف منه سر التفاحة، وماذا تعني الجاذبية الأرضية؟ ونقابل «ابن الهيثم»، فنفهم كيف تعمل أبصارُنا، وكيف استفادوا من مفهوم انعكاس الضوء في تصنيع الكاميرا. وفي إحدى رحلاته قابَل العالِم الفيزيائي «رونتجن» ليفهم منه سر المفتاح الموجود في الرسالة الغامضة، فإذا به يعرف ونعرف معه كيف تم اكتشاف الأشعة السينية، والتي بسببها تم اكتشاف خبايا جسم الإنسان!! اسم المؤلف :- سماح ابو بكر عزت سنة النشر :- 2021\n\nرسوم ضحى الخطيب", "/images/products/9789777953382.webp", "9789777953382", "رحلة الى قارة الدهشة", null, 185m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 809, "نهلة كرم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعد أن تخرج الراوية من علاقة سامة،  تستدعي أحداثًا وتفاصيل، وتبدأ في ربط كل ما كان يحدث بينهما بسلوكيات الحيوانات في عالمها. التشابهات المدهشة تجعلها قادرة على إعادة اكتشاف الآخر ونفسها. فتجد في هذا العالم التفسير الذي تسعى إليه لتضع كل شيء في مكانه الصحيح. كعادتها تصحبنا نهلة كرم في رحلة مؤثرة وعميقة داخل الحياة بكل تعقيداتها وبساطتها، من خلال فك تشابك العلاقات العاطفية وتحليل طبقاتها المتعددة بحس مرهف وأسلوب جذاب، لا يمكن إلا أن تذوب داخله لترى نفسك برؤية مغايرة وأكثر إنسانية.\nالمؤلف : نهله كرم\nسنة النشر :2022", "/images/products/9789777953566.webp", "9789777953566", "خدعة الفلامنجو", null, 185m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 810, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كعادتها في الآونة الأخيرة تتمرد نور عبد المجيد على منطقتها الروائية التي تفردت بها واعتلت قمتها لتخرج إلى مناطق أخرى جديدة لم يطأها قلمها من قبل. \"كـان\" رواية تناقش العنصرية والازدواجية التي تعاني منها البشرية ولا تعترف أبدًا أنها من اخترعها!! هل الحرية والسلام مقتصران على شعوب معينة؟ وهل تُترك الأوطان بحثًا عنهما؟ وماذا لو أنه بعد الجهاد والهجرة وضياع العمر نكتشف أن الأرض بأكملها ليست وطنًا لأي منهما؟! وهل حقًّا جحيم الأوطان جنة الإنسان؟! رواية تطرح الأسئلة وتغوص في أعماق أبطالها بحثًا عن إجابات حتى التاريخ نفسـه لم يستطـع تقديمهـا بشكـل قاطـع.. بين \"القاهرة\" و\"الإسكندرية\" و\"مرسيليا\" قصة بل قصص وانتصارات.. هزائم وخيبات.. لحظات من الحب وأزمان طويلة من الانتظار والندم.. ولكن ما عساها الحياة إن لم تكن كل هذا؟!\nالمؤلف : نور عبد المجيد\nسنة النشر :2022", "/images/products/9789777953504.webp", "9789777953504", "كان", null, 320m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 811, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"ثق ان بابا يعتبر مثلاً أعلى لكل منا .. أخي عبد السلام نشأ وهو يريد ان يعتمد على نفسه كما كان بابا معتمداً على نفسه .. واجتاز عدة محاولات فشل فيها كلها ولكنه ظل مصمماً على أن يعتمد على نفسه .. فلم يطلب رغم فشله أن يعمل مجرد ابن لأبي..ابن صاحب العمل .. ولكنه سافر أوروبا وعاش وقيل إنه نجح ..وقلت في هدوء كأني أواجهها بالواقع المر:\n-ولكن أخوك عبد الوهاب لم ينجح ولم يستطع حتى الآن أن يكون شيئاً!\".\nالمؤلف : احسان عبد القدوس\nسنة النشر :2022", "/images/products/9789777953535.webp", "9789777953535", "لن اعيش في جلباب ابي", null, 195m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 812, "حاتم حافظ", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه رواية تغوص داخل النفس البشرية؛ لتستخرج منها – عَبْرَ تدفُّق تيار الوعي – ذكريات هادرةً، متحدية أعطال الذاكرة التي تُصيب شخصًا أتمَّ عامه المائة، ووصل لهذه السن دون أن يمرض!\nولأنه ليس شخصًا عاديًّا، بل هو كاتب روايات عاطفية، فأمواج ذاكرته المعطوبة، تبدو مراوغة، فهو يذكر أُمَّه التي كانت تُعاني من اعتلال ذاكرتها أيضًا؛ ولكنه لا يذكر إن كان قد استأصل زائدته الدودية في سن العاشرة أم في سن الأربعين!\nولأنه كاتب رومانسي، يعيش وحيدًا، فقد كان يخشى دائمًا من أن يموت دون أن يدري به أحد؛ لذلك تحايل على الأمر بالتواطؤ، متصارعًا مع أحداثٍ تُظهرها الذاكرة فجأة ولا يذكر تفاصيلها كاملة.. لكنه لم ينسَ أبدًا أن ينام مُبكرًا؛ ليكون مستعدًّا في الصباح لكتابةٍ يُمكنها أن تمنح الآخرين أملًا لمواصلة الحياة!\nالمؤلف : حاتم حافظ\nسنة النشر :2022", "/images/products/9789777953511.webp", "9789777953511", "جيد بما يكفى", null, 150m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 813, "مصطفي عبيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ينبش هذا الكتاب في الأحداث الماضية، طارحًا قراءات وافتراضات تُساهم في تقديم رواية أخرى للتاريخ المصري الحديث، وذلك من خلال طرح تساؤلات قد تُمثل اشتباكًا جديدًا مع التاريخ الرسمي، حيث يتساءل الكاتب ـ وفق معطيات عديدة ـ حول أسطورة مصطفى كامل الوطنية، المُحمَّلة بمبالغات لرسم صورة غير حقيقية لزعيم استثنائي، ويطرح الوجه الآخر للسياسي المخضرم إسماعيل باشا صدقي، والمُعاكس للصورة السائدة في الكتابات التاريخية، فضلًا عن طرح السؤال الممنوع حول ما كان يُفترض أن يكون عليه محمد نجيب لو استمر في السلطة كرئيس لمصر، مستعينًا بآرائه وخطبه وتصريحاته التي تُنبئ عن ديكتاتور لم يأخذ فرصته!\nويُقدِّم الكتاب أيضًا اكتشافًا جديدًا حول المرأة التي قلبت حياة سيد قطب، وحوَّلته من أديب وناقد رقيق، إلى مفكر تكفيري متشدِّد..\nكما يضيف الكتاب لأول مرة متهمين جددًا في جريمة اغتيال الرئيس الراحل محمد أنور السادات، لم يشملهم قرار الاتهام، ربما لمحبة الناس لهم، أو إعجابهم الشديد بهم!\n المؤلف : مصطفى عبيد\n سنة النشر :2022", "/images/products/9789777953498.webp", "9789777953498", "ضد التاريخ", null, 250m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 814, "شريف مليكة", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه الرواية تدور حول «العشق» بمعناه الواسع، الذي يتجاوز حدود العلاقة بين الرجل والمرأة، إلى بُعد أكثر عمقًا وتنوعًا، كعشق الإنسان لربه، وعشقه لذاته، وعشق الفنان لفنه، وغيرها من حالات العشق التي قد نراها ولا نتوقَّف أمامها باعتبارها عشقًا!\nوقد رصد الكاتب في روايته حالات عشق متنوعة، مهتمًّا ومحتفيًا بالعشق، باعتباره البطل والمُحرِّك للأحداث، حتى لو كانت الحكاية تدور حول شخصيات تخطف الانتباه، مثل سيدة الغناء العربي أم كلثوم، والعندليب الأسمر عبدالحليم حافظ، وعبقري الفن المصري محمد فوزي، وبُلبل التلحين الموسيقي بليغ حمدي!\n المؤلف : شريف مليكه\n سنة النشر :2022", "/images/products/9789777953474.webp", "9789777953474", "ايام عشق", null, 165m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 815, "ريم نجمي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“تريدين أن تعرفي لمَ خسرنا تلك الحياة المشتركة، ولمَ نزلتُ من القطار في منتصف الرحلة؟ لكن المعرفة تساوي الألم. إن كشف مواطن الخلل جارح، لكنه ينقذنا من الاستمرار في خديعة أحدنا الآخر. تماما كما لو أننا نمشي في حديقة جميلة مُتشابكي الأيدي لكن قدمينا داميتان بفعل الأشواك وشظايا الزجاج، غير أن كل واحد منا يبتسم للآخر ليخبئ شعوره بالألم”.\n***\n“يوليا” امرأة خمسينية ألمانية تُصدم بقرار زوجها “عادل”، ذي الأصول المغربية، الانفصال عنها بعد مرور خمسة وعشرين عامًا على زواجهما، فتحاول استعادته وفهم أسباب اتخاذه لهذا القرار، دون أن تعرف أن زوجها يعيش قصة حب مع “جوري” وهي لاجئة سورية قدمت إلى ألمانيا هاربة من ويلات الحرب، والتي وجد فيها عادل صورة المرأة الشرقية التي كان يفتقدها.\n“تشريح الرغبة” رواية نسوية بامتياز، نجحت في كشف تناقضات رجل شرقي، وإن تعلم وعاش وارتدى زي الألمان وتحدث بلسانهم، لكنها لم تحرمه حق الدفاع عن نفسه؛ فلقد برعت “ريم نجمي” في استخدام الأصوات المتعددة بحيادية تامة من خلال رسائل متبادلة بين شخوص الرواية كأنها بأقلامهم الحقيقية.\n المؤلف : ريم نجمى\n سنة النشر : 2022", "/images/products/9789777953450.webp", "9789777953450", "تشريح الرغبة", null, 250m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 816, "إنعام كجه جي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“نشف الدم في عروقي يوم استدعيت لمقابلته. وقد كان أهون عليّ أن أقف بين يدي خالقي يوم الحساب، مثقلاً بعظيم ذنوبي وفوادح خطاياي، من أن أتواجه مع الرئيس. قال إنه قرأ قصيدة لي أعجبته. وكان يحفظ الأسطر الأربعة الأولى منها. عربدت عصافير البهجة في صدري لكنّني سرعان ما انتظرت الكارثة”.\n المؤلف : انعام كجه جى\n سنة النشر : 2022", "/images/products/9789777953467.webp", "9789777953467", "بلاد الطاخ طاخ", null, 155m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 817, "أشرف العشماوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أبطال هذه الرواية شخصيات غير تقليدية لكننا نصادفها كل يوم ، يعيشون في المسافة الفاصلة بين الحقيقة والخيال ، ظلوا صامتين حتى فك المؤلف عقدة لسانهم ليحكوا ما أرهقهم كتمانه عبر سنوات طويلة ، ما أوجعهم وما أسعدهم ، أحلامهم التي لا تحتاج إلى تفسير وطموحاتهم التي لا تُكلف الكثير . في روايته الجديدة يطرح أشرف العشماوي أسئلة مهمة حول قيمة الحقيقة وقوة تأثير الزيف على مواطنين مهمشين يحاولون الحياة ، عبر سرد شيق لبدايات مليئة بالآمال ونهايات مرتبكة ، أدت بغالبيتهم إلى عبور جسر الطموح إلى الجريمة بدافع إنساني مُضطرين . وبعد ما ظن كل منهم أنه عضو بجمعية سرية لا يدري الآخرون بأمرها ، اكتشف أنه مجرد رقم في طابور طويل ينتظر دوره ليقبض نصيبه ، لكنه يدفع للآخرين في الوقت ذاته بانتظام من سنين حياته وأيام عمره دون أن يدري .\n المؤلف : اشرف العشماوى\n سنة النشر : 2021", "/images/products/9789777953436.webp", "9789777953436", "الجمعية السرية للمواطنين", null, 250m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 818, "فادي زويل", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "E300عندما طلبت أوبر في ميونخ، جاءتني سيارة فخمة مرسيدس\n موديل السنة ولم أدفع سوى مبلغ ضئيل أجرة! سألت السائق: هل تحقق أوبر أي ربح في ألمانيا؟\nوفي لندن عاصمة الضباب أخبرتني ريبيكا عن المصري الذي يحبه الشعب الإنجليزي وتكرهه العائلة المالكة، وكيف تسبب هذا الشخص في إحراجهم أمام العالم!\nوجندي المارينز الأمريكي الذي شاهد بعينيه أفراد المخابرات الأمريكية يدفعون الأموال لطالبان بينما كان يؤمّن أحد المطارات في أفغانستان.\nفي هذا الكتاب 22 قصة من رحلاتي حول العالم تدور جميعها مع سائقي أوبر من الجنسيات المختلفة وذوي خلفيات ثقافية واجتماعية متنوعة ومركبة منهم الغني والفقير، المثقف والسطحي، المتواضع والعنصري، المهاجر والمواطن، تعلمت منها الكثير وتأثرت بها في حياتي لما فيها من دروس قيمة وعبر.\nعزيزي القارئ دعني أصطحبك في رحلة ممتعة ومشوقة حول العالم مع أوبر، فلتضع حزام الأمان وهيا بنا ننطلق\nالمؤلف : فادى زويل\nسنة النشر : 2022", "/images/products/9789777953481.webp", "9789777953481", "رحلاتي مع Uber", null, 185m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 819, "خالد عزب", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا الكتاب نكتشف بأن العمران أدى إلى نظام دائم الفاعلية في الكون بشتى مظاهره الروحية والمادية، وهو ما أفضى إلى تأسيس منظومة فكرية التحمت بالواقع عبر فضاء العمران، ففلسفة العمران أتاحت للإنسان أن يطبق معاييرها دون أن يدرك ذلك، يقوده إليها الإيمان المطلق بالله الواحد الأحد، ولأنه الواحد؛ فقد جعل بعض فلاسفة وعلماء الإسلام بداية الأعداد 2 لاختصاص العدد 1 بالله سبحانه وتعالى، وهم بذلك يردون كل شيء في الكون إليه، فالمبدع المتقن الله، سبحانه وتعالى، يسعى الإنسان إليه عبر الإيمان به، وبالتالي كان الإتقان والإبداع والعمل سعيًا للوصول إلى مبدع هذا الكون الذي جعل عمارة الأرض وظيفة الإنسان الأولى ثم بعدها عبادته.\nإن العناية الفائقة بفكرة إتاحة سبل عمارة الأرض هي التي أدت إلى نشوء علم العمران وفلسفته حتى رأينا بعضه في بطون الكتب وفي التراث المادي والشفهي للمسلمين، وقد اقترب المسلمون من هذه المثالية تارة وابتعدوا عنها تارة أخرى، فلما بعدت الهوة بينها وبين التطبيق انهارت حضارة العمران وضاع سبقهم ومجدهم وأضاعوا الدنيا بعد أن كانوا سادتها.\n المؤلف : خالد عزب\n سنة النشر : 2022", "/images/products/9789777953429.webp", "9789777953429", "العمران فلسفة الحياة في الحضارة الاسلامية", null, 200m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 820, "طالب الرفاعي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مليونير كويتي ستيني يعيش صداع علاقته بزوجته، ومعاناته بضياع ولده. وتباغته نظرة فتاةٍ عابرة، لتخطف قلبه، وتجرّه خلف عطرِها، ليعزم أمرًا يقلب حياته!\nمغامرة روائية جريئة وصادمة يخوضها الروائي الكويتي طالب الرفاعي، بإزاحة اللثام وكشف أهم القضايا الإنسانية المؤلمة، التي يعيشها المجتمع الكويتي والمنطقة العربية.\nالمؤلف : طالب الرفاعى\nسنة النشر : 2021", "/images/products/9789777953412.webp", "9789777953412", "خطف الحبيب", null, 200m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 821, "راسم محمد الجمال", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا أقرأُ النصَّ الأدبي إلى نهايته إلا إذا شدّني إليه، وجذبتني علاقاته الإبداعية إلى عوالمه، شريطة أن يحقق لي نوعًا من المُتعة. وهذا النوع من المتعة هو ما أشعرُ به وأنا أبحر في عوالم القص، مفتونًا بملامحه الذاتية أو العلاقات التي تخايلني بين عناصره التكوينية، فأترك نفسي وراء ما ألمحه من خلال هذه العلاقات التي تضيف شيئًا فشيئًا إلى متعة القراءة التي تتزايد، بل تتصاعد إلى أن ينتهي النص. ولا غرابة في ذلك، فالقص الأدبي - كالنص الأدبي – حمّال أوجهٍ، متعدد الأبعاد الظاهرة والباطنة، وكلما ازداد عمقًا، ازدادت دواله تعدُّدًا في المدلولات، وأحيانًا إلى ما لا نهاية... وقد أعاود قراءة النص مرّات ومرّات لا لشيء إلا لكي أزداد من متعة ما لم أكتشفه في القراءة الأولى التي تُغوِي بغيرها من القراءات. وحتى بعد أن أنتهي من قراءة العمل أشعر كأن شيئًا ما يدفعني إلى معاودة القراءة كي أستكمل اكتشافي للجوانب المجهولة من النص.\nاسم المؤلف :- راسم محمد\nالجمال سنة النشر :-2021", "/images/products/9789777953405.webp", "9789777953405", "ميثودولوجيا الاتصال علم البحث العلمى وتطبيقاته في الاتصال", null, 360m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 822, "عزة فهمى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يــوم مـا اتولدتْ فكرة الكتـاب ده، كنا بنحتفـل بمـرور 50 سنـة على إنشـاء (شركـة عـزة فهمـي)، وانشغـال بنـات الشركـة في إعـداد (برنامج الاحتفال) خلاني أتفزع سألت نفسي، يا خبر، 50 سنة فاتوا؟!! إمتى الأيام والسنين دول جريوا كده! حسيت إن ده آخر فصل اللي أنا داخلة عليه، هو ده المشهد الأخير في المسرحية، قلت: لازم يا بت تهدي وتقفي، وتحكي ما هو خاص بعزة فهمي (البني أدماية)”.\nهذا الكتاب يروي قصة نجاح مصرية حقيقية، استطاعت فيها “عزة فهمي” تجاوز عقبات كثيرة في حياتها، بدءًا من محنة وفاة الأب وانتقال الأسرة إلى مستوى اقتصادي أقل، ثم خروجها من روتين الوظيفة إلى اختيار “الحلي” مهنةً ورحلةً لاكتشاف الذات مرورًا بتحويل هذه الحرفة إلى مهنة فنية لها أصول صناعيـة وتطبق فيهـا قواعـد ونظـم التسويق الحديثة العالمية، وانتهاءً بأن أصبح اسم “عزة فهمي” علامة تجارية عالمية خرجت من مصر، وتحمل هوية وثقافة وتراثًا عالميًّا من حيث التصميم والحرفية والجودة.\nالمؤلف : عزة فهمى\nسنة النشر : 2021", "/images/products/9789777953399.webp", "9789777953399", "مذكرات عزة فهمي احلام لا تنتهى", null, 525m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 823, "عبير عبد الحافظ", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\" اللعبةُ الغاضبةُ هي أولى روايات الكاتب الأرجنتيني رُوبرتو آرلت، التي صَدرتْ في طبعتها الأولى عن دار نشر (لاتينا). أحدثَ ظُهور هذه الرواية نُقطة تَحوُّل فاصلة، ذلك أنَّه لأول مرةٍ تتحولُ مدينةُ بوينوس آيرس إلى مركز الحَكي على هذا النَّحو مُتخليةً عن الصورة النمطيَّة التي اعتادتْ الظُّهور بها في أعمالٍ أخرى. يُدشِّن روبرتو آرلت فضاءً سرديًّا جديدًا مُستَوحِيًا مُوتيفة أدب المهمشين لـ دوستوفيسكي، موثقًا ملامحَ البشر الخاضعين للفقر والخسران والضَّياع المُتواصل فيهيمون بِلا توقُّف في شوارع المُدُن الكبيرة على غير هُدى في محاولة مُضنيَة للبقاء. لقد وُلِدَ ليكتبَ عن شقاءِ طفولته وصباه وشبابه، فعلَ ذلك بغضبٍ وحنقٍ في آنٍ واحد، إنَّها أشياء فاضتْ وكفَّت\".  \nالمؤلف :- ربروتو ارلت \nترجمة :- عبير عبد الحافظ \nسنة النشر :- 2021", "/images/products/9789777953276.webp", "9789777953276", "اللعبة الغاضبة", null, 275m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 824, "ديدية بلوند", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“إنها قارئتي. تلك التي لطالما أملتُ في لقائها، ذات يوم. في الشارع. في مترو الأنفاق. في مقهى. هي لا تعرف أني هنا. ولا تعرف حتى مَن أكون. لم ترَني من قبل. سوى أني أملك كل أفكارها“. *** في هذا الكتاب، يأخذنا الأديب الفرنسي الكبير ديديه بلوند في جولة على مقاهي باريس، القديم منها والحديث، الفاخر والبسيط؛ جولة تتكشَّف عبرها حياة باريس النهارية والمسائية، جرائدها، أسرارها، فنانوها، بسطاؤها، حياتها السرية وتاريخها الحافل بالتحولات.. وقائع شهيرة ارتبطت بالمقاهي، روايات وأفلام دارت بين جدرانها، قصائد كُتِبت فوق طاولاتها ورسائل سُطِرت على قصاصاتها الورقية.. حكايات عشق وهجر ولِدَت وماتت فوق مقاعدها الوثيرة والمتعِبة؛ كل هذه الأوجُه لمدينة باريس، يُجمِلها بلوند بلغته الشعرية في سرد جاذب خاطف\nللإيقاع.\nالمؤلف :- ديديه بلوند\nترجمة :- احمد القرملاوى\nسنة النشر :- 2021\n\nترجمة أحمد القرملاوي", "/images/products/9789777953351.webp", "9789777953351", "كافيهات", null, 220m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 825, "خالد منتصر", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"يفزعونك حتى تصمت وتخرس، لكن «جوجل» قد انتصر، و«اليوتيوب» قد اكتسح، والشاب الآن صار بضغطة زر كيبورد يعرف في ثانية من الإنترنت ما كان يبحث عنه فرج فودة في شهر بين رفوف مكتبته. التنوير قادم لا محالة، يسير ببطء لكنه آتٍ آت، البطء والتأخير سببه أن عدد المغيبين الذين يخرجون من ماكينة التلقين الصدئة ضخم ومرعب، لكن الطوفان عندما يحدث سيكتسح ويكنس كل أصنام التخلف، وبدلًا من فرج فودة واحد سيولد مليون فرج فودة، وسنكتب في كل ذكرى له ونحييه ونقبّل جبينه، وتذكروا أن الرصاص لا يقتل المفكر، وإنما التجاهل هو الذي يقتل\". اسم المؤلف :- خالد منتصر سنة النشر :- 2021", "/images/products/9789777953344.webp", "9789777953344", "يوميات تنويرية", null, 220m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 826, "أشرف العشماوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سرقات مشروعة كتاب مذهل يرصد ظاهرة تهريب الآثار المصرية ووسائل استردادها ويحكي بالوثائق لأول مرة كيفية خروج قطع أثرية نادرة مثل رأس نفرتيتي وحجر رشيد وجداريات متحف اللوفر بباريس ومقبرة فرعونية بتورينو . وكالة رويترز للأنباء\n كتاب متفرد ستحبس أنفاسك وأنت تقرأ صفحاته المثيرة ، يحكي كاتبه من خلال موقعه كمسئول عن ملف استرداد الآثار المهربة التفاصيل المذهلة لرحلة خروج الكنوز المصرية واستردادها بأسلوب أدبي مشوق عبر أربعة فصول ممتعة للغاية. رياض توفيق/ جريدة الأهرام\n سرقات مشروعة من أهم الكتب الوثائقية التي تستعرض صفحات مجهولة من تاريخ سرقة وتهريب الآثار المصرية. قناة الجزيرة الوثائقية\n كتاب مهم يعكس تحول المجتمع المصري على مدار مائتي عام منذ بداية عصر محمد علي باشا حتى ثورة يناير. جريدة الحياة اللندنية\n • اسم المؤلف :- اشرف العشماوى\n • سنة النشر :- 2021", "/images/products/9789774277375.webp", "9789774277375", "سرقات مشروعة", null, 360m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 827, "تامر شيخون", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"انتفض العالم. دخلت اللعبة مرحلة جديدة بعدما استيقظت كل الهلاوس النائمة. فيضان الصين أغرق العالم في حوارات نهاية الكون حتى أصبح شبح الإنترنت الغامض مسيحًا لمن يتوق إليه، مهديًّا لمن يبحث عنه وبوذا لمن يسعى للسير معه على الماء. بينما أحرق لهيب الصين ما تبقى من منطق عقلاني عن الخدعة والمصادفة والمؤامرة\". *** عام 2045، هيمنت التكنولوجيا الرقمية على الأرض حتى أصبحت دينًا جديدًا لشباب تصدعت ثوابته الروحية. يحاول أستاذ التاريخ نوح جوشوا تنبيه البشر من مصير مفزع يتسلل إليهم ببطء عبر شبكة الإنترنت بينما تحارب إيزابيلا ستورم رئيسة الولايات المتحدة القوية  من أجل إحكام قبضتها على العالم الجديد. رحلة مثيرة إلى مستقبل أجيال ما بعد الحقبة الرقمية! \nالمؤلف :- تامر شيخون \nسنة النشر :- 2021", "/images/products/9789777953337.webp", "9789777953337", "شفرات القيامة", null, 300m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 828, "حسام العادلى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"نجع بريطانيا العُظمى\" عنوان لافت، فالنجع هو نجع السعداوية بالصعيد فمن أين جاء الكاتب العنوان؟ هنا تدخل في الرواية لتكتشف أنك أمام تاريخ يتمدد إلى الخلف لبدايات القرن العشرين وصراع عائلة السعداوية للفوز بالعُمُدية ثم خسارتها ولا ينفصل ذلك كله عن الوجود البريطاني والحرب العالمية الأولى والثانية حتى ثورة يوليو وما بعدها إلى 1956. كل ذلك التاريخ يتهادى ويتواتر وينفجر مع زيارة زين سليل السعداوية إلى عمه حسنين الذي صار تاجرًا كبيرًا في روض الفرج بعد أن صار كل شيء ينتمي إلى العهد البائد بعد ثورة يوليو. على ناحية، السعداوية وأعداؤها وأصدقاؤها، وعلى ناحية، مستر هاريس الإنجليزي وأصوله وزوجته وبنته، يتداخلون من أبواب السياسة والجنس والقتل والحرب وغيرها بشكل مذهل. لا يختلف الصعود هنا عنه هناك ولا النهايات. ليس بتداخل الحكايات فقط لكن بالرؤية للإنسان بين طموحه ونزواته وجرائمه فلا فرق. النجع واحد هنا أو هناك. فارقٌ أن الكتابة جعلت المكان رايتها في كل الحكي والصور بشكل مذهل عن الجنس والخيانات والاغتصاب والقتل والحب بلغة بنت المكان بأشجاره ومائه ونباتاته وطميه ورماله وعاداته. لغة من يرى.. لا من يحكي وهذا هو أجمل إنجاز للفن. هذا هو ما يجعلك تقرأ بانبهار ولا تتوقف. إبراهيم عبد المجيد اسم المؤلف:- حسام العادلى سنة النشر :- 2021", "/images/products/9789777953313.webp", "9789777953313", "نجع بريطانيا العظمى", null, 200m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 829, "عزت القمحاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عطر مريضة شابة يغمر طبيب النساء الأعزب؛ فيقلب حياته رأسًا على عقب. نظرة من امرأة في عربة ترام تصل إلى سر ما عاشته امرأة أخرى في ساعة حب. موسيقار عرف العديد من النساء وانتهى مقيدًا بسطوة امرأة يحاول الإمساك بجملة لحنها الأولى. وباحث يخسر حربًا طويلة الأمد مع الذباب، لكنه يستميت في معركة أخيرة من أجل الحب! في رواية «غربة المنازل» يتعطل الكلام؛ فيفسح مجالًا لملمس الحياة ورائحتها وطعمها وألوانها، وتبدو القراءة عملًا لكل الحواس، نكتشف من خلاله عالمًا صاخبًا بالأحلام ومعجزات الحب، تحت المظهر المخادع لهدوء العزلة الحزين. اسم المؤلف :- عزت القمحاوى سنة النشر :- 2021", "/images/products/9789777953320.webp", "9789777953320", "غربة المنازل", null, 235m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 830, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لماذا ننجب من قد لا يريدون القدوم إلى الحياة؟!  لماذا نصبح عبيدًا يطاردنا الخوف عليهم ويغتالنا الركض خلفهم لنطعمهم وننظف فضلاتهم ونرتب فوضاهم!! ننام حين يسمحون لنا بالنوم وننهض إن بكوا في وقت لا نستطيع فيه تحريك إصبع في قدم أو رمش في جفن.. نذوب من أجلهم وحين تشتد سواعدهم يروننا عبء ثقيل يجب الهرب منه! الإنجاب مسئولية لا يجب أن تريدها.. الإنجاب جريمة ليس من الحكمة أن  تود ارتكابها.. كل أطفال الأرض مرضى بعُقد آبائهم وجنون جيرانهم وخطايا أوطانهم..\n• المؤلف :- نور عبد المجيد\n• سنةالنشر2021", "/images/products/9789777953306.webp", "9789777953306", "انين الدمى", null, 300m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 831, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«وأنا طلبت إننا ننتقل من باريس.. وحاننتقل.. بكره.. بعده.. مش حاتشوفني.. حاسيبك تاني يا علاء.. حاسيبك وحبك في دمي.. حا آخدك معايا جوه عروقي.. حاسيبك لأن حبنا مايقدرش يعيش إلا جوانا.. ما يقدرش يعيش في الدنيا.. ما يقدرش يعيش على الأرض!.. وتلقي نفسها وهي واقفة فوق صدره.. ثم ترفع رأسها إليه والدموع في عينيها، ثم تقبله قبلات كثيرة سريعة، ثم تبتعد عنه وتجري.. وعلاء يصيح وراءها: ناهد.. ناهد.. ويخفت صوته، ويسقط رأسه على صدره يائسا، ويهمس: - ناهد.. ناهد..». اسم المؤلف :- احسان عبد القدوس سنة النشر :- 2021", "/images/products/9789777953245.webp", "9789777953245", "دمى ودموعى وابتسامتى", null, 250m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 832, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«وهمت زينب أن تقوم من فراشها لتعود وتستمع إلى أخبار مفاوضات السلام في محطات الراديو.. حتى لو تحقق السلام.. هل يعود ابنها إيزاك.. هل تعود ياسمين.. هل تعود هاجر؟!.. وابتسمت ابتسامة مريضة وهي تتنهد كأنها تخفف عن نفسها.. لا.. لقد تركوها وحدها.. إنها تحس بإحساس الأم إنهم لن يعودوا.. ومدت يدها تلتقط العكاز الذي تستند عليه وهي تقوم وتمشي فأفلتت منه يدها وسقطت على الأرض.. وصاحت: - نعيمة.. خضرة.. تعاليا إليّ.. وحملتها نعيمة وخضرة!..». اسم المؤلف :- احسان عبد القدوس سنة النشر :- 2021", "/images/products/9789777953252.webp", "9789777953252", "لا تتركونى هنا وحدى", null, 195m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 833, "عمار على حسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"كنت أعرف الكثير عن كبرائهم، ويا ويل من يعرف أسرار أناس يظنون أنهم قد دفنوها إلى الأبد. أسرار إن هُتكت سقطت وجوه، وانتهت أكاذيب خادعة، وضاعت الهيبة عمن يشمخون بأنوفهم غطرسة، وتغيرت أحوال كان أصحابها يتوهمون أنها راسية كالجبال. ربما تكون هذه هي التي أتت بي إلى هذا المكان الموحش، لكن كيف أعرف هذا وأنا حبيس هنا إلى أن ألقى الله؟ من يبدد هذه الحيرة التي تنهش روحي؟\". *** يعيش بطل هذه الرواية أيامًا عصيبة بعد أن دفنه أعداؤه حيًّا لتموت معه أسرارهم. كان قد أتيح له وحده معرفة الكثير عن انحلال نسائهم، وسرقاتهم التي لا تتوقف، وتجارتهم الحرام، وأفعالهم المشينة. في المقبرة يكلم الموتى، فيعرف منهم أسرارًا أكثر، تجعله راغبًا في الخروج إلى الحياة. يكافح بلا انقطاع محاطًا بالرعب والفزع، والكوابيس التي تداهمه وهو مفتوح العينين، ويغالب الروائح الكريهة، وعلامات النهاية التي تهاجمه كل لحظة. إنها ليست رواية رعب إنما حالة فنية مشوقة لها أبعـاد اجتماعيـة ونفسيـة غارقـة في الخـوف، ولا تخلو من مغزى فلسفي وسياسي عن الإنسان الذي عليه أن يصارع طويلًا في سبيل الخروج من الضيق إلى البراح. اسم المؤلف :- عمار على حسن سنة النشر :- 2021", "/images/products/9789777953207.webp", "9789777953207", "صاحب السر", null, 215m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 834, "محمد فتحى", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لِـمَاذَا يَنْظُرُ الجَمِيعُ إلَى (ريم) بطريقةٍ تُضَايقُها أحْيَانًا؟ وهَلْ سَتخْبرُ (ريم) وَالدتَهَا ومُعلمَتها بما يُضَايقُها أم ستظلُ صَامتةً؟ تَعالوا نتعرفُ علَى (ريم) ونرى لِماذا هِيَ مُختَلِفَةٌ؛ لِنعرفَ كيف سننظرُ لها حِين نُقَابِلهَا؟\nالمؤلف : محمد فتحى\nسنة النشر :2022\n\nرسوم وليد طاهر", "/images/products/9789772937653.webp", "9789772937653", "نظرة", null, 185m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 835, "على أحمد الجمل", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذه الموسوعة نتعرف على شبه الجزيرة العربية بنظرة أعمق وأشمل، من خلال البحث التفصيلي في جغرافيتها وتاريخها وحاضرها، تراثها وثقافتها ورياضاتها، وطرح الموضوعات  بأسلوب علمي وأدبي شيق. تتضمن الموسوعة معلومات عن دور أهل شبه الجزيرة العربية الفاعل والمهم، عبر التاريخ قديمه وحديثه والدور الأبرز خلال بعثة الرسول صلى الله عليه وسلم. أما من حيث الجغرافيا فتوضح الموقع المتميز بين قارات العالم وإطلالها على أهم المسطحات المائية والمضايق البحرية العالمية، كما تمدنا بمعلومات عن جبالها وهضابها وصحرائها وأثرها في التطور الاقتصادي للمنطقة، سواء قديمًا عن طريق التجارة أو حديثًا عن طريق البترول ومصادر الطاقات المتجددة وغير المتجددة. وتعد موسوعة \"عالمنا العربي بين يديك\" إضافة إلى المكتبة العربية، تثري معرفة القارئ لتصبح مرجعًا علميًّا وثقافيًّا مبسطًا من خلال العرض الشيق لدول المنطقة، مدعومًا بصور وخرائط توضيحية لما اشتملت عليه من معلومات موثوقة. ولقد اعتمد مؤلفو الموسوعة على المراجع العلمية والمصادر الإلكترونية لتقديم صورة تفصيلية ومحدَّثة وفقًا لآخر الإحصاءات الرسمية عن دول الخليج السبع: \"المملكة العربية السعودية، الإمارات العربية المتحدة، الكويت، سلطنة عُمان، البحرين، قطر، اليمن\".  وانطلاقًا من دور القراءة في تنمية المعارف للفرد والمجتمع، وتشكيل عقول أبنائنا واهتماماتهم ودعم انتمائهم لبلادهم وتقديم وسيلة معرفية لفهم موروثهم الثقافي والتاريخي والقيمي نقدم هذه الموسوعة.                                                 اسم المؤلف :- على احمد الجمل                                                                                                                               سنة النشر :- 2021", "/images/products/9789777952897.webp", "9789777952897", "موسوعة عالمنا العربى بين يديك", null, 600m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 836, "محمد المنسى قنديل", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي القصة مغامرة خيالية لطفل نام حزينًا لما علم أن جده سيأتي بالجزّار ليذبح صديقته البقرة.\n ومن خلال تلك المغامرة الشيقة يعرفنا الكاتب بقوس قزح، وألوانه، وبعض ما تشير إليه هذه الألوان، مثل اللون الأحمر الناري، والماء واللون الأزرق، والتأثير العلاجي والنفسي للون الأخضر في حبكة شيقة ممتعة.\n\n المؤلف : محمد المنسى قنديل\n سنة النشر :2022", "/images/products/9789777952873.webp", "9789777952873", "رحلة فى الوان الطيف", null, 185m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 837, "محمد شومان", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعتبر كتاب «الرأي العام»Public Opinion لـ«والتر ليبمان» الصادر عام 1922 واحدًا من أهم الكتب الرائدة التي جاءت في مجال دراسات الاتصال والإعلام والرأي العام، ويعد من أهم الكتب التأسيسية في هذا المجال، والذي صار علمًا ومهنة تدرس في معظم جامعات العالم. وجاءت فكرة ترجمة هذا الكتاب الأيقونة إلى اللغة العربية، وتقديم قراءة عربية لأهم أطروحاته الفكرية والإعلامية والسياسية، تستهدف التفاعل مع القارئ المتخصص في مجال بحوث الإعلام، والعلوم السياسية، والجمهور المثقف المهتم بإشكاليات السياسة والحكم ودور الإعلام في المجتمع المعاصر، وإشكالية دور الصحافة والإعلام في زيادة اهتمام ووعي المواطنين، أم قيامها بتزييف الوعي والتلاعب بالرأي العام وتضليله؟ وهل يمكن إصلاح دور الصحافة والإعلام بحيث تصبح أكثر دقة وموضوعية في نقل الأخبار والآراء المتعددة؟ وما علاقة هذه الإشكاليات بآليات صنع الصورة النمطية، والرموز، والدعاية، وصناعة الإجماع أو الإرادة العامة؟ اسم المؤلف :- محمد شومان سنة النشر :- 2022\n\nاشراف حسن عماد مكاوي", "/images/products/9789777953177.webp", "9789777953177", "الصورة النمطية وتضليل الرأى العام", null, 330m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 838, "زينب عبد اللاه", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في بيوت تحمل رحيق العمالقة والمبدعين، بحثنا عن الأبناء والأحفاد ليحدثونا عن الجوانب التي لا نعرفها عن «الحبايب»، تفاصيل البدايات ومحطات النجاح والأضواء، وأسرار فترات العزلة والانزواء. كيف كانت الحياة في بيت الشيخ رفعت، وأسرار سنوات مرضه وعزلته، وسر وصية الشيخ النقشبندي وكيف توقّع وفاته، ولماذا تعرّض محمد عبد المطلب للاعتقال، وما لا يعرفه الكثيرون عن السندريلا عقيلة راتب، وقصة سعاد محمد مع زوجين و10 أبناء، وعلاقة الشيخ الشعراوي بعماد حمدي وحسن عابدين واعتزال مديحة كامل وحجابها. حكايات القهر والألم في حياة ملوك الضحك زينات صدقي، وعبدالفتاح القصري، وعبد المنعم إبراهيم، ومحمد رضا، وعبد المنعم مدبولي، وفؤاد المهندس، وعلاء ولي الدين، ومغامرات حمدي وعبدالله غيث مع الفن والحياة، وحكايات عبد الناصر والسادات مع أهل الفن. في بيوت الحبايب نرى وجوه من غابوا، ونعرف كيف عاشوا، نشاهد الصور والمقتنيات ونعرف تفاصيل الأسرار والحكايات. اسم المؤلف :- زينب عبد اللاه سنة النشر :- 2021", "/images/products/9789777953283.webp", "9789777953283", "فى بيوت الحبايب", null, 220m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 839, "علي فرجاني", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب هو دراسة استكشافية تهدف إلى إزالة الغموض عن آلية التحول الرقمي وما يضمه من تقنيات تكنولوجية قد لا يعرفها غير المتخصصين، أو بعض متخذي القرار في المؤسسات، مما يعيق اللحاق بركب التكنولوجيا التنافسية الجديدة، وما تضمه من حقول نفطية جديدة كالذكاء الاصطناعي والبيانات الضخمة، مرورًا بدور النظم الخبيرة في دعم واتخاذ القرار، والحوسبة السحابية، والأسواق الافتراضية، وتوظيف خوارزميات الذكاء الاصطناعي في إدارة العملاء CRM ومستحدثاتها، ووصولًا إلى صحافة البيانات والذكاء الاصطناعي، وكيفية تأثير تكنولوجيا الاتصال والمعلومات عبر تطبيقات الذكاء الاصطناعي على مهنة العلاقات العامة والاتصال المؤسسي العملاق، فضلًا عن توظيف المؤسسات الكبيرة لتقنيات الذكاء الاصطناعي والبيانات الضخمة في إدارة العملية الاتصالية والتأثير على العملاء والجمهور. اسم المؤلف :- على فرجانى سنة النشر :- 2021\n\nاشراف حسن عماد مكاوي", "/images/products/9789777953146.webp", "9789777953146", "التقنيات الرقمية وتبيقاتها فى الاعلام", null, 300m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 840, "أحمد جميل الشرقاوي", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما الجَمَال؟ أين نراه؟ هل الجَمال خاص بالطبيعة حولنا فقط؟ هل يمكن أن يوصف الجسم البشري بالجَمال؟ مَن الذي يسعى للجمال؟ المرأة أم الرجل؟ هل للجَمال معايير؟ ما هو عِلم الجمال؟ وما علاقته بالجمال الإنساني؟ إن الشعور بالجمال له أصول بعيدة تعود لتطور الإنسان البيولوجي وتصورنا عن الجمال يتنوع بتأثير البيئات والثقافات المختلفة عبر التاريخ. وكذلك المقاييس والنسب التي تمثل الشكل المثالي لجسم الإنسان. يناقش هذا الكتاب مفهوم الجمال الطبيعي، والجمال البشري الشكلي بصفة خاصة، حيث أصبح الجمال الطبيعي موضوعًا أساسيًّا في أحد فروع علم الجمال... ويستعرض كيف أن جسم الإنسان كان يعاد تشكيله قديمًا عن طريق وسائل التجميل والملابس، وحديثًا عن طريق الجراحة ليحصل الإنسان على أعلى درجة من الجمال بشقيه الطبيعي والفني. اسم المؤلف :- احمد جميل الشرقاوى سنة النشر :- 2021", "/images/products/9789777953153.webp", "9789777953153", "7 وجوه للجمال", null, 185m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 841, "شيخة سيف الشامسي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يستعرض هذا الكتاب أحوال التعليم وجهود التنمية المستدامة في دول الخليج العربي متخذًا من دولة الإمارات نموذجًا ليعكس مدى التقدم المحرز في هذا المجال، حيث تحتل دولة الإمارات العربية المتحدة المرتبة الأولى عربيًّا، والمرتبة السابعة عشرة عالميًّا من حيث جودة التعليم، بناء على ما ورد في تقرير التنافسية العالمية الصادر عن المنتدى الاقتصادي العالمي عام 2018. ولأن التعليم يعتبر أحد الأهداف الهامة لإعلان التنمية المستدامة الذي وافقت عليه جميع الدول الأعضاء بالأمم المتحدة بأهدافه السبعة عشر عام 2015، فقد حاول الكتاب أن يموضع جهود التعليم في دول الخليج العربي في إطار هذا الإعلان الذي يسعى إلى إنهاء الفقر وحماية الكوكب وضمان تمتع جميع الناس بالسلام والازدهار بحلول عام 2030. وتطرح المؤلفة رؤية مستقبلية في إطار مبادئ التنمية المستدامة بتجلياتها الاقتصادية والاجتماعية والبيئية. وتتضمن هذه الرؤية نظامًا تعليميًّا مقترحًا يسهم فى تنويع هيكل الاقتصاد القومي من خلال إعداد قوة العمل القادرة على التفاعل مع منجزات اقتصاد المعرفة وتكنولوجيا المعلومات. وفي غضون هذه الرؤية تقترح المؤلفة عددًا من الأهداف التي يجدر أن تسعى الأنظمة التعليمية الخليجية أن تركز على تحقيقها فى المستقبل مثل تقوية الدافعية للتعلم، وطرح نسق جديد للقيم، والمهارات اللازمة للعمل والحياة، ومسارات رفع مستوى الإنتاجية والتوظيف للمواطنين، وانعكاس ذلك على تطوير سوق العمل المحلية من حيث المهارات الجديدة وأساليب العمل في ظل تحديات الثورة الصناعية الرابعة وتكنولوجيا الذكاء الاصطناعي.                                               اسم المؤلف :- شيخة سيف الشامسى                                         سنة النشر :- 2021", "/images/products/9789777953214.webp", "9789777953214", "التعليم والتنمية المستدامة بدول الخليج العربي الامارات العربية المتحدة", null, 330m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 842, "عائشة سلطان", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تأخذنا الكاتبة في رحلة تنطلق من دبي القديمة وشوارع \"الفريج\"، حيث نشأت وحكاوي جدتها، إلى مطارات عواصم العالم، تتحرك الكاتبة بين السطور برشاقة من اعتاد التنقل تحت سماوات مختلفة، فتكتشف – كقارئ – أنك ترى المدينة من زاوية مختلفة وعين أخرى حتى لو كنت من أهلها؛ فتحت سماء القاهرة تقرأ عن شوارع تسير فيها يوميا لكنك لا تلتفت لمواطن جمالها كما تتحدث عنها المؤلفة. من القاهرة وبيروت وذكريات الكويت، إلى براغ وميونخ وبروكسل، جندول فينيسيا وقت الغروب وقصص الحب في فيرونا، تاريخ اسطنبول وسخونة الهواء في بانكوك. حقائق لن تعرفها إلا بالسفر؛ فالمدن لا تجامل عشاقها، ولا تلتفت لمزاجك، لكنها تعلمك الحكمة. هل يغيرنا السفر أو المناخ، هل للمدن ذاكرة أو رائحة؟ أسئلة وإجابات لن ترد لخاطرك إلا إذا كنت تطل من شباك الطائرة. اسم المؤلف :- عائشة سلطان سنة النشر :- 2021", "/images/products/9789777953191.webp", "9789777953191", "هوامش فى المدن والسفر والترحيل", null, 275m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 843, "يوسف كرم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يؤرخ فيلسوفنا ومؤرخنا القدير يوسف كرم في هذا الجزء لمساحة زمنية شاسعة امتدت لعدة قرون تبدأ من نهايات العصر الوسيط وبدايات عصر النهضة والعصر الحديث في القرن الخامس عشر وحتى القرن العشرين مع ما في هذه المساحة الزمنية من زخم فكري كبير وكثرة من الفلاسفة والتيارات الفلسفية في كل البلاد الأوربية وأمريكا تحدث فيها الفلاسفة في كل شيء وحملوا لواء التنوير والتحديث وعبروا بأوربا والغرب من عصور الظلام والجمود كما كانوا يطلقون على العصور الوسطى إلى عصر جديد تمامًا دانت السيادة الفكرية والعلمية والاقتصادية بل والاجتماعية والفنية والأدبية للغرب. إن يوسف كرم في هذا الجزء يواصل إبداء ملاحظاته النقدية على كل ما يعرضه من مذاهب وأفكار لهؤلاء الفلاسفة، ولعلنا نلاحظ دائمًا علو نبرة النقد والرفض لهذه الأفكار التي تمس التوجه الروحي للأفراد والمجتمعات أو التي تشكك في العقائد الدينية أو تقلل من شأنها. ومن هنا فإن يوسف كرم لم يكن مجرد المعارض المحايد، بل كان الفيلسوف الذي يستعرض الآراء والمذاهب الفلسفية بأقصى قدر من الموضوعية، وفي ذات الوقت لا يتركها تمر مرور الكرام، بل يحرص على تفنيد ما يستحق التفنيد منها ونقد ما يستحق النقد. اسم المؤلف :- يوسف كرم شرح وتقديم وتعليق :- مصطفى النشار سنة النشر :- 2021\n\nتقديم وشرح وتعليق مصطفى النشار", "/images/products/9789772937677.webp", "9789772937677", "تاريخ الفلسفة الحديثة من القرن الخامس عشر حتى القرن الثامن عشر", null, 275m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 844, "زينب عفيفى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"أسمع نقرات خفيفة، ظننت أنها صوت تنبيه رسائل هاتفي، ثم أدركت أنها دقات على باب الغرفة. تسمرت في مكاني عندما فتحت الباب، كدت أفقد توازني، من هذه المرأة؟ هل ضلت الطريق إلى باب الغرفة أم ضللت أنا طريقي للباب ووقفت أمام المرآة ؟! إنها تشبهني تمامًا، بل هي أنا، أغمضت عيني وفتحتها عدة مرات.. الصورة واضحة ، امرأة في مثل عمري تشبهني تمامًا، ليس هناك شك أو تخمين.. إنها أنا!\". *** من الفقد ما يستحيل تعويضه، نعيش بعده الإحساس الدائم بالنقص في حياتنا، نظل نبحث عنه طوال الوقت، وبعد عناء نكتشف أنه موجود بداخلنا، ولم يذهب بعيدًا. في «معكِ تكتمل صورتي» تسافر مصورة فوتوغرافية إلى باريس، لحضور حفل تسليمها جائزة مسابقة دولية، فتتحول رحلتها إلى رحلة للبحث عن نصف روحها المفقود. رحلة مليئة بالدهشة، بالتوهمات، بالعذاب، بالحب. رحلة شاقة وعسيرة يعيشها كل منا بهذا الشكل أو بآخر، والمحظوظ من تكتمل روحه في النهاية. اسم المؤلف :- زينب عفيفى سنة النشر :- 2021", "/images/products/9789777953269.webp", "9789777953269", "معك تكتمل صورتى", null, 155m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 845, "أحمد القرملاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مثل غدير صافٍ، تتهادى مياهه بوداعة أو تندفع بعنف، يظل صفاؤه يكشف عن الأعماق بروعة، هذا ما يتبادر إلى خاطري فور أن أذكر الحالة الإبداعية التي يشكلها الكاتب الجميل أحمد القرملاوي، وهي حالة استثنائية بذاتها وبإبداعها، فهو من الكتّاب النادرين الذين يجيدون كتابة القصة كما كتابة الرواية، بالشروط والتجليات الخاصة بكل منهما. لقد قرأت هذه القصص البديعة المتقنة بإعجاب وحب وكثير من التأثر، منها ما ذبحني بشعاع من نور، ومنها ما انتزع من صدري تنهدات الأسى، ومنها ما مس وتر الغضب، لكن سمتها المشترك، كان تلك الشفافية، ورهافة البوح، ونقاء الروح، وهو سمت الكاتب نفسه، كإنسان. اسم المؤلف :- احمد القرملاوى سنة النشر النشر :- 2021", "/images/products/9789777953290.webp", "9789777953290", "قميص لتغليف الهدايا", null, 185m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 846, "يوسف كرم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وقد بيَّنَّا أصول رأينا فيما بعد الطبيعة، وهو أن هذا العلم يدور على معنى الوجود بما هو وجود، أي بإطلاقه من كل تعيين وتخصيص، وعلى المعاني والمبادئ اللاحقة لمعنى الوجود، وهي أبسط المعاني والمبادئ وأعمها، المؤسسة لمعرفتنا، المؤيدة لحقيقتها، المخولة العقل حق الخروج إلى موضوعات التصور في أنفسها، والنفاذ إلى حقائقها، وبناء العلم. ونقصد بعد ذلك إلى إتمام البحث الشامل، واستيفاء اليقين الكلي، بالصعود إلى العلة الأولى للطبيعة، أي لخالقها ومشرع قوانينها، المفارق لها، العالي على موجوداتها، وقد نفت وجوده فرق، وضلت في فهمه فرق، فتكدست المسائل في هذه الناحية من المعرفة، وأعضلت حتى لا يهتدي إلى وجه الحق فيها إلا الأقلون. وفي ضوء الحاجة الملحة لإعادة بناء الفكر الإنساني حول قضايا الطبيعة وما بعد الطبيعة وعلاقتهما بعقلنا الواعي الذي ينبغي ألا تشغله المطالب المادية والممارسات الشهوانية في الحياة اليومية والمتابعة اللاهثة لنواتج التكنولوجيات  المعاصرة عن تأمل حقيقة الوجود والطبيعة من حوله، ذلك التأمل الذي سيقوده حتمًا إلى إدراك ما وراء الوجود المادي المحسوس وخاصة وجود الله.                                                                     اسم المؤلف :- مصطفى النشار                                         سنة النشر :- 2021\n\nتقديم وشرح وتعليق مصطفى النشار", "/images/products/9789772937684.webp", "9789772937684", "الطبيعة وما بعد الطبيعة", null, 200m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 847, "حسن عبد الموجود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في قرية سبقها الزمن، أو دهسها، نسيته أو نسيها، تدور حرب طاحنة، لا أمل في إنهائها، إذ إن طرفيها الإنسان والحيوان، لا يتحدثان نفس اللغة، فلا مجال لتفاوض بينهما على هدنة. هنا. في عالم كتاب «البشر والسحالي» لا خطوة يخطوها كائن إلا على جثة آخر، ولا شبع لبطن إلا وثمنه جوع يمزق بطنًا آخر، الفلاح، والخنزير، والثعبان، والكلب، والديك، والهدهد، والحمار، والعقرب، والدودة، والقط، والفراشة.لا يستند حسن عبد الموجود في هذا الكتاب الممتع إلى تراث قصص الحيوان العالمي الراسخ، ونصوصه لا تسعى وراء الحكمة وإن أمكن استخلاصها منها، ولا تستهدف الحكي وإن لم تتعال عليه، لكنها نصوص تجمع بين القصة والسيرة والفكرة، لتعرِّي كثيرًا مما تخفيه الحضارة الإنسانية وراء أقنعة الدين أو الأسطورة أو التقاليد، وتفتح عيني قارئها على حقيقة ما تراه، كلما وقعت على دجاجة في طبق، وهي أنها مجرد طائر خسر الحرب.                 اسم المؤلف :- حسن عبد الموجود                                     سنة النشر :- 2021\n\nرسوم الكفراوي", "/images/products/9789777953238.webp", "9789777953238", "البشر والسحالى", null, 185m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 848, "توم ايستون", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي هذه القصة مغامرات «سارة» مع صديقتها الجديدة «مريم» بعدما انتقلت صديقة «سارة» إلى مدرسة أخرى.\n تشير القصة إلى شعور الأطفال بالحزن عندما يبتعدون عما يألفونه، ولكن سرعان ما يعتادون الصداقات الجديدة، ويسعدون بها.\n المؤلف : توم ايستون\n سنة النشر :2022\n\nتشارلى الدر ترجمة ولاء كمال", "/images/products/9789777952804.webp", "9789777952804", "مغامرات جديدة صديقتى الجديدة", null, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 849, "هشام الخشن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"رحلة جديدة ومختلفة عن رواياته السابقة، كعادته يصحبنا فيها هشام الخشن. من لندن إلى القسطنطينية مرورًا بباريس وصولًا إلى القاهرة يشاركنا قصة ليديا ستون، المربية البريطانية التي التحقت في بداية سبعينيات القرن التاسع عشر بقصر الأمير المصري مصطفى بهجت فاضل. نعيش معها بين الصفحات وسطورها مجريات العصور الخديوية المتتالية بما حوت من أحداث. مزيج من شخصيات تاريخية عاشت وكانت علامات في تاريخ مصر، وأخرى من خيال الكاتب نتابع من خلال عيونها ومشاعرها كيف عاشوا وما مروا به من مغامرات ودراما حياتية في خضم تلك الفترة الثرية التي شهدت نهضة للوطن مازال بنا شوق لتفاصيلها. بالحبر الأزرق رواية آخذة عن الشغف واكتشاف الذات وقساوة القدر والبشر.\n سنة النشر :- 2021\n اسم المؤلف :- هشام الخشن", "/images/products/9789777953184.webp", "9789777953184", "بالحبر الازرق", null, 185m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 850, "لوتس عبد الكريم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"\"\"هذه روايةٌ تمزجُ بين العقلِ والعاطفة ؛ أملًا للوصُول إلى الفردوسِ القلبيِّ، من خلالِ مسارِ الحياةِ التي لن يعيقَ تيارُها العنيفُ أحدَهُما عن الآخر.\nإنَّ أيَّةَ امرأةٍ بوسْعها أن تصلَ إلى جنَّتها الأرضية أيًّا كانت عراقيلُ الحياة، إذا هي أرادتْ ورغبتْ وحاولتْ .\nد.لوتس عبد الكريم تقدِّم في روايتها ” الجنَّة المفقُودة ” أحاسيسَ امرأةٍ ، مُستخدِمةً تحليلَ نفسيتِها ومشاعرِها العميقةِ المُستَتِرة، وانفعالاتها عبرَ أطوارِها المختلفةِ على مدى مراحل عُمرها .\nهذا عملٌ روائيٌّ يوحِي بالكثير، ويتسمُ بالجرأة في تصوير ما تمرُّ به المرأة عندما تحبُّ، وتخفقُ في حبِّها لمن اختارته بأسلوبٍ يعي الفهمَ الحقيقيَّ لعلاقة الرجل بالمرأة .\nوكانت الكاتبةُ صريحةً وكاشفةً ، وهي تقـدِّم تجربةَ امـرأةٍ بريئـةٍ لا خبرةَ لها بأكاذيبِ الرجال وحِيَلِهم وشِرَاكِهم وخِدَعِهم .\n اسم المؤلف :- لوتس عبد الكريم سنة النشر :- 2021", "/images/products/9789777953221.webp", "9789777953221", "الجنة المفقودة", null, 125m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 851, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "واحتضنها إبراهيم بعينيه، ووجهه ينطلق بالفرح، كان كل خلجة فيه تزغرد.. ولم يفرح بالخبر ولكنه كان فرحًا بعودتها.. لقد قضى كل هذه الفترة منذ ذهابها ملهوفًا عليها.. يفكر فيها.. وقلبه ينقبض وينفرد كأنه يجري وراءها.. وحاول أن يقنع نفسه أنه لم يكن يفكر فيها إلا ليطمئن على خطته.. وأنه لم يكن ملهوفًا عليها، إنما كان ملهوفًا على نفسه.. حاول كثيرًا.. وحاول أن يفسر إحساسه بأنه نفس الإحساس الذي كان يشعر به وهو يرسل زملاءه في الجمعية السرية لتنفيذ خططه.. حاول أن يوجه إحساسه إلى هذا الاتجاه.. ولكنه لم يستطع.. إنه إحساس جديد ذلك الذي يحس به..                                                اسم المؤلف :- احسان عبد القدوس                                     سنة النشر :- 2021", "/images/products/9789777953160.webp", "9789777953160", "فى بيتنا رجل", null, 330m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 852, "عرفة عبده على", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قرن كامل من الزمان ..مضى على رحيل \"اسماعيل باشا العظيم \" عن دنيانا ..ذلك الرجل الذي كان عصره أكثر عصورنا التاريخية الحديثة ثراءً وحركة شاملة في جميع المجالات، وقد وافى الخديو اسماعيل امته، وهي في مفترق الطرق، تتنازعها حضارتان حضارتها العربية الاسلامي تنزع اليها بحكم الموروث والتقاليد.. والحضارة الغربية الحديثة، تندفع نحوها بحكم التجديد وقد اثر اسماعيل الإصلاح القوي العنيف، من أجل الأخذ بأسباب الارتقاء الحضاري في العمران والزراعة والصناعة والتجارة والتعليم والقضاء والنظم السياسية والإدارية.. وكان في كل هذا الروح الملهمة واليد المحركة،في عصر زاخر بالإنشاء والتجديد.. والبناء والتشييد.. وقد يختلف المؤرخون في اسماعيل باشا، لكنهم يتفقون على عظمة شخصيته التي تعرف المستحيل .. ولا يمكن لجيل من الاجيال - خاصة جيل نهاية القرن العشرين - أن يدرك مقدار عظمة اسماعيل، الا اذا تصور مصر حين اعتلى اسماعيل باشا عرشها، لكن التاريخ المنصف لا يملك الا ان يؤدى واجب الحق،اذا تحدث عن الذين بنوه، وحددوا معالمه، وكانت لهم الكلمة الاولى فى صنع وتوجيه أحداثة\nاسم المؤلف :- عرفة عبده على \nسنة النشر :- 1998", "/images/products/9789777953122.webp", "9789777953122", "القاهرة فى عصر اسماعيل", null, 220m, new DateTime(1998, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 853, "عباس الطرابيلى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "العباسية ، النيل ، بابا اللوق ، جاردن سيتي ، الزمالك ، العتبة ، الأزبكية ، القناطر ، ، وخصص فصلا حول القاهرة في العصر الإسلامي ، وفصلا أخر حول شوارع هامة في القاهرة\n “ما دمنا اتفقنا على أن الشوارع خير شاهد حي على التاريخ، تعالوا بنا نغوص في أعماق التاريخ، نشرح تاريخ صاحب كل شارع، ولماذا وضعناه حيث يجب. تعالوا نقرأ تاريخ مصر من خلال أسماء شوارع مصر، أو بمعنى أكثر دقة تعالوا نعيد الذاكرة لعقل شعب مصر، تعالوا ننبش تاريخ الأمة المصرية وليعرف جيل هذا الزمان عظمة رجال أيام زمان”.\n هكذا يهيئنا الكاتب والصحفي الكبير “عباس الطرابيلي” لرحلةٍ ممتعة وثرية معرفياً، يمثِّلها كتابه الشهير “شوارع لها تاريخ”، والذي تعيد الدار المصرية اللبنانية إصداره في طبعةٍ جديدة، بعدما نفد أكثر من مرة. ثمة كتب لا تنتهي صلاحيتها مع مرور الزمن، بل تزداد أهميتها كلما ابتعدت بها السنوات، ذلك أنها تُمثِّل تأريخاً دقيقاً، وتوثيقاً أميناً، لصفحات من التاريخ، شهدت عليها وأنقذتها من الاندثار. وكتاب “شوارع لها تاريخ” هو أحد هذه الكتب بامتياز.\n كما يوضح العنوان، فالكتاب يقرأ التاريخ عبر زاويةٍ فريدة، هي الشوارع، حيث نصبح أمام متعة قراءة مُضاعفة: رحلة بين الدروب التي نعبرها كل يوم دون أن نعرف الأدوار التي لعبتها في سالف الأزمنة، وزخم معرفي من المعلومات التي يقدمها الطرابيلي بدقة المؤرخ وسلاسة الصحفي معاً. إنها بالفعل، وكما يعلن العنوان الفرعي للكتاب: “سياحة في عقل الأمة”، حيث الرحلة هذه المرة داخل الهوية المصرية نفسها، رحلة لا تكتفي بالقشور ولا تقنع بالسطح، بل تغور لتعيد اكتشاف العديد من المعاني وتُبرز ما لا يُحصى من المآثر.\n “هناك ظواهر عديدة في مصر يجب أن نضعها في الاعتبار. مثلاً هناك شوارع القاهرة الفاطمية المُعزِّية التى أصبحت حاضرة الدولة أو الخلافة الفاطمية الشيعية، وتُنافس دولة الخلافة العباسية السُنيَّة في بغداد، والأموية السُنِّية أيضاً في الأندلس، شوارع القاهرة الفاطمية هذه لم تحمل أسماء أشخاص ولكنها حملت أسماء مهن أو حرف أو تجارة وصناعة وهي لم تأت اعتباطاً ولكنها جاءت صورة من الواقع”.\n هكذا يفرد الطرابيلي خريطته، مبرزاً جوهر مشروعه الذي لا يُغفل “الدراما”، ليضيف لكتابه عنصراً مهماً هو الصراع، المدعوم بتشويق يجعل من بعض فصول الكتاب ذُرى في السرد القصصي الممتع.\n اسم المؤلف :- عباس الطرابيلى سنة النشر :- 2021", "/images/products/9789777953108.webp", "9789777953108", "شوارع لها تاريخ", null, 495m, new DateTime(1997, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 854, "محمود تيمور", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"فما هو العائِقُ الذي يحولُ دونَ تطوُّرِ اللغة؟ وكيف السبيلُ إلى رفْع هذا العائق؟ أكبرُ ما يعُوقُ اللغةَ فيما يقولُون أنها لغةُ كتابةٍ لا لغةُ كلام، ولو كانتْ لغةَ كلامٍ لعاشَتْ في السُّوق والبيت، وَلَنَمَتْ مِنْ تِلقَاءِ نفسِهَا، ولاشْتَقَّتْ ألفاظَها مِنْ طبيعتِها دونَ اللُّجُوءِ إلى عوامِلَ مصنُوعَة. وذلك شأنُ العامية في أقطار الشرق، فهيَ أكثرُ طلاقةً، لأنها ترجمانُ الحياة الدارِجَة. ولكنَّ تلك العاميةَ لا ضابطَ لها ولا نِظَام، فإنها لَهَمَجِيَّةٌ غيرُ مهذَّبَة. وليس لها من أصولٍ مستقرَّةٍ قَطُّ. ولا طاقةَ لها بالتعبير الراقي عن جلائلِ الأشياءِ في ميادينِ الاجتماع. فأما لغةُ الكتابة، أعني الفُصْحَى، فقد انصَقَلَتْ على ترادُفِ الأيام، وأُحكِمَتْ ضوابِطُها في الألفاظ والأساليب، لأنها استُعْمِلَت في التعبير منذُ أَمَدٍ مديد. فهلْ يمكنُ أنْ تكونَ هذه الفُصْحَى لغة كلام لِيَتِمَّ كَمَالُها بالمعنى الواسع؟ الواقعُ أننا حين نتأمَّلُ سائِرَ اللغاتِ الحيةِ المعتَبَرةِ لغاتِ كلامٍ وكتابةٍ معًا، لا نعدِمُ الفروقَ فيها بين الكتابةِ والكلام. وربما كانت هذه الفروقُ هَيِّنةً بالإضافة إلى الفَرْقِ بين العربية وعاميَّتِها، ولكن الفرقَ في مثْل الألمانيَّةِ ظاهِرٌ. ومن المحتمَل أن يتضاءَلَ ما بين العربيةِ والعاميةِ من البَوْن على مَرِّ السنين، ولا سيما إذا اطَّرَدَ رقيُّ التعليمِ وشمولُ الثقافة. وقد يكون عن كَثَبٍ منا يوم تتدانَى فيه العربيةُ والعاميةُ باستمدادِ كُلٍّ منهما مِنَ الأُخْرى\". اسم المؤلف :- محمود تيمور تقديم :- صلاح فضل شرح وتعليق :- وائل على السيد اشراف :- نبوى عبد العزيز سنة النشر :- 2021\n\nتقديم صلاح فضل شرح وتعليق وائل على السيد إشراف عبد العزيز نبوي", "/images/products/9789777953115.webp", "9789777953115", "مشكلات اللغة العربية", null, 155m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 855, "مصطفى عبد الرزاق", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إن هذه السلسلة من كلاسيكيات الفلسفة تأليفًا وترجمة هي أبرز ما قامت عليه نهضتنا الحديثة، وهي ما تربت عليه الأجيال السابقة.\nوما أحوجنا اليوم لإعادة نشر هذه الكلاسيكيات من مؤلفات ومترجمات رائدة لتستفيد منها أجيالنا الشابة، وخاصة في ظل ندرة ما يكتبه المتخصصون المعاصرون في الفلسفة ومجالاتها المختلفة، وفي ظل غياب المنهج الفلسفي للتفكير في حياتنا المعاصرة، مما كان السبب المباشر لما نراه من تطرف وتعصب وجمود وعدم تقبل الآخر وفقدان القدرة على التحليل ونقد الأفكار.\n***\nهل الفلسفة حرام؟ ماذا يعني علم الكلام؟ ما المقصود بالرأي؟ ما علاقة المسلمين بالفلسفة؟ هل هناك ما يسمى بالفلسفة الإسلامية؟ هل أيَّد الإسلامُ العقلَ؟ هل ظهر الرأي في عهد النبي صلى الله عليه وسلم؟ هل اختلف الصحابة في الرأي؟\nتساؤلات كثيرة يثيرها هذا الكتاب مجيبًا عليها علميًّا وتاريخيًّا مما يجعله أهم مرجع في الفلسفة الإسلامية؛ حيث يبدأ بآراء الغربيين، ويُثنّي بآراء الإسلاميين مُفصّلًا مناهجهم، ذاكرًا أعلامهم في النظر العقلي وأثر ذلك على العلوم الشرعية كعلم العقيدة، والفقه.\n«لابد للباحث في الفلسفة الإسلامية وتاريخها من الإلمام بمقالات من سبقوه في هذا الشأن؛ ليكون على بصيرة فيما يتخيره من وجهة النظر، وفيما يتحرى اجتنابه من أسباب الزلل» - شيخ الأزهر الأسبق: الدكتور مصطفى عبد الرازق.\nاسم المؤلف :-  مصطفى عبد الرازق\nتقديم وشرح وتعليق :- مصطفى النشار \nسنة النشر :- 2023\n\nتقديم وشرح وتعليق مصطفى النشار", "/images/products/9789772937660.webp", "9789772937660", "تمهيد لتاريخ الفلسفة الاسلامية", null, 275m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 856, "محمد محمد الهادي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "موجةٌ من التغيُّرات أحدثت انقلابًا هائلًا في عالَم اليوم، أزمةٌ صحيَّةٌ كشفت جوانب أخرى من حياة البشرية، وأظهرت إبداعاتٍ بشريةً أثارت الكثير من الجدال حولها، أبرزها تكنولوجيا الذكاء الاصطناعي، التي ظهرت وفرضت نفسها بقوة على عالَم اليوم وأصبحـت أمرًا واقعًا بل حتميًّا، وقـد أدرك العـالم أنْ لا مناصَ من التعامل معها، غير أنَّ هناك أسئلةً عديدةً تراود إنسان العصر حول تكنولوجيا الذكاء الاصطناعي أحقيقةٌ هي أم خيالٌ كما تصوره الأفلام والقصص؟ ما انعكاساتُها على اقتصاديات الدول؟ وكيف تؤثر على الوظائف وسوق العمل، هل يحل الذكاء الاصطناعي محلَّ الذكاء البشري على الدوام.. وما دور تطبيقات الذكاء الاصطناعي في تقديم الرعاية الصحية هل حقًّا يساعد في إمكانية التنبؤ بالأمراض الحادَّة ومنع حدوث النوبات المفاجئة؟! وكيف أسهمت في خدمات التعليم والنقل والزراعة بل وعلوم اللغة. وما السياسات التي ستتبعها الدول للتعامل مع تكنولوجيا الذكاء الاصطناعي باعتبارها تكنولوجيا الحاضر والمستقبل، هل ستصبح استغلالًا سياسيًّا وتخضع للصراع الدولي بين القوي والضعيف، وكيف سيتم تنظيم استخدامها مِن قِبل الأفراد والمؤسسات. هذه الأسئلة وغيرها الكثير يعرِضها الخبير التكنولوجي الدكتور محمَّد الهادي في فصول هذا الكتاب بنظرة علمية واقعية تكشف الحقائق وتنير البصائر.\nاسم المؤلف :- محمد محمد الهادى \nسنة النشر :- 2021", "/images/products/9789777953085.webp", "9789777953085", "الذكاء الاصطناعى", null, 385m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 857, "مصطفى النشار", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعد أن وقف العالم عاجزًا أمام فيروس صغير \"كورونا\" تساءل فلاسفة العالم وعلماء الإنسانيات: هل هذا نهاية عصر وبداية عصر جديد؟! هذا الكتاب يرى فجرًا جديدًا لهذا العصر الجديد يلوح في الأفق تتغير فيه سياسات واقتصاديات العالم، لتصبح فيه السيادة لإنسانية الإنسان، بدلًا من الهيمنة العسكرية والاقتصادية لقطب واحد. إن العصر الجديد ستكون السيادة فيه لعودة القيم قولًا وفعلًا؛ فالعالم سيتجه حتمًا ليس إلى تكديس السلاح ومحاولات غزو الفضاء بقدر ما سيتجه إلى إعادة توزيع الثروات والقضاء على الفقر، وإعادة البيئة الخضراء والحفاظ على الحقوق المتوازنة للبشر ولجميع الكائنات الحية التي تشارك البشر الحياة على هذا الكوكب. إن عصرًا جديدًا سيبدأ في التشكل عقب القضاء على هذا الوباء الذي لم يعرف له البشر - حتى كتابة هذه السطور - نهاية! لكن ما إن يقضي الله له نهاية مرتقبة بإذنه هو وحده، سيبدأ ذلك العصر الجديد من هذا الفجر الجديد الذي يكاد نوره يبزغ في نهاية هذا النفق المظلم الذي يعيشه العالم الآن. اسم المؤلف :- مصطفى النشار سنة النشر :- 2021", "/images/products/9789777953078.webp", "9789777953078", "مدخل الى فلسفة المستقبل", null, 275m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 858, "محمد فتحى عبد الهادى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تنظيم المعلومات حلقة مهمة من حلقات دورة المعلومات، ونشاط لا غنى عنه في المكتبات وغيرها من مؤسسات المعلومات التي تسعى للحصول على مصادر المعلومات ثم تنظيمها وإعداد أدوات الاسترجاع من أجل إتاحة المعلومات وخدماتها للراغبين في الاستفادة منها.  كما أنه من أكثر المجالات استخداما للتقنيات الحديثة المتمثلة في الحاسبات وشبكات نقل المعلومات والهواتف الذكية وما شابه، وأيضًا من أكثر المجالات المعنية بإعداد واستخدام وتطبيق الأدوات والقواعد والنظم المعيارية. ورغم أن تنظيم المعلومات يضم عمليات أو أنشطة عديدة يحتاج كل منها إلى كتاب مستقل، إلا أنه يبدو من الضروري وجود كتاب يغطي كل هذه الأنشطة بإيجاز ويكون بمثابة تقديم لها. يهدف هذا الكتاب إلى تقديم عرض شامل وحديث ومبسط لمجال تنظيم المعلومات بكل مكوناته.                                                       اسم المؤلف :- محمد فتحى عبد الهادى                                      سنة النشر :- 2021", "/images/products/9789777953061.webp", "9789777953061", "المدخل الى تنظيم المعلومات", null, 330m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 859, "محمد يونس", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل انتهى عصر الصحافة الورقية؟ هذا السؤال يشغل الكثيرين. وفي الإجابة عنه توقعات وسيناريوهات عديدة ومتنوعة، ولكن سواء كنت تخطط للعمل في الصحافة الورقية أو الإلكترونية، فإن الأصول والقواعد التحريرية تكاد تكون واحدة مع اختلافات تفرضها طبيعة الوسيط. يتناول الكتاب فنون الخبر والحديث والتحقيق الصحفي والصحافة الاستقصائية، ومهارات التحرير ومتطلباته، وتأثيرات الثورة الرقمية والوسائل الإلكترونية التي ظهرت عبر شبكة المعلومات الدولية «الإنترنت» على العمل الصحفي، وسبل الاستفادة من المصادر الإلكترونية في ممارسة المهنة سواء عبر الصحافة الورقية أو الإلكترونية، مع تعزيز كل ذلك بنماذج عملية. إن هذا الكتاب يتضمن تقنيات فنون التحرير الصحفي كما أصلتها المعرفة العلمية عبر الأسس النظرية، وأيضا كما رسختها الممارسة العملية في بلاط صاحبة الجلالة.\nاسم المؤلف :- محمد يونس\nسنة النشر :- 2021", "/images/products/9789777953054.webp", "9789777953054", "فنون التحرير الصحفى في العصر الرقمى", null, 385m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 860, "محمود فوزى شاد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل إنشاء معرض ما أو مؤتمر يحتاج إدارة؟ وهل تسويق المعارض والمؤتمرات صار علمًا يتدارسه المهتمون؟ للإجابة عن ذلك سواء كنت تخطط لإنشاء معرض، أو الاشتراك في معرض بدءًا من الفكرة ومرورًا بالتخطيط، وإنجاحًا بالتسويق الجيد، فإننا نقف على قواعد جديدة أرساها المتخصصون على مستوى العالم. يتناول هذا الكتاب فن إدارة وتسويق المؤتمرات والمعارض، بادئًا بتحديد مفهوم الأحـداث الخاصـة، وأنواعها وسماتهـا، وأهدافها، وما قد يقابلها من عوائق، ولا يغفل تصنيف أنواع الجمهور المستهدف من الحدث، مستعرضًا نماذج نظرية عديدة للأحداث الخاصة؛ منها ما يضبط إدارة الحدث، ومنها ما يضبط جودة الحدث، ومنها ما يصل إلى كيفية تقييم فاعلية الأحداث الخاصة ويعرض دور المطبوعات وأنواعها وضوابطها. إن هذا الكتاب يتضمن كل ما من شأنه أن يُنجح معرضًا أو مؤتمرًا على صعيد محلي أو دولي بطريقة علمية ممنهجة تزداد دقة بالتمثيل والإحصاءات ورصد وتحليل مؤشرات صناعة المعارض على المستوى العالمي. اسم المؤلف :- محمود فوزى رشاد سنة النشر :- 2021", "/images/products/9789777953047.webp", "9789777953047", "فن ادارة وتسويق المؤتمرات والمعارض", null, 360m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 861, "حاتم حافظ", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"كقطة تعبر الطريق\" رواية موضوعها \"العالم\" وليس مكانًا بعينه أو هوية دون غيرها. إنها رواية الإنسان المنسحق في آلة العولمة الجبارة، والذائب في مقدرات خلقتها قوى هائلة تحدد له مصيره وتمزق خرائطه لتدفعه نحو الموت أو الجنون. جميع شخوصها مغتربون، كلٌ منهم هارب من حربه الكبرى والخاصة معًا، باحث عن طوق نجاة ينتشله من جحيمه الشخصي.كل شخص هنا يعبر ضفته نحو ضفة أخرى، عبورًا سريعًا مرتبكًا، بالضبط كقطة تعبر الطريق طامحةً في الوصول إلى الرصيف المقابل.. لكن حياتها قد تضيع في لحظة، تحت عجلات سيارةٍ مسرعة.\n• المؤلف :- حاتم حافظ\n• سنة النشر :- 2021", "/images/products/9789777953030.webp", "9789777953030", "كقطة تعبر الطريق", null, 215m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 862, "أحمد حمدان", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ثلاثمائةمصطلح وازدادو تسعاً لبثنا نقلبها ذات اليمين وذات الشمال ونتلطف في عرضها على الأصدقاء والخبراء نستشير هذا ونستطلع تجارب ذاك من أهل القانون وخبراء اللغة وأعلام الوساطة والتفاوض فمنذ أصدرنا كتابنا الأول \" المدخل لراسة الوساطة \" وفي يقيننا ان تعريف القاارىء العربي بأبجديات هذا العلم الجديد بحاجة الى خطوة ثانية نجمع فيها شتات المصطلحات المتناثرة في ثنايا المراجع التي استقينا منها مادة ذلك الكتاب ثم نعربها بمقابلات نحاول فيها ان نكون قدر الطاقة منضبطة قريبة المأخذ تتسق مع الثقافة القانونية العربية وتنسجم مع المزاج المعرفي الشرقي ثم نسعى الى شرحها على نحو مبسط ومزود كلما كان ذلك متاحاً                                                                                                         اسم المؤلف :- احمد حمدان، شريف النجيحى                                                                                                                سنة النشر :- 2021\n\nشريف الحجنى", "/images/products/9789777953009.webp", "9789777953009", "قاموس الوساطة والتفاوض انجليزي، عربي", null, 425m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 863, "إبراهيم فرغلي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"تحدثَتْ ‏كثيرًا، وقرأتْ لي فقرات من كتاب الأحلام. ولم أفهم الرابط بين وجود نفس الكتاب ‏الذي تقرأ منه زرقاء معها هنا. هل يتضمن الكتاب سرّا لا يعرفه إلا من يعيشون ‏في القطار؟ ورغم الحكايات التي حكتها لي قائلة إنها تخص علاقتي بها، فإنني لم ‏أستعد ذاكرتي لكي أتحقق من صدق ما تقوله\".‏ * في هذه الرواية يضعنا إبراهيم فرغلي كعادته بين عالمين يبدوان متباعدان تمام التباعد، من خلال الراوي الذي يركض ليلحق بقطار، ثم يفقد ذاكرته فجأة، فلا يعرف من أين جاء وإلى أين يقصد. ثم يفاجأ بخلو القطار من المسافرين إلا من امرأة غريبة الأطوار تخبره إنها تقرأ لكيلا يتوقف القطار، وفي أجواء غريبة يسودها الغموض يسعى لاستكشاف عالم القطار الغريب، وفي ذروة اليأس تسرد له القارئة ما تقول له أنها سيرته، فيجد نفسه شاهدًا على تغريبة من الجنوب إلى الشمال بطلها فتى خرج من مقبرة حيّا ليبدأ رحلة هربًا من ماضيه. فما الذي يجمع بين هذين المسارين الغريبين البعيدين؟ هذه الرواية المشوقة المثيرة للأسئلة تجيب ببراعة.\n• المؤلف :- ابراهيم فرغلى\n• سنة النشر :- 2021", "/images/products/9789777953023.webp", "9789777953023", "قارئة القطار", null, 300m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 864, "السيد امير على ترجمة / رياض رافت تحقيق وتعليق د. حسام أحمد عبد الظاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"مختصر تاريخ العرب والتمدن الإسلامي\n هذا الكتاب صدرت طبعته الأولى بالإنجليزية عام 9981م، ولازالت طبعاته تواصل الصدورحتى الآن، ما يؤكد أنه ما زال يجد إقبالًا لدى القارئ الغربي، وأن ترجمته التي صدرت في القاهرة عام 8391م، كانت إضافة مهمَّة للمكتبة العربية. مؤلِّف الكتاب، هو المؤرخ والمفكر الهندي السيد أمير علي (9481-8291م)، والذي تميز بقُدرته على مخاطبة الغرب بلغةٍ غربيَّة، وعَرْضِ أفكاره في ثوبٍ علمي يتذوَّقه الذهن الغربي ولا يُنكره الذهن الإسلامي، بحيث أخرج للغرب أجمل وأدق صورة عن المجتمع الإسلامي القديم ومدنيته وتفكيره. وقدَّم أمير علي - في كتابه هذا - التاريخ العربي الإسلامي خلال العصور المُتعاقبة، متناولًا تاريخ الدول الإسلامية دولة فدولة، مقدِّمًا للقارئ تاريخ الإسلام ودُوَله في ضوء النظريات الحديثة، سواء من حيث الدولة أو السياسة، باحثًا في نهضة المسلمين وتدهور سلطانهم، والتطور الاقتصادي والاجتماعي والفكري في الأمة العربية منذ أقدم العصور وحتى إغارة التتار على بغداد، وقد عُني بالناحيتين الاجتماعية والفكرية، حيث قدَّم عنهما في نهاية كل دولة لمحة عميقة ممتعة\"\n• المؤلف :- السيد امير على\n • سنة النشر :- 2021", "/images/products/9789777952972.webp", "9789777952972", "مختصر تاريخ العرب والتمدن الاسلامى", null, 300m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 865, "أشرف العشماوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لكل قصة بداية وحكاية ونهاية ، وحياة كل إنسان رواية هو بطلها ومن خلالها يتشكل العالم من حولنا. ببناء مدهش يقدم أشرف العشماوي أحدث رواياته، قصص أبطاله الثلاثة تحكي حياتهم لكنها تشكل فصول الحكاية الأكبر، حكاية صالة المزاد التي يقتحم بها المؤلف عالمًا روائيًا جديدًا، كاشفاً خباياه وكواليسه وطرق الخداع التي تُجرى فيه، ودور يهود مصر في السيطرة عليه منذ العهد الملكي حتى السبعينيات . تتشابك خيوط حكايات الأبطال وتتعقد علاقاتهم الإنسانية، ليجذب العشماوي أطرافها بسلاسة فتنساب لتحكي أدق تفاصيل النفوس وتصطدم بصراعات تُفضي لجرائم ، وعندما تقترب الخيوط من نهاياتها ومع دَقة المزاد الثالثة الشهيرة التي تعلن موت رغبة وميلاد أخرى تتفجر المفاجآت لتتسع أذهاننا لتساؤلات بقدر ما تتفتح أعيننا على حقائق .. هل حياتنا تشبه المزاد؟ وماذا يتبقى من إنسانيتنا لو أصبح كل منا قطعة معروضة في صالة مزادات ينتظر دوره؟\n • اسم المؤلف :- اشرف العشماوى\n • سنة النشر :- 2021", "/images/products/9789777952989.webp", "9789777952989", "صالة اورفانيللي", null, 310m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 866, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا يبقى بعد الاحتفالات.. ماذا يبقى بعد أن يصفق لك الناس.. و يحملون لك الزهر والهدايا!! يلتقطون معك الصور ويطلبون توقيعك على دفاترهم الصغيرة كأنهم يأخذون منك إقرارًا بوجودك معهم ..!!! هم بنشوة لقائك ومتعة ماقدمته لهم يذهبون ... و يعود مبدع الحدث وحده حزينًا كسيرًا وحيدًا كما كان..!!! * «الرواية تأسرك بجمالها وصدقها، وبرقة تناولها للعلاقات الإنسانية. وهي إن كانت تحكي قصصًا وثيقة الصلة بواقع اجتماعي وثقافي معين، تتجاوز الواقع إلى أفق أوسع وأرحب، مما يجعلها جديرة بمكانة متميزة في الأدب العربي الحديث». د. جلال أمين، كاتب وناقد مصري\n• المؤلف :- نور عبد المجيد\n• سنة النشر :- 2021", "/images/products/9789777952965.webp", "9789777952965", "صولو", null, 320m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 867, "ابن حزم الأندلسي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"طوق الحمامة\n\"\"وكلفتني -أعزك الله- أن أصنِّف لك رسالة في صفة الحبِّ ومعانيه وأسبابه وأعراضه، وما يقع فيه، وله عليَّ سبيلُ الحقيقة، لا متزيدًا ولا مُفنِّنًا، لكن مُورِدًا لما يَحْضُرُني على وجهه، وبِحَسْب وقوعه، حيث انتهى حفظي وسَعَة باعي فيما أذكره، فَبَدَرْتُ إلى مرغوبك، ولولا الإيجاب لك لما تَكَلَّفْتُه، فهذا من اللَّغْو، والأوْلى بنا مع قِصَر أعمارنا ألَّا نَصْرِفَها إلّا فيما نرجو به رَحْبَ المُنْقَلَب، وحُسْن المآب غدًا. والذي كلفتني لا بد فيه من ذكر ما شاهَدَتْه حضرتي، وأدركتْه عنايتي، وحدّثني به الثِّقات من أهل زماني، فاغتفرْ لي الكناية عن الأسماء، فهي إمَّا عَوْرَةٌ لا نستجيز كشفها، وإمّا نحافظ في ذلك صديقًا وَدُودًا ورجلًا جليلًا. وبحسبي أن أُسمِّيَ من لا ضررَ في تسميته، ولا يَلحقنا والمُسمَّى عَيْبٌ في ذكره، إما لاشتهار لا يُغني عنه الطيّ وترك التَّبيين؛ وإمّا لرضا المُخَبَرُ عنه بظهور خَبَرِه، وقلة إنكارٍ منه لنقله. وسأورد في رسالتي هذه أشعارًا قلتُها فيما شاهدتُه، فلا تنكر أنتَ ومن رآها عليّ أني سالكٌ فيها مَسْلَك حاكي الحديث عن نفسه، فهذا مذهب المتحلِّين بقول الشعر، وأكثر من ذلك فإنّ إخواني يُجشِّمونني القولَ فيما يَعْرِض لهم على طرائقهم ومذاهبِهم. وكفاني أَنِّي ذاكرٌ ما عَرض لي مما يُشاكل ما نَحَوْتُ نحوه وناسِبُه إليّ\"\".\"\n• المؤلف :-ابن حزم الاندلسى\n• سنة النشر :- 2021\n\nتقديم:د. صلاح فضل آمال إبراهيم", "/images/products/9789777952934.webp", "9789777952934", "طوق الحمامة فى الألف والالإف", null, 215m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 868, "عائشة البصرى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"“لم أكن أريد أن أخبر المقرر بذلك، لكن إلحاح النوم، وتحت ضغط نظرته المتشككة، أخبرته: – بقي مشهد واحد في الذاكرة. آخر صورة قريبة وواضحة تماما.. أنا في بيتي، أجلس أمام التلفزيون، أشاهد برنامجا وثائقيا عن كرة صغيرة حمراء ناتئة. كرة لا تُرى بالعين المجردة، تتجول في شوارع فارغة، تطير بين المدن والدول والقارات. تتسلل إلى بيوت الأغنياء والفقراء، والملوك والوزراء، تمتص الهواء من صدورهم، وتحصد الأرواح بالآلاف.. رعب وموت لا ينتهي.. حتى المذيع كان في حجر صحي، لا يعرف إن كان سيموت أو سيحيى.. كنتُ جزءا من المشهد، أجلس في أحشاء الكاميرا، ألتهم الطعام بشراهة وأبكي بحرقة مدنا عرفت خطوي، وهي تفرغ موتاها بحاويات في مقابر جماعية.. ..مكبر الصوت: “الكرة الأرضية موبوءة، مئات الآلاف من موتى كورونا في الطريق إلى المركز، قادمة من 172 دولة.. لم يبق مكان آمن على الأرض “.\n• المؤلف :- عائشة البصرى\n• سنة النشر :- 2020", "/images/products/9789777952903.webp", "9789777952903", "كجثة فى رواية بوليسية", null, 155m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 869, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"«وقال مصطفى في دهشة:\n– أي وكر؟!..\nوقال رءوف ضاحكا:\n– إنه وكر الوطاويط!\nواستسلم مصطفى له كأنه يتطلع لاكتشاف سر.. وسار به رءوف إلى حارة من حواري حي الحسين ودخل به في بيت قديم تآكلت كل جدرانه ويستند على عود كبير من الخشب يحميه من الانهيار.. ثم إلى حجرة ضيقة مظلمة تجمع بها ثلاثة شبان.. كل منهم أمامه لوحة يرسم عليها.. يحركون الفرشاة حتى في هذا الظلام وكأن عيني كل منهم تطلق النور الذى\"\n• المؤلف :- احسان عبد القدوس\n• سنة النشر :- 2020", "/images/products/9789777952941.webp", "9789777952941", "وكر الوطاويط", null, 215m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 870, "يوسف عز الدين عيسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"“قال الرجل الغريب مؤكِّدًا:\n– نعم. هنا في غرفتك شيءٌ ثمينٌ، غالي الثّمن!\nقال رمزي في سخريةٍ:\n– وما هو هذا الشيءُ يا تُرَى؟\n– فَنَظر إليه الرجل الغريب نظرةً طويلةً ثم قال:\n– رأسُكَ! هلْ تقْبل أن تبيع لي رأسَكَ؟!\nفضحكَ رَمْزِي في مرارةٍ وقد خاب ظنُّه بعد أنْ لاح لهُ بريقٌ من الأمل وقال:\n– أبيعُ لك رأسي؟ كان من الممكن أن تنتظر دقيقةً واحدةً بعد أن أشنق نفسي، وتأخذ جثتي بأكملها بلا ثمنٍ\"\n المؤلف :- يوسف عز الدين عيسى\n سنة النشر :- 2020", "/images/products/9789777952958.webp", "9789777952958", "الرجل الذى باع رأسه", null, 195m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 871, "سمير صبري", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"خليك دايما أقوى من الصدمات اللي تقابلك.. واتعلم تقف تاني مهما كعبلوك.. وسامح أعداءك حتلاقي أن التسامح أقوى من الانتقام.\"                             (مصطفى أمين)\n\"ملك الأفراح.. برنس الشاشة الصغيرة.. سفير البهجة والسرور والإيجابية في الحياة.\"                                                                                                           (د. يوسف إدريس)\n \n\"لما تلاقي نفسك نجحت قوي.. اختفي شوية.. خلي أعداء النجاح ينسوك شوية.. هاترتاح قوي!\".                                   (أنيس منصور)\n \n\"أروع ما في سمير صبري رعايته لقدامى الفنانين وعشقه لفنه واحترامه لجمهوره.. إنه فارس نادر من فرسان الزمن الجميل\".                                                                                                                                                                            (د. زاهي حواس)\n \n\"سفير الإسكندرية.. مواهبه المتعددة مثل بحرها لا تعرف الصمت ولا الهدوء\".                                                                                     (مفيد فوزي)\n \n\"شكرًا لأبي وأمي.. فقد علَّماني أن أحب ولا أكره ولا أحقد وأحببت مثلهما القراءة، خاصة القرآن الكريم\".                          (سمير صبري)\n \n اسم المؤلف :- سمير صبرى \nسنة النشر :- 2020", "/images/products/9789777952927.webp", "9789777952927", "حكايات العمر كله", null, 400m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 872, "ولاء كمال", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«كنت مسحورًابكل ماقالته، وبهيئتها ،وميلادها الجديد.. ك لذلك جعلني أراها قديسةً أوملاكًا.. تتماهى في نظري معماري العذراء التي رأيتها آلاف المرات في اللوحات .. الآن كانت أمام يماري التي تخصني ، التي تنتمي لي.. لم أكن أدرك لحظتها بأنها لم تكن العذراء.. ولكنها كانت الأخرى.. المجدلية». بعد صدمة عنيفة يرحل الراوي إلى عدة دول أوروبية.. وفي كل مرةٍ تحط به الطائرة يحاول إعادةتركيب الماضي كقطع أحجية ٍتستعصي على الفهم، وكأنه كان يعيش في غيبوبة طوال حياته.. يجهل من هو.. ويجهل حقيقة أقرب الناس إليه. النحات الإيطالي العظيم برنيني، لوحات ديرجويس وكارافاجيو، جرائم فريتزل البشعة، رؤى القديسة تيريزا، وقطع المغناطيس الثقيلة... كلهاعناصرذات حضوراستثنائي ينبض بالحياة في هذه الرواية المؤلمة.. الشاعرية.. والصادمة كثيرًا.\nاسم المؤلف :- ولاء كمال \nسنة النشر :- 2020", "/images/products/9789777952910.webp", "9789777952910", "القداس الأخير", null, 235m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 873, "أحمد القرملاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"“لم أكن أريد أن أخبر المقرر بذلك، لكن إلحاح النوم، وتحت ضغط نظرته المتشككة، أخبرته: – بقي مشهد واحد في الذاكرة. آخر صورة أسطورةعن كنزموعود،يتناقلها أفرادعائلته جيلًابعدجيل، تستحوذعليه، فتدفعه لأن يفتِّش وراءها عبرالبيوت والأزمنة.. وكلما التأمَت الصورالقديمة،نطقَت منهاأصوات الراحلين، ونادَته كي يستكمل الرحلة التي بدأهاسعيًا وراء الكنز. في خامس أعماله الروائية،يضع أحمد القرملاوي بين أيدينا روايةأجيال لها مذاق مختلف،يصحبنا فيها عبرشوارع القاهرة القديمة وحكاياتها التي بلانهاية؛حكايات عشق وألم وفَقْد،انتصارات صغيرة وهزائم مدوِّية.. إنهاحكاية زمن يتسرَّب فلا نستطيع إيقافه.\n• المؤلف :- احمد القرملاوى\n • سنة النشر :- 2020", "/images/products/9789772937646.webp", "9789772937646", "ورثة ال الشيخ", null, 275m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 874, "هشام الخشن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"“لم أكن أريد أن أخبر المقرر بذلك، لكن إلحاح النوم، وتحت ضغط نظرته المتشككة، أخبرته: – بقي مشهد واحد في الذاكرة. آخر صورة أسطورةعن كنزموعود،يتناقلها أفرادعائلته جيلًابعدجيل، تستحوذعليه، فتدفعه لأن يفتِّش وراءها عبرالبيوت والأزمنة.. وكلما التأمَت الصورالقديمة،نطقَت منهاأصوات الراحلين، ونادَته كي يستكمل الرحلة التي بدأهاسعيًا وراء الكنز. في خامس أعماله الروائية،يضع أحمد القرملاوي بين أيدينا روايةأجيال لها مذاق مختلف،يصحبنا فيها عبرشوارع القاهرة القديمة وحكاياتها التي بلانهاية؛حكايات عشق وألم وفَقْد،انتصارات صغيرة وهزائم مدوِّية.. إنهاحكاية زمن يتسرَّب فلا نستطيع إيقافه.\n• المؤلف :- هشام الخشن\n • سنة النشر :- 2020", "/images/products/9789777952859.webp", "9789777952859", "شلة ليبون", null, 220m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 875, "شريف عرفة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"أبدع المؤلف شريف عرفة في كتابه \"لماذا يريد الرجل وترفض المرأة؟\". مرجعية الكتاب علمية مبسطة، ليدرك القارئ أن العلاقة الزوجية والجنسية غالبيتها عقلية وعاطفية أكثر منها ارتواء جنسي. وحينما يصف المؤلف كل مكونات العلاقة الجنسية فهو يستخدم كلمات حضارية ليس لها علاقة بالشائع من ألفاظ تخدش الحياء.. إن الكتاب تطبيق ثقافي معرفي لعلم النفس الإيجابي سيفيد الكثير من القراء. أهنئك يا شريف\".\nبروفيسور/ أحمد عكاشة\nالرئيس الأسبق للجمعية العالمية للطب النفسي\n \nهذا الكتاب ليس دينيًّا، ولا يهدف للوعظ أو تكرار ما تعرفه مسبقا، بل يتناول الموضوع من منظور الدراسات العلمية الحديثة، بهدف تحسين جودة الحياة وتعزيز السعادة الزوجية.\nيتناول الكتاب موضوعات مثل: (الفرق بين غريزة الرجل والمرأة، الأفلام الإباحية، العادة السرية، علاج الفتور الزوجي، استحضار الرغبة، أورجازم المرأة، دم البكارة، تكوين الشخصية الجنسية، التحكم في القذف، أساليب التواصل الجنسي، تدريبات تحسين الأداء….).\nالمحتوى مناسب للجنسين، للقارئ المتزوج أو المقبل على الزواج، في سن الشباب أو منتصف العمر.\nفهل أنت مستعد لقراءة هذا الكتاب؟\nشريف عرفة", "/images/products/9789777952866.webp", "9789777952866", "لماذا يريد الرجل و ترفض المرأة؟", null, 300m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 876, "أبي فيودور دستويفكى ترجمة أنور محمد ابراهيم مقدمة بوريس تيخوميروف", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"منذ مائة عام، في عام 1920، ظهرت الطبعة الأولى من كتاب لوبوف دستويڤسكايا (1869-1926)، لوبا أو ليليا أو إيميه كما كانت تسمي نفسها، “أبي فيودور دستويڤسكي”، في ميونخ بالألمانية، ليصدر بعد ذلك في طبعات أخرى بالفرنسية والروسية. لقد وضعت ابنة الكاتب الروسي الأشهر (1821-1881) أمام نفسها هدفًا واضحًا هو أن تقدم للقراء حياة أبيها كاملة – من الميلاد وحتى الوفاة. لم تكتف أن تكون مجرد كاتبة مذكرات تعتمد على ذاكرتها الحادة، وإنما سعت لأن تكون كاتبة سيرة، وقد نجحت في أن تبعث إلى الوجود الحكايات التي قصَّتها عليها أمها أنَّا جريجوريڤنا عن حياتها العائلية مع دستويڤسكي: لقائهما الأول، خطبتهما، علاقاتها المتوترة مع أهل زوجها، السنوات الصعبة التي قضياها معا في الخارج، الأحداث التي سبقت ميلاد لوبوف دستويڤسكايا، ما حكاه أبوها لأمها عن طفولته، المعلومات ذات الطابع الحصري التي سيتعرف عليها القارئ هنا للمرة الأولى. لوبوف دستويفسكايا تحكي بالتفصيل عن طفولتها وشبابها، عن والديها، وعن المحيط الذي عاشت فيه. وتكشف في هذا الكتاب عن مشاهد من حياة دستويفسكي لم تكن معروفة إلا لأفراد العائلة.\n• ترجمة أنور محمد ابراهيم مقدمة بوريس تيخوميروف\n • سنة النشر :- 2020", "/images/products/9789777952750.webp", "9789777952750", "حياة دستويفسكى لوبوف فيودوروفنا دستويفكايا", null, 300m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 877, "سماح أبو بكر عزت رسوم", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"خمسةٌ من الأصدقاء كأصابع اليد الواحدة، في المدرسة وفي الشارع أيضًا، كلٌّ منهم يشبه اسمَه في معناه، دخل الهاتفُ حياتَهم ففرَّقهم وكثُرت بينهم المشكلات، حتى جاءت مسابقة الطائرات، فشارك فيها الأصدقاء، كلُّ واحدٍ بطائرته… وفي السماء تجمَّعت الطائرات فأعادت ما كان من حُبٍّ بين الأصدقاء.\nهذه الحكاية حكاية قلوب فرَّقتها صفحة الفيسبوك الزرقاء واجتمعت في حُبٍّ على صفحة السماء.\n• المؤلف :- سماح ابو بكر عزت\n• سنة النشر :- 2020\n\nسندس الشابى", "/images/products/9789777952774.webp", "9789777952774", "قلوب من ورق", null, 185m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 878, "وسيم السيسي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"هذا الكتاب يبحث في أصعب ما يفكر فيه أي إنسان!..\nإحنا مين جسمانيًّا.. جينيًّا.. دينيًّا.. تاريخيًّا.. نفسيًّا..!..\nإحنا مين في هذا الكون اللانهائي؟..\nإحنا مين بالنسبة لهويتنا؟ إلى آخره..!\nقالها سقراط اعرف نفسك بنفسك…\nوقالها وندل هولمز: كل إنسان أربعة..! كما خلقه الله، كما يراه الناس، كما يراه أقرب الناس إليه، كما يرى نفسه.\nهذا كتاب صادم لأن صاحبه يفكر بصوت مسموع، ذلك لأنه لا يشتتـه شيء، ولا يخاف شيئًا!\nهذا كتاب لا يهم صاحبه رضاؤك عنه أو سخطك عليه ولكن يكفي صاحبه رضاء هذه الفئة القليلة من الباحثين عن الحقيقة ويفرحون بها.\nأخيرًا سألوا برنارد شو: ما سر النجاح؟\nقال: أنا أعرف سر الفشل! هو محاولة إرضاء كل الناس!\n• المؤلف :- وسيم السيسى\n • سنة النشر :- 2020", "/images/products/9789777952781.webp", "9789777952781", "احنا مين", null, 155m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 879, "الشيح محمد الخضرى بك / تحقيق محمد أحمد و ايمن فؤاد سيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"التاريخ العباسي جزء عظيم من تاريخ المسلمين يبتدئ من سنة 231هـ إلى سنة 656 هـ، وقد بقي البيت العباسي بعد ذلك له اسم الخلافة بمصر إلى سنة 329 هـ، أحدث ظهور هذه الدولة رجَّة في العالم كلِّه ونهضت العلوم فيها نهضة واسعة ما جعل عصرها بحق “العصر الذهبي للإسلام” وبرز فيها أعلام الرجال من بيوت المجد القديمة والعصاميِّين الذين تسابقوا للتغلُّب على الأقاليم الإسلامية، فكم مِن دولٍ قامت تحت لواء هذه الخلافة، وعظُمت مدنيَّتها ثم انتهت بغلبة غيرها عليها، مرّ على هذه الدولة أحداث جسام. ولم يخل لهم الميدان – أيضًا- من منافسة أبناء عمومتهم العلويين. أو غيرهم من الدول الناشئة كالأدارسة بالمغرب الأقصى، والفاطميين بمصر، أو المجاورين لهم من الروم.\n.. في هذا الكتاب بيان حال العباسيين السياسي من مبتدأ خلافتهم على أيدي دعاتهم بخراسان والعراق إلى منتهاها على يد هولاكوخان المغولي\n• المؤلف :- محمد الخضرى بك\n • سنة النشر :- 2020", "/images/products/9789777952743.webp", "9789777952743", "محاضرات تاريخ الامم الاسلامية الدولة العباسية", null, 385m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 880, "أمانى فؤاد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ستظل قضية المرأة وحقوقها تُطرح للنقاش لإدراكنا أننا بحاجة لإعادة النظر في الأعراف الاجتماعية، وطبيعة الخطاب الديني السائد عن المرأة، وتصوراته عن ماهيتها ووظيفتها وحقوقها، واختزال أدوارها وحصرها في دورها الأسري المحدود، والنظرة الجسدانية لها، والتمييز القائم على أفضلية الرجل، واستلاب استحقاقها في المشاركة السياسية والوظائف القيادية ومناصب القضاء، ووقوعها تحت سلطة التأويل النفعي للنصوص، وهيمنة النزعة الذكورية. نطرح في هذا المؤلّف موقف الثقافة العربية من المرأة، الخطاب الديني، الدولة ومؤسساتها، رؤية المجتمع لها، صورتها في الفكر والأدب، في وسائل الإعلام. هل المرأة نوع وجنس أم كيان ورؤية وبصيرة، شريك وجودي لا تقوم الحياة إلا به؟!.. تساؤلات ورؤى يحاول هذا الكتاب أن يحاورها.\n• المؤلف :- امانى فؤاد\n • سنة النشر :- 2020", "/images/products/9789777952651.webp", "9789777952651", "المراة ميراث من القهر", null, 215m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 881, "لوتس عبد الكريم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"عندما تُصدرُ الكاتبة الدكتورة لوتس عبد الكريم كتابًا ؛ فالمتوقَّع منها قراءة الجديد والمختلف ؛ لأنها تنشرُ أوراقًا مجهُولةً من حياة من اقتربتْ منهم على مدارِ حياتها في مصر والكويت وبريطانيا واليابان وإيطاليا ، ثم أغلب دول الشرق الأقصى ، حيث عاشتْ أغلبَ عُمرِها بين الملكات والأميرات والسَّاسة والقادة والزُّعماء والرؤساء والكُتَّاب والأدباء\n وكتاب \"\" عاشُوا معي \"\" يُمثِّلُ واحدًا في سلسلة كُتبها الناجحة ، الذي يكشفُ العديدَ من الخفايا والخبايا والأسرار في حياة شخصياتٍ مُؤثِّرةٍ في حياتها وحياتنا ، عاشتْ في صُحبتهِم لسنواتٍ طويلةٍ ، ويمكنُ اعتبارُهُ سيرةً ذاتيةً كتبتْهَا عنهُم ، حيثُ هناك جوانبُ غيرُ مألوفةٍ أو معرُوفةٍ أو مُتدَاولة عن هؤُلاء لا يمكنُ للقارئ أن يجدَها في مكانٍ آخر ؛ لأنَّ ماذكرَتهُ في كتابها كانتْ شاهدةً شخصيةً عليه ، وليس مُتواترًا في الكُتبِ والمراجع ؛ فهي تكتبُ عن شخصياتٍ عرفتهَا من قُربٍ.\n إنَّ كتابَ \"\" عاشُوا معي \"\" يُكْمِلُ الجُزْءَ الناقصَ أو المسْكُوتَ عنهُ أو غير المطرُوق في حياةِ أسماءٍ مُؤسِّسةٍ ورائدةٍ في مختلفِ المجالات خُصُوصًا في الأدبِ والموسيقى والفنون التشكيلية والدبلوماسية والسياسة والتاريخ و ...\n ويمكنُ اعتبارُ الكتابِ اعترافاتٍ أو مذكِّراتٍ يربطُ حياة الكاتبة بمن كتبتْ عنهم.\"\n• المؤلف :- لوتس عبد الكريم\n • سنة النشر :- 2020", "/images/products/9789777952729.webp", "9789777952729", "عاشوا معى", null, 115m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 882, "محمود الورواري", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اهل العقل_حوارات مع قادة الفكر الاصولى والتنويرى\n الأصالة والحداثة.. متى يلتقيان؟ في ظل هذا التدافع القائم بين الأصوليين والتنويريين، لا شكَّ أنَّ هناك نقاطَ تلاقٍ بين الفريقين. فسبيلهما واحد، وهو الخروج من الأزمة التي أحاطت بالأمة العربية والإسلامية. من هنا كانت فكرة هذه اللقاءات، لقاءات جمعت أهل العقل تجاوزت حدود الجغرافيا العربية إلى الإسلامية من موريتانيا إلى أفغانستان، وتجاوزت حدود الدين من الإسلام إلى المسيحية، وتجاوزت حدود الأصولية إلى التنويرية فمن شوقي علام وعلي جمعة وعبد الله بن بيه إلى محمد الطالبي وعبد المجيد الشرفي وهشام جعيط، وتجاوزت حدود النوع فلم تغفل جانب المرأة. كل هؤلاء امتطوا العقل لفهم متغيّرات الواقع. قد نتفق معهم وقد نختلف، لكن لا ننكر أنَّ كلَّ واحدٍ من هذه العقول يحمل في طيَّات كلامه جزءًا من\n • المؤلف :- محمود الوروارى\n • سنة النشر :- 2020", "/images/products/9789777952767.webp", "9789777952767", "اهل العقل", null, 275m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 883, "ستانلى ليزبول ترجمة على الجارم تحقيق وتعليق عبد الباقى السيد عبد الهادى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في إطار من الموضوعية والبُعد عن التعصُّب لدين أو قومية، استطاع المستشرق الإنجليزي ستانلي لين بول رسم صورة واضحة وموجزة لتاريخ الأندلس من الفتح العربي الإسلامي حتى السقوط؛ فقد وجه سهام نقده لكلا الجانبين، وأيضًا ذكر الجوانب الإيجابية لهما. وقد جمع في هذا السِّفر تاريخ الأندلس موضوعيًّا، ولم يعوِّل على التأريخ السنوي في معالجة وجيزة غير مخلَّة، سطرتها يمين رجل ليس بعربيٍّ ولا مسلمٍ، لكنه أجاد وأفاد، وحصر من تاريخ الأندلس ما طالت بيننا وبينه الأزمان، من أحداث فتحها، مرورًا بعصور ازدهارها واختلاف الحكَّام عليها، حتى سقوط آخر ممالكها. ألقى فيها الضوء على جوانب عديدة من تاريخ العرب المسلمين بأسبانيا دينيًّا واجتماعيًّا وثقافيًّا وسياسيًّا، مشيرًا إلى الأصوات الدينية المسيحية المعارضة لحكم المسلمين، وكيف تعامل معها المسلمون. واضعًا يده على الأسباب الحقيقية لسقوط الأندلس. هذا الكتاب بمؤلفه المُنصف، ومترجمه الفذّ علي الجارم جديرٌ بأن يكون مرجعًا في تاريخ حقبة مهمة في أوروبا وشمال إفريقيا، ودليلًا لأي قارئ لا يريد سوى الحقيقة.\n • المؤلف :- ستانلى لين بول\n • سنة النشر :- 2020", "/images/products/9789777952644.webp", "9789777952644", "تاريخ العرب المسلمين فى اسبانيا", null, 225m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 884, "عبد الهادى مصباح", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"القلب\" ليس مجرد مضخة للدم فقط – على الرغم من أهمية هذه الوظيفة – ولكن له نظامه العصبي الخاص المستقل، وهو نظام معقد ويشار إليه بـ \"مخ القلب\" ويحتوي على أربعين ألفًا على الأقل من الخلايا العصبية (خلايا الأعصاب) في القلب – بخلاف ما تم العثور عليه منها في مختلف المراكز تحت القشرة المخية من الدماغ. و\"القلب\" يتصل مع الدماغ وبقية الجسم من خلال طرق موثقة بأدلة علمية رصينة، وهي: * عصبيًّا (من خلال بث النبضات والخلايا العصبية). * كيميائيًّا (من خلال الهرمونات والنواقل العصبية). * فيزيائيًّا (من خلال موجات الضغط). * عن طريق الطاقة، ومن خلال تفاعلات المجال الكهرومغناطيسي للقلب. لذا فمن خلال هذه الأنظمة لاتصالات القلب البيولوجية مع المخ وكافة أعضاء الجسم التي تصلها نبضاته، يُحدث القلب تأثيرًا كبيرًا على وظائف المخ، وجميع وظائف وأجهزة الجسم، مما جعل العلماء يكتشفون أن قلوبنا قد تكون في الواقع «القوة الذكية» أو «العقل الذي يقف وراء تلك الأفكار البديهية»، أو «الإلهام الذي يعترينا»، والمصدر الأساسي للمشاعر التي تنتابنا ونشعر بها تجاه الآخرين!\n• المؤلف :- عبد الهادى مصباح\n • سنة النشر :- 2020", "/images/products/9789777952682.webp", "9789777952682", "مخ القلب واعجاز رب الاكوان", null, 185m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 885, "محمد الفخراني", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"لا ينسى أول لقاء لهما، شعر وقتها أنه يجلس مع صديقة يعرفها منذ سنوات، ربما كان هذا الإحساس تحديدًا، وليس الحب، هو ما جعله يطلبها للزواج بعد 14 دقيقة من تعارفهما، نعم، كان الحب موجودًا بطريقة ما، لكن ذلك النوع الغريب المُفاجئ من الصداقة هو ما جذَبَه إليها، تحدَّثا عن الحب، الموسيقا، الناس، الفنون، الكتب، وأشياء صغيرة لم يتحدث أيٌّ منهما عنها من قبل، وأشياء تحدَّثَ كلٌّ منهما عنها من قبل لكن ليس بهذه الطريقة، ورغم أنهما لم يتفقا في كثير من الأفكار، أو ربما بسبب عدم اتفاقهما، كان حوارهما سهلًا، ممتعًا، وله روح ذكية\n كاتب يؤمن بالإنسان، ويعتبره \"\"أجمل فكرة في العالم\"\"، يتقابل مع مُدرِّسة شابة، لها شخصية غير اعتيادية، فيحب كلٌّ منهما الآخر من اللحظة الأولى، يتزوجان خلال أسابيع، ويعيشان في بيت دَفَعا فيه معًا أكثر من نصف مالهما، لتدور بينهما أسئلة، قصص، وأفكار، عن الإيمان، الإلحاد، الحب، والصداقة، مثلما تدور بينهما مباريات البنج بونج في حديقة منزلهما، في الوقت الذي نرى جانبًا من الرواية داخل الجنة والجحيم.\nرواية يروق لها أن تُصرِّح: \"\"الإنسان أجمل فكرة فى العالم\"\n• المؤلف :- محمد الفخرانى\n • سنة النشر :- 2020", "/images/products/9789777952705.webp", "9789777952705", "اراك فى الجنة", null, 155m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 886, "حسنى هاشم محمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "المواطنة مصطلح شاع في عصرنا الحالي، وأصبح الوعي به مسألة في غاية الأهمية لكل أفراد المجتمع. وإذا كان الإنسان الغربي اعتاد هذا المصطلح وعاشه كواقع في حياته المدنية منذ الثورتين الأمريكية والفرنسية فإن الإنسان العربي مازال يسعى إلى فهم والعيش وفقا له. يتميز الكتاب الذي بين أيدينا بخاصيتين اثنتين أولا: أنه كتب بأسلوب حواري ممتع وسلس بين الجد وأحفاده يخلو من التعقيدات الفلسفية النظرية، ويطرح الحديث حولها بلغة سهلة بسيطة يفهمها الجميع من الصبية والناشئة والشباب حتى الإنسان العادي الذي يعرف القراءة والكتابة والفهم. ثانيا: أنه يستعرض الموضوع من كل جوانبه التقليدية والمعاصرة، ويطرح لأحدث ما وصلت إليه مناقشة قضية المواطنة في عصر العولمة والفضائيات والرقمنة التي ترتب عليها صورا ومفاهيم جديدة للمواطنة من بينها المواطنة العالمية والمواطنة البيئية والمواطنة الرقمية. إنه إذن كتاب يطرح قضية المواطنة من منظور جديد ومعاصر وبأسلوب مناسب لكل الأعمار من الحفيد إلى الجد أو من الجد إلى الحفيد!\n• المؤلف :- حسنى هاشم محمد\n • سنة النشر :- 2020", "/images/products/9789772937622.webp", "9789772937622", "المواطنة العالمية البيئة الرقمية", null, 170m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 887, "رشا سمير", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تقاطعت مصائرهم، وتداخلت أقدارهم ليلتقوا مرة أخيرة تحت سماء قمر بعيد.. غرباء وقرباء.. مُهاجرون وعائدون.. حملوا حقائبهم وارتحلوا يبحثون عن مرسى لقلوب سكنها الحنين تارة والعشق تارة والحزن آلاف المرات.. وتبقى معركة أخيرة، لا الفوز فيها للقوي، ولا الهزيمة من نصيب الضعفاء.. بشرٌ يبحثون عن حيواتهم الضائعة وسط أنقاض الذكريات البعيدة.. أبطال هذه الرواية أدركوا في لحظة فارقة، أن أجمل القصص هي تلك التي لم تُرو بعد.. في هذه الرواية تُبحر بنا المؤلفة في أغوار النفس البشرية، لتنسج عالما من السحر، وترسم بقلمها الرشيق خيوطًا من الواقع بمغزل الخيال.. في رحلة تصطحب فيها قلوب قرائها إلى مرساها الأخير.\n• المؤلف :- رشا سمير\n • سنة النشر :- 2020", "/images/products/9789777952712.webp", "9789777952712", "للقلب مرسى اخير", null, 275m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 888, "عمرو العادلى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه رواية اقتناص؛ فهي تقتنص روح كاتب، وترتدي عباءته الشفيفة، بل وتستحضر بعض شخصيَّاته لتُعيد توظيفها من خلال شخصية «مروان» الفلسطيني الشارد، الذي يهجر وطنه من أجل أن يأتي بالمال الوفير ليفوز بحبيبته «صفية»، فتبدأ رحلة تيهه التي يضل خلالها طريقه، فبدلًا من الذهاب إلى الكويت، يجد نفسه في طريقه إلى الأردن، ومنها إلى مصر، حيث يدخل متاهة جديدة من متاهاته المتتالية، يمر خلالها بسراديب «مريم» الحزينة، مستحضرًا طوال رحلته تجسُّدات أُمِّه التي تتهادى أمامه، وتتكثَّف في روحه، بينما يزداد انغماسًا في تيهه الأبدي!\n• المؤلف :- عمرو العادلى\n • سنة النشر :- 2020", "/images/products/9789772937639.webp", "9789772937639", "رجال غسان كنفانى", null, 250m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 889, "علي عطا", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "زرتها، بعد أيام مِن إصابتها بجلطةٍ تركَت نصفَها الأيسر مشلولًا. كانت تنطق بصعوبةٍ. قبّلتُ جبينَها وتبادلنا كلاما معتادا في مثل تلك المواقف. اتضح لي لحظتها أنها زهدت الحياة؛ إلا قليلًا، فلمحتُ طيف \"عقل\" أعلى السرير وعلى وجهه ابتسامةُ رضا. يبدو أنه كان في تلك الأثناء؛ في استراحة نادرة من ضجره المقيم. كانت \"الست\" تشدو: \"كان لك معايا أجمل حكاية في العمر كله\". كان الراديو العتيق إلى جوارها فوق السرير بناءً على طلبها، فيما صورُ زوجها الراحل، وأبنائها وأحفادها موزَّعة على الحوائط. كان بينها صورةٌ فوتوغرافيةٌ لها، في هيئة \"الموناليزا\"، ولكن بابتسامةٍ لا يشوبها ذلك الغموض الذي قصده دافنشي. بعد أيام ستفقدُ النطقَ. سترفض تناول أي طعام، ثم سيحملونها فاقدةً الوعي إلى العناية المركزة، بمستشفى المنصورة الدولي.\n• المؤلف :- على عطا\n • سنة النشر :- 2020", "/images/products/9789777952613.webp", "9789777952613", "زيارة اخيرة لام كلثوم", null, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 890, "ناصر عراق", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في أجواء مثيرة وشائقة وبلغة رشيقة آسرة تخطف الأنفاس من الصفحة الأولى، حيث يمتزج الواقع بالخيال في حكاية عجيبة، تدور أحداث رواية \"اللوكاندة\". فنتعرف على الصراع العنيف بين الوالي عباس حلمي الأول والفلاح البسيط عليوة أبو زهرة، ويذهلنا دهاء الدكتور الإنجليزي وليام براون طبيب الوالي، ونعجب من فرط حيوية أدهم بك العثمانلي المزواج، ونتأمل بسيمة أول فتاة مصرية تدرس مبادئ الأديان السماوية الثلاثة وتتعلم العزف على البيانو، وكيف تعاملت مع شاب تطارده دولة بأسرها. في هذه الرواية يقودنا ناصر عراق بسلاسة نحو حارات القاهرة وأزقتها، فنتجول في درب قرمز بالحسين، ونزور \"اللوكاندة\" التي تتوسط هذا الدرب ونعرف مايدور فيها من صراعات اجتماعية ونفسية حادة انعكست على مصر كلها.\n• المؤلف :- ناصر عراق\n • سنة النشر :- 2020", "/images/products/9789777952668.webp", "9789777952668", "اللوكاندة", null, 275m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 891, "أحمد الملواني", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أربعة أشخاص ينطلقون معًا في رحلة سحرية للبحث عن شجرة الحكمة. رحلة واحدة لكنها مكونة من تشابك رحلة كل منهم الخاصة للبحث عن ذاته. رحلة تطلق الكثير من التساؤلات عن الحرية والمصير والتناقضات الحادة التي تحويها النفس البشرية. رحلة تجسد المعاناة النفسية لأبطالنا، وسعيهم ـ في مرحلة محورية من حيواتهم ـ لإعادة التعرف على ذواتهمبعد روايته السابقة الفائزة بجائزة ساويرس للأدب \"الفابريكة\"، يواصل أحمد الملواني مزج الواقع بالخيال، ليصنع بناء رمزيًّا متشابكًا، ينقل الكثير من الأفكار والرؤى.\nاسم المؤلف:- أحمد الملواني\nسنة النشر :- 2020", "/images/products/9789777952620.webp", "9789777952620", "ما يشبة القتل", null, 215m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 892, "عمار على حسن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يحوي الكتاب حكايات تكشف جانبًا من تاريخنا الاجتماعي المنسي، وينجلي في سطوره كل ما يربطنا بجذورنا البعيدة، ليجعل الحنين يجرفنا نحو زمن ولَّى في غفلة منا، ولن نستعيده أبدًا إلا حين يغوص كلٌّ منا في ذاكرته، التي أضناها الشوق والأسى، بسبب غربتنا الطويلة، خلال سنين نقلتنا من طفولة عفية إلى شيخوخة واهنة. يستعيد الكاتب كل ما عرفه ولمسه عن آلات وحالات وأدوات، سادت ثم بادت، بعد أن جارت عليها الأيام، برصد انفعال البشر معها، وقت أن كانت حياتهم مرتبطة بها. هنا نقرأ عن خمسٍ وستين آلة ريفية، ذهب أغلبها مع ريح عصرنا المتوحش، مثل: النُّورَج والطَّنبُور والسَّاقية والشَّادوف والمِحرَاث والحَصِير والخُص والزِّير والقُلَّة والكَانُون والمَصْطَبة والسَّحَّارة والسِّبرتاية والقُفَّة والطَّبْليَّة والطُّلمْبَة والعَصِيد والرَّحَاية والدَّمَّاسة ولَمبة الجَاز والطَّاحونَة والمَاجُور والنَّامُوسِيَّة والغُرْبَال والسِّيجَة والخُلخَال والكِردَان وغيرها.\nاسم المؤلف :- عمار على حسن \nسنةالنشر :- 2020", "/images/products/9789777952699.webp", "9789777952699", "عجائز البلدة", null, 300m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 893, "عزت القمحاوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "غرفة المسافرين ليس رواية، ليس سيرة ذاتية للمؤلف، ليس كتابا في الرحلة، ليس كتابا في الفلسفة، ولا في العمارة، وليس كتابا حول القراءة، ولكنه كل ذلك. الحكاية هى روح النص، والأماكن حاضرة بما يكفى لكى نشعر أننا انتقلنا إليها، والكتب التي قرأناها سنراها هنا بطريقة مختلفة والتي لم نقرأها سيجعلنا هذا الكتاب نسعى إليهايكتب عزت القمحاوي عن خفة الكائن خارج مكان عيشه الأصلى، عن السفر بوصفه موتا لذيذا نعود منه لنتأكد أن من نضحي بحايتنا من أجلهم يستطيعون العيش من دوننا. يكتب عن الأماكن التى تنادينا لزيارتها وتلك التي نزورها ونغادرها من دون أن نراها. عن \"تمثيل الحياة علي الطائرة\" وعن رفيقتنا الصامتة \"الحقيقة\" ومشاعرها في رحلاتنا السعيدة والحزينة. يكتب عن أشياء صغيرة وأحاسيس سبق أن عشناها، لكننا لم نفكر فيها من قبل، عن طبع العدوان المتأصل في الجمال، عن نظرة التمثال التي ترتد إلينا وتجعلنا نشعر بنقصنا، عن إثارة العيش في جزيرة، عن هاجس البكارة في السفرنص جديد مفتوح على كل فنون الكتابة، يحتفي بمتعة القراءة ومهنة العيش مع حس صوفي يسري داخل النص سريان عصارة الحياه في عروق شجرة مبتهجة\nاسم المؤلف :- عزت القمحاوي\nسنة النشر :- 2020", "/images/products/9789777952675.webp", "9789777952675", "غرفة المسافرين", null, 220m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 894, "الشيح محمد الخضرى بك / تحقيق محمد أحمد و ايمن فؤاد سيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الخضري الذي نهض بالأمر وعقد محاضرات تضمنت أحوال العرب قبل الإسلام سياسيًّا واجتماعيًّا ودينيًّا، ثم تطرق للبعثة النبوية وما صاحبها من غزوات وأحداث، أعقبها بالحديث عن فترة الخلافة الراشدة محقِّقًا مواقف الصحابة بعد وفاة النبي ﷺ، عرض من بعدها لدولة بني أمية من نشأتها حتى السقوط، لاقت هذه المحاضرات نجاحًا واسعًا، ما دعا الشيخ الخضري إلى جمعها في كتابنا هذاصفحات فيها... عرضٌ ونقدٌ وتحليلٌ لأحداث تاريخية اختلط فيها الدين بالسياسة والاقتصاد والاجتماع\nاسم المؤلف :- محمد الخضرى بك \nسنةالنشر :- 2020", "/images/products/9789777952637.webp", "9789777952637", "محاضرات تاريخ الامم الاسلامية الدولة الاموية", null, 365m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 895, "عبد العزيز نبوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أصبحت الأخطاء الإملائية من الفداحة بحيث طالت جميع فنون الكتابة: الأدبية والصحفية والعلمية؛ فليس كثير من المعلمين والمثقفين وأساتذة الجامعات بحريصين على مراجعتها والعمل بها، كما تكثر الأخطاء الإملائية في كثير من الرسائل الجامعية كثرة مفرطة.. كثُرتِ الأخطاء وقلّ الخجل! وفي دراسة أعدت في الكويت منذ عهد قريب - كان لي شرف الاشتراك فيها - بلغت أخطاء تلاميذ المرحلة المتوسطة من %59 من جملة الأخطاء في كتابة الهمزة والتاء المربوطة والهاء.. وليس الأمر مقتصرًا عليهم، فقد تفشت الظاهرة على المستويات كافة للإملاء عدة أسماء، هي: الكتابة الإملائية، والخط، والرسم، والهجاء. ويختلف بعضها من عصر إلى عصر، ومن قطر إلى قطر، بل داخل القطر الواحد والرسم الإملائي ثلاثة أنواع : النوع الأول : الخط القياسي : وهو الخط الذي نستعمله في كتابتنا اليومية النوع الثاني : الخط غير القياسي : وهو خط خاص بالمصحف الشريف (لا القرآن النوع الثالث : الخط العروضي (في ميزان الشعر): وهو خط يطابق المنطوق تمامًا، فكل ما ينطق يُكتب، وما لا ينطق لا يكتب. فكلمة (هذا) مثلًا تكتب عروضًا هكذا (هاذا). ولذا قيل : خطان لا يقاس عليهما خط المصحف، والخط العروضي\nاسم المؤلف :- عبد العزيز نبوى\nسنة النشر :- 2020", "/images/products/9789777952576.webp", "9789777952576", "قواعد الاملاء المعاصر فى العالم العربى", null, 185m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 896, "هاني عبد المريد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين وصل بالقهوة كان فرج ممسكًا بكفها يتحسسه، يقرأ لها الطالع، بينما ضربات القدر لبيتهوفن تعلو\nشربت قهوتها في فنجان فخاري بسيط، نظرت له كثيرًا، لعلها تنتقد بداخلها بساطة المكان، الذي يخلو من الرفاهية، فقط اللوحة التي لم يستطع مقاومتها، تمثال رخامي صغير لأفروديت، غير ذلك كل المساحات مفتوحة، النباتات تنتشر في أرجاء المكان، تضيف بهجة وصفاء، الأرض تفترش بالخيش البني، معظم أدوات المائدة من الفخار والخشب\nكان يحدثها، إن النقص أحد الطرق للكمال، أن القدرة على التقاط الجمال في النقص أكبر الفضائل، حاول أن يوضح إعجابه بالرواية، إعجابه بها هكذا بعيبها البادي له، أنها بدت له ككائن قريب من قلبه، أنه واثق من أن الرواية تقبلته كما تقبلها، وأنها أهدته عيبها حين لمحت حبه لها، كان يتحدث وكانت تنظر له بريبة، بينما فرج يجلسها بجانبه، ما زال ممسكًا بكفها، ومن حين لآخر يربت على ركبتها ليبدو كأب حنون، بينما كانت ابتسامته الماكرة مملوءة بالرضا\nاسم المؤلف :- هانى عبد المريد\nسنة النشر :- 2020", "/images/products/9789777952583.webp", "9789777952583", "من شرفة بيتهوفن", null, 140m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 897, "يوسف كرم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إن هذه السلسلة من كلاسيكيات الفلسفة تأليفًا وترجمة هي أبرز ما قامت عليه نهضتنا الحديثة، وهي ما تربت عليه الأجيال السابقة\nوما أحوجنا اليوم لإعادة نشر هذه الكلاسيكيات من مؤلفات ومترجمات رائدة لتستفيد منها أجيالنا الشابة، وخاصة في ظل ندرة ما يكتبه المتخصصون المعاصرون في الفلسفة ومجالاتها المختلفة، وفي ظل غياب المنهج الفلسفي للتفكير في حياتنا المعاصرة، مما كان السبب المباشر لما نراه من تطرف وتعصب وجمود وعدم تقبل الآخر وفقدان القدرة على التحليل ونقد الأفكار.\nإن الصلة الوثيقة بين الفلسفة اليونانية من جهة وبين الفلسفة الإسلامية من جهة أخرى، وبين الفلسفة الغربية في العصر الوسيط تجعل من الضروري للقارئ أن يكون على صلة بالتراثين اليوناني والإسلامي حتى يكون قادرًا على فهم هذا الجزء من تاريخ الفلسفة.\nإن مؤرخنا قد كتب هذا الكتاب مركزًا على كشف أن قراءة تاريخ الفلسفة الأوربية في العصر الوسيط بدقة يوضح أن التقدم الأوربي في الفلسفة والعلم فيما يسمى عصر النهضة والعصر الحديث لم يأت من فراغ، بل كانت بدايات هذا التقدم وإرهاصاته موجودة عند هؤلاء الفلاسفة، وخاصة بعد اتصالهم بالتراث الفلسفي و العلمي العربي، واطلاعهم على الترجمات والشروح العربية لفلاسفة اليونان واستفادتهم منها، فضلًا عن استفادتهم من إبداعات وآراء الفلاسفة والعلماء المسلمين في شتى المجالات\nإن وصف هذا العصر الوسيط بأنه عصر الظلام والجمود ليس صحيحًا على الإطلاق؛ إذ إن التطور الفكري المتلاحق موجود في أي حضارة، وإن كانت وتيرته تتسارع أو تتباطأ حسب ما يمر بأهلها من أحداث وظروف\nاسم المؤلف :- يوسف كرم\nشرح وتعليق :- مصطفى النشار\nسنة النشر :- 2020\n\nتقديم وشرح وتعليق ا.د. مصطفى النشار", "/images/products/9789772937615.webp", "9789772937615", "تاريخ الفلسفة الاوربية فى العصر الوسيط", null, 215m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 898, "زينب عبد الرزاق", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قدَّم إحسان نموذجًا فذًّا في قبول الآخر\nوتبني الإبداع واحترام الأصوات المختلفة معه\nسياسيًّا. ولم يكن روائيًّا أو كاتبًا سياسيًّا فقط،\nبل كان إنسانًا بمعنى الكلمة. ظلمه النقاد،\nلكن أنصفته الجماهير عندما قرأت إبداعه بحب،\nوأنصفته السينما عندما أصبح أدبه أفلامًا من\nعلامات السينما المصرية.\nهذا الكتاب محاولة لإعادة قراءة مصر\nوتاريخها الحديث من خلال مرآة واحد من أبرز\nأبنائها المبدعين، في وقت تحتفي فيه مصر بمئوية\nالثورة الشعبية الأهم في تاريخها وهي مئوية\nإحسان أيضًا، وكأنه جاء في لحظة قدرية ليكون\nابن الثورة وصوتها الإبداعي الذي لا يخفت\nرغم مرور الزمن.\nاسم المؤلف :- زينب عبد الرازق\nسنة النشر :- 2020", "/images/products/9789777952569.webp", "9789777952569", "احسان عبد القدوس معارك الحب والسياسة 1919-1990", null, 220m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 899, "منى أحمد أبو زيد", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعدّ ابن سينا عبقرية فذة جديرة بالإعجاب، حيث إن له مكانة رفيعة في سجل العباقرة الذين تدين لهم الإنسانية بالشيء الكثير، فقد نبغ في الفلسفة والطب، وألّف في الفقه واللغة والمنطق والأخلاق، وتعمق في الإلهيات، درس الطبيعيات والفلك والأرصاد والكيمياء والهندسة وعلم طبقات الأرض وعلم المناخ، كما كتب في السياسة والاقتصاد، ونظم الشعر وفسّر القرآن. وفوق ذلك كله كان رجل سياسة خاض غمارها وتقلّب بين مهامها. وصل صيته إلى ولاة الحكم في عصره، فدعوه إلى مجالسهم لتتزين به وبعلمه، وتنقّل بين الإمارات الإسلامية في شرق الخلافة الإسلامية، وشغل عدة مناصب علمية وسياسية. وبسبب هذه المكانة المتميزة لابن سينا وعبقريته، فقد تنازعته القوميات الإسلامية المختلفة، فادعى الإيرانيون امتلاكه، وذكر العرب أنه منهم، ونسبه الروس إليهم، وهذا التنازع يعكس الأهمية والمكانة التي احتلها ابن سينا في تاريخ الحضارة!\nاسم المؤلف :- منى احمد ابو زيد\nسنة النشر :- 2020", "/images/products/9789772937479.webp", "9789772937479", "اعلام الفلسفة فى الشرق والغرب - ابن سينا الشيخ الرئيس", null, 165m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 900, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\" تسألني لماذا لم أعد إلى القرية مادمت قد أطلقت الرصاصة التي كانت في جيبي؟!.. هل هذا سؤال؟!.. هل هذا كلام؟! إن معي اليوم آلاف الرصاصات.. ليست في جيبي.. إنها في سلاحي.. ورغم ذلك فقد تعودت من أيام الشيخ علون أن ألتقط من داخل سلاحي رصاصة أحتفظ بها كلما تركته\nإن في جيبي الآن رصاصة.. انظر.. هذه هي.. ويجب أن أعود بها إليه.. إلى سلاحي.. آسف.. لم يعدّ لديّ وقت.. سلام عليكم\nاسم المؤلف :- احسان عبد القدوس\nسنة النشر :- 2020", "/images/products/9789777952422.webp", "9789777952422", "الرصاصة لا تزال فى جيبى", null, 165m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 901, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"وتعودوا بعد ذلك ألا يلحوا عليه بأن يشاركهم التدخين، بل إنه كان يلازمهم دون أن يبدو عليه أنه ممتنع عن التدخين\nكان بذكائه وحيويته يشغلهم عن الإحساس بأنه ليس منهم.. ليس حشاشا.. لم يخطئ إلا مرة واحدة، عندما ضاق بتكاثر الدخان داخل الغرفة ففتح الشباك ليريح صدره، وصاح عبد العزيز جعفر\n مين اللي عايز يطير النعمة من حولنا؟!\nوقال فهمي بسرعة\n   أصل نفسين وقعوا من الشباك وطيت أجيبهم\nاسم المؤلف :- احسان عبد القدوس\nسنة النشر :- 2020", "/images/products/9789777952415.webp", "9789777952415", "حتى لا يطير الدخان", null, 185m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 902, "جين لاسي", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كان «هاشم» يتطلع إلى قدوم أخ صغير ليلعب معه… ولكن المولود الجديد «محمود» صغير جدًّا ولا يمكنه اللعب؛ لذا بدأ «هاشم» يشعر أنه ممل… ترى ماذا يمكن لـ «هاشم» أن يفعل؟  اقرأ قصة «هاشم» وحكايات الأطفال الآخرين، الذين تأثروا بقدوم طفل جديد في الأسرة.\nاسم المؤلف :- جين لاسي\nترجمة :- وفاء اشرف\nسنة النشر :- 2020\n\nترجمة وفاء أشرف رسوم فينيسيا دين اشراف نورا رشاد", "/images/products/9789777952538.webp", "9789777952538", "سلسلة أنا والمولود الجديد", null, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 903, "جين لاسي", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "جاء والد «ديبتي» من الهند.. ولكن «ديبتي» ولدت في هذا البلد، إنجلترا..\nوقد شعرت بصدمة، عندما أخبرها أحد زملائها أن تعود من حيث أتت..\nاقرأ قصة «ديبتي» وقصص الأطفال الآخرين، الذين يعانون من التمييز والعنصرية..\nاسم المؤلف :- جين لاسي\nترجمة :- وفاء اشرف\nسنة النشر :- 2020\n\nترجمة وفاء أشرف رسوم فينيسيا دين اشراف نورا رشاد", "/images/products/9789777952521.webp", "9789777952521", "سلسلة أنا والتمييز", null, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 904, "جين لاسي", 11, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماتت جدة «ليلى»، ولكن أسرتها لا ترغب في أن تخبرها بذلك. وهم يتوقفون عن الكلام، عندما تدخل إلى الغرفة… ليلى تشعر بالقلق والخوف… ماذا تفعل «ليلى»؟  اقرأ قصة «ليلى» وقصص الأطفال الآخرين، الذين فقدوا صديقًا أو فردًا من عائلتهم.\nاسم المؤلف :- جين لاسي\nترجمة :- وفاء اشرف\nسنة النشر :- 2020\n\nترجمة وفاء أشرف رسوم فينيسيا دين اشراف نورا رشاد", "/images/products/9789777952514.webp", "9789777952514", "سلسلة أنا والموت", null, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 905, "أ.د. فتحية النبراوى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إن الخط الرئيسي الذي يجمع فصول هذا الكتاب “أحد عشر فصلًا” هو التأكيد على أصالة النظم الإسلامية، وأن نشأة هذه النظم بدأت مع قيام الدولة الإسلامية في المدينة، ثم طورها المسلمون عبر العصور الإسلامية المختلفة.إن النظم الإسلامية هي أنماط فكرية حرة قدمها المسلمون، وعلى المفكرين المحدثين أن يعيدوا قراءتها والنظر فيها من أجل عالم يتمتع بالاستقرار مع الحرية والعدالة  وفي هذا الصدد تضاعف مسئولية المؤرخ المعاصر من أجل إبراز قيمة الحضارة الإسلامية بنظمها وقيمها ومفاهيمها التى تقدم الحلول لكثير من مشكلات العالم المعاصر\nاسم المؤلف :- فتحية النبراوى\nسنة النشر :- 2020", "/images/products/9789777952545.webp", "9789777952545", "تاريخ النظم والحضارة الاسلامية", null, 330m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 906, "مصطفى الفقى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "للدكتور مصطفى الفقي باع طويل في الحياة السياسية والثقافية على حدٍّ سواء. أما في المجال الأكاديمي، فقد قام بتدريس العلوم السياسية لسنوات طويلة بالجامعة الأمريكية بالقاهرة، ثم تولى رئاسة الجامعة البريطانية بمصر في السنوات الثلاث الأولى لإنشائها. وفي المجال السياسي، شغل منصب سفير مصر في النمسا وعدد من الدول الأجنبية الأخرى، كما كان مندوب مصر لدى الوكالة الدولية للطاقة الذرية، ثم مندوبًا دائمًا لها في جامعة الدول العربية.\nوقد اتجهت أنشطته في السنوات الأخيرة إلى العمل البرلماني ومؤتمراته الدولية؛ حيث ظل يشغل منصب رئيس لجنة العلاقات الخارجية بالبرلمان لمدة عشر سنوات. وكرَّس حياته لقضيتين أساسيتين؛ الأولى هي قضية الإصلاح الفكري والسياسي، وإيقاف كلِّ أشكال التمييز ضد الأقليات في المجتمع. أما الثانية فهي حول القضية العربية ومفهوم الوحدة في إطارها المعاصر.\nوعلى الصعيد الوظيفي، شغل الدكتور مصطفى الفقي منصب سكرتير رئيس الجمهورية المصرية للمعلومات، ومدير معهد الدراسات الدبلوماسية بوزارة الخارجية، إلى أن تولى منصب مساعد أول لوزير الخارجية، وفي عام 2017 شغل سيادته منصب مدير مكتبة الإسكندرية. وقد ترأس جمعية الصداقة المصرية النمساوية في السنوات العشر الماضيات، وكان عضوًا في المجلس القومي لحقوق الإنسان، واتحاد الكتاب، والمجمع العلمي المصري الذي تأسس عام 1798، والمجلس الأعلى للثقافة، وقد رشحته مصر رسميًّا لمنصب أمين عام جامعة الدول العربية عام 2011.\nنال الدكتور مصطفى الفقي عددًا من الأوسمة، كما حصل على جائزة «النيل العليا» في العلوم الاجتماعية عام 2010، وجائزة «الدولة التقديرية»في العلوم الاجتماعية عام 2003، وجائزة «الدولة التشجيعية» في العلوم السياسية عام 1993، كذلك نال عشرات الأوسمة والنياشين من عدد كبير من الدول العربية والأجنبية.وله ما يزيد على ستة وثلاثين كتابًا في مجالات السياسة والفكر والثقافة.\nاسم المؤلف : مصطفى الفقى \nسنة النشر : 2019", "/images/products/9789777952453.webp", "9789777952453", "دهاليز السياسة وكواليس الدبلوماسية", null, 360m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 907, "صلاح إسماعيل", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "دراسة فلسفية لطبيعة المعرفة، وأنواعها، وشروطها وهي الاعتقاد، والصدق، والتسويغ. ويناقش أبرز النظريات التي قدمها الفلاسفة المعاصرون في تحليل هذه الشروط. ويجيب عن الأسئلة المتعلقة بالفهم والتفسير والمعرفة العلمية. ويتعمق أهم فروع الإبستمولوجيا المعاصرة مثل الإبستمولوجيا الطبيعية والإبستمولوجيا الاجتماعية.\nزد على ذلك أن المؤلف يعالج مفاهيم المعرفة من خلال التحليل اللغوي والمنطقي. ويدافع عن رؤية للفلسفة بوصفها توضيحا مفهوميًّا بالإضافة إلى نزعة طبيعية. ويقدم مذهبًا إبستمولوجيًّا سماه المذهب الطبيعي المعتدل، يأتي فى إطار صورة معتدلة من النزعة العلمية.\n• المؤلف :- صلاح اسماعيل\n • سنة النشر :- 2019", "/images/products/9789777952477.webp", "9789777952477", "نظرية المعرفة", null, 330m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 908, "جلال الشايب", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل سبق أيها القارئ أن سببت لنفسك الذعر حول شيء ما لم يحدث مطلقًا؟ أو أصبت نفسك بحالة من الهلع حول شيء ما اعتقدت أنه قد يحدث يومًا، إلا أنه لم يحدث أبدًا؟ أو أخبرت نفسك قصصًا مخيفة ستحدث لك في المستقبل البعيد؟ أو تصورت ما ستفعله إذا خسرت وظيفتك، أو أصبت بمرض عضال، أو فقدت شخصًا عزيزًا عليك؟ إذا كنت قد فعلت ذلك، أو تفعله الآن، فمرحبًا بك في نادي القلق، الذي ربما يكون النادي الأكبر على سطح كوكب الأرض، فجميع البشر تقريبًا أعضاء به\nماذا بوسعنا أن نفعل لكي نتوقف عن القلق؟! هل من طريقة ناجحة للتوقف عن القلق الذي يفسد كل حياة هانئة ويعيق كل حياة سعيدة؟! .. في هذا الكتاب، قد تجد إجابة على هذا السؤال\nاسم المؤلف :- جلال الشايب\nسنة النشر :- 2020", "/images/products/9789777952446.webp", "9789777952446", "نادى القلق", null, 150m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 909, "شرف الدين عبد الحميد", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتناول هذا الكتابُ الفلاسفةَ اليونانيين الأوائلَ، قبل سقراط، الذين شكلوا الوعي الأوربي، بل العالمي؛ فهم الأجدادُ والآباءُ المؤسسون لصرح الفلسفة العالمي. ويتضمن محاولةَ إعادةِ بناءٍ وتأويلٍ جديد؛ يتأسس على\nاستثمار النص الفلسفي، واستشراف السياق الديني الأسطوري السابق على النص الفلسفي، وإعادة بناء الدلالة الفلسفية.\nيحاول المؤلف هنا تطويرَ ما يسمى بـ «الهرمنيوطيقا الفلسفية»، ويطمح إلى تأسيس: تأويل جديد بديل للتأويل الأرسطي الشائع، من خلال منهج هرمنيوطيقي يؤول الشذراتِ الباقيةَ من فلسفة الفلاسفة اليونان الأوائل.\nإن فترة الفلاسفة اليونان الأوائل هي فترة تأسيسية للعلم اليوناني، وللفلسفة اليونانية. لذلك هي فترة بالغة الأهمية في تاريخ الفكر الإنساني كله. فإن لم نفهم هذه الفترة، المؤسسة للحضارة الأوربية المعاصرة، حقَ الفهمِ نكون قد أغفلنا الأساسَ الذي قامت عليه حضارةٌ معينةٌ، هي الحضارة الأوربية، وتأثرت بها حضاراتٌ مختلفةٌ، ومغايرة  كالحضارة الإسلامية. وفي ذلك جرمٌ قد نرتكبه في حق الوعي ولو دون قصد!\nإننا أمام كتاب مهم في تاريخ الفلسفة اليونانية يمثل إضافةً حقيقيةً للمكتبة العربية بما يمتلكه مؤلفه من رؤى تأويلية جديدة، ومن قدرة فائقة على الخوض في أدق التفاصيل والإبحار اللامحدود، في محاولة فهم المصطلحات وتعميق دلالاتها المختلفة لتقديم أوفى وأكمل صورة لبيان مذهب هذا الفيلسوف أو ذاك، وذلك في لغة فلسفية رصينة وأسلوب سلس\nاسم المؤلف :- شرف الدين عبد الحميد\nسنة النشر :- 2020", "/images/products/9789777952392.webp", "9789777952392", "تأريخ الفلاسفة اليونان الأوائل - قبل سقراط إعادة بناء وتأويلُ جديد", null, 275m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 910, "أشرف العشماوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "محّقِق قضائي يحاول تتبُّع جرائم جنائية في قريةٍ صغيرةٍ بشمال الصعيد، فيُفاجأ بما هو أخطر، حوادث قتلٍ بغير باعثٍ منطقي، وحالات انتحار مُريبة، واحتراق زراعات وبيوت بدون سببٍ واضح، لتك حالة الشَّك المصاحبة للجميع بمَن فيهم المُحقِّق، الذي يتقاطع مصيره مع سيدةٍ قبطيَّةٍ غامضةٍ. في هذه الرواية، يغوص الكاتب أشرف العشماوي في نفوسٍ مُعقَّدةِ التركيب، مُستعينًا بشخصياتٍ ثانويَّةٍ آسرة، رسمها ببراعةٍ فكادت تتحرَّك على الورق، ثم منحها البطولة فترات قصيرة قبل أن تعود لتتوارى بين الجموع، ناسجًا أحداثه في عوالم جديدةٍ مُدهشة، ومُفارقاتٍ مُضحكةٍ مُبكيةٍ، عَ إيقاعٍ سرديٍّ جذَّاب، يُثري الفكر ويُثير الخيال، تاركًا مساحة رحبة من التأويل للقارئ.\n• اسم المؤلف :- شرف الدين عبد الحميد\n• سنة النشر :- 2019", "/images/products/9789777952460.webp", "9789777952460", "بيت القبطية", null, 225m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 911, "لورنس كورباندى كوديس", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتناول الكتابُ الأدبَ الإفريقي الحديث بقلم أحد مبدعيه، هو الشاعر والدبلوماسي الأستاذ «لورنس كورباندي كوديس»، ففي فصله الأول يبدأ بتعريف الأدب الإفريقي الحديث، وما حدوده الجغرافية، وسماته، وجذوره القديمة وأثرها في الأدب الحديث، كما يتناول أثر التدخل الاستعماري الإنجليزي والفرنسي على مدار بدايات القرن الماضي، في تكوين فكر أدباء هذا الإقليم، وما هي التحديات التي فرضها الواقع الاستعماري من موضوعات وأفكار وحتى اللغة المستخدمة.\nأما الفصل الثاني فيتحدث عن عناصر الأدب الإفريقي بشيءٍ من التفصيل، فيبدأ بالشعر وموضوعاته المختلفة، وتمجيد اللون الأسود المميز لأهل إفريقيا، ونشوء المسرح وعوامل دخوله للقارة ومراحل تطوره.. ولأن الفن يشمل الحرف اليدوية أيضًا، فلم يدعها الكاتب بدون أن يُجْمل الحديث عن تاريخ بعضها وحاضره.\nهذا الكتاب إرهاصة وتوطئة لأي باحث أو مهتم بالشأن الإفريقي عامة، والأدب الإفريقي الحديث خاصةً.\nاسم المؤلف :- لورنس كورباندى كوديس\nسنة النشر :- 2020", "/images/products/9789777952439.webp", "9789777952439", "دراسة فى الادب الافريقى الحديث", null, 95m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 912, "صلاح فضل", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب معاهدة سلام وصلح وتقارب بين لهجتنا العامية ولغتنا الثقافية العليا؛ فشعراؤه: \"بيرم التونسي\" و\"صلاح جاهين\" و\"فؤاد حداد\" استخدموا مستوى من العامية شديد القرب من الفصحى بكلماتها وتعبيراتها ومجازاتها وفنونها القولية وأمثال وثروة لغوية لا ينبغي إهدارها؛ فالأدب الشعبي مظهر عبقرية الشعوب، بل نذهب إلى أبعد من ذلك فنجد بعض النماذج من الأدب العامي غذَّى اللغة الفصحى وفنونها بأساليبه وأنماطه، وبعضها ضخَّ في العربية دمًا حارًّا ساخنًا منحها قدرًا عظيمًا من الحيوية. كما لا ينبغي أن يؤخذ هذا الكتاب على أنه دعوة إلى أن تحل اللهجات العامية محل اللغة البليغة الفصيحة. فلنقل إذًا إنه دعوة إلى إعادة النظر إلى أن ثنائية اللغة بين الفصحى والعاميات المختلفة في أقطار الوطن العربي لا يمكن أن تُعد ظاهرة سلبية أو شرًّا لا بد منه، بل هي نعمة كبرى احتضنت الطاقات الخلاقة للمبدعين في المستويات المختلفة؛ فشوقي مثلًا طعَّم مسرحيته الفكاهية \"الست هدى\" بعبارات عامية شائقة. ولعل هذا الكتاب يكون بداية انتهاء عصر الحروب اللغوية بين الفصحى والعامية، وتشجيعًا للعامية كي تنتقل من مجرد أدوات للتواصل اليومي إلى كنوز فنية وأدبية آن لها أن تخرج من السوق إلى المتحف بجماليتها ورونقها\nاسم المؤلف :- صلاح فضل\nسنة النشر :- 2020", "/images/products/9789777952385.webp", "9789777952385", "شعر العامية من السوق الى المتحف", null, 215m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 913, "محمد عبدة بدوى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يهتم هذا الكتاب بالكشف عن آثار الدور الجديد للإعلام على الشباب العربي، والتعرف على طبيعة العلاقة بين التعرض للفضائيات العربية الإخبارية ومواقع التواصل الاجتماعي من جهة، ومستويات المشاركة السياسية لدى الشباب العربي في مصر وتونس نموذجًا من جهة أخرى. قام المؤلف بتقسيم هذا الكتاب إلى خمسة فصول تناول الفصل الأول منها مفهوم الشباب، ومفهوم المشاركة السياسية وأبعادها ومستوياتها. واستهدف الفصل الثاني الشباب العربي والمشاركة السياسية التقليدية، ودور الشباب في ثورتي مصر وتونس، ومقترح لتمكين الشباب سياسيًّا. واستعرض الفصل الثالث مفهوم المجال العام والأطراف الفاعلة فيه، وطبيعة المجال العام في العالم العربي، وعلاقة وسائل الإعلام التقليدية والمستحدثة بالمجال العام. ورصد الفصل الرابع واقع الإعلام المرئي في مصر وتونس قبل الثورتين وبعدهما، وطبيعة النشاط السياسي للشباب العربي على وسائل التواصل الاجتماعي. وتناول الفصل الخامس الواقع التطبيقي للمشاركة السياسية للشباب في مصر وتونس مختتمًا هذا الفصل بطرح رؤية مستقبلية. اسم المؤلف :- محمد عبدة بدوى سنة النشر:- 2019", "/images/products/9789777952408.webp", "9789777952408", "الاعلام والمشاركة السياسية للشباب مصر - تونس نموذجًا", null, 250m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 914, "طارق إمام", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتقاطع \"طعم النوم\" مع \"الجميلات النائمات\"\nلكاواباتا و\"ذاكرة عاهراتي الحزينات\" لماركيز\nمعًا، لتُقدِّم معارضةً روائية تستلهم \"ألف ليلة\nوليلة\" حكائيًّا. لكن \"إمام\" هذه المرة يقلب\nلعبة الروايتين السابقتين مُنطلقًا من وجهة النظر\nالعكسية بالضبط، والمسكوت عنها \"روائيًّا\".\nهذه المرة، الفتاة النائمة هي من تكتب روايتها،\nمستعرضةً تقاطع التاريخ الشخصي بتاريخ وطن\nوجرح الذاكرة الفردية بألم الذاكرة الجمعية، على\nشرف مدينة قلِقة هي \"الإسكندرية\"، المتخبّطة\nفي سؤال هويتها، والتي تحضر هنا بط حقيقيًّا\nوليس مجرد مسرح للحدث.\nإنها رواية جميع النساء اللائي لم يتحدثن أبدًا:\nرواية حُب وجريمة، تأريخ وتأمُّل، يمتزج فيها الواقع بالخيال، وتسردها يدُ الشعر.\nاسم المؤلف :- طارق امام\nسنة النشر :- 2020", "/images/products/9789777952316.webp", "9789777952316", "طعم النوم", null, 300m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 915, "عبد الجبار ناصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"خالد جاسم\" صحفي عراقي.. عاش في العراق سنوات طفولته وصباه وشبابه تحت سطوة نظام صدام وقهره..\nكان يبحث عن إجابة لسؤال ظل يرافقه عن \"ما الوطن؟\".. حاول أن يعثر على الإجابة في أستراليا حين ذهب إليها لاجئًا،\nوعندما أخفق عاد إلى العراق، بعد سقوط صدام، عله يجد ضالته..\nوجاءته الإجابة التي لا يعرف أحد منا: هل كانت إجابة شافية أم ناقصة.. هو وحده يعرف ذلك.\nهذه دعوة لترتحل معنا في آفاق أحداث هذه الرواية؛ علك تعرف إجابة السؤال التي أخفقنا –مع بطل روايتنا- في إدراكها\nاسم المؤلف :- عبد الجبار ناصر\nسنة النشر :- 2020", "/images/products/9789777952156.webp", "9789777952156", "فندق كاليفورنيا", null, 250m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 916, "حسن شحاتة", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليس هناك مقياس أكثر دلالة على أهمية التعليم من أنه السمت المميز لمكانة أي دولة في المجتمع الدولي، والدال الأقوى على رفعة شأنها أو انخفاض قدرها في هذا المجتمع.  وانطلاقًا من هذه البدهية، نقدم لك كتابنا هذا، مترسمًا البحث لا عن التعليم وأهميته فحسب، وإنما أيضًا البحث عن أمثل أسلوب لجعله متعة وبهجة ونمطًا حياتيًّا رائعًا لدى المتعلم والمعلم معًا.. نحدد لك مصادر متعة التعليم، ونضع ملامح ثقافة تحقيق تلك المتعة، شارحين لك فنيات التواصل لمكونات هذه الثقافة، من خلال تطبيقات عملية اشتققنا لها مصطلح \"مباريات\".. علّ ذلك كله يرسم الطريق البين إلى الاستمتاع بالتعليم، فيضمن لنا تحقيق أفضل عوائده وأبقاها..  ألا وهو المتعلم المستمتع المستدام الناقد المتعدد الرؤى المبدع..  ذخيرة أية أمة تبتغي الريادة والسبق.. علنا وفقنا في ذلك...   اسم المؤلف :- حسن شحاتة                                                   سنة النشر  :- 2019", "/images/products/9789777952309.webp", "9789777952309", "متعة التعليم والتعلم خبرات وتجارب ورؤى", null, 300m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 917, "محمود الوروارى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعرض الكتاب في توثيق غير مسبوق ظهور  الأفكار والحركات والتيارات السلفية بدءا من عام 1852 وصولا إلى حالها اليوم.\nمنذ ما قبل تأسيس الجمعيات ، يأخذ هذا الرصد منهجا توثيقيا اذا يتم ذلك برواية أصحاب ومؤسسي كل تيار. وهو يركز على السلفية ككيان مؤسسي  مثل الجمعية الشرعية \"جماعة أنصار السنة المحمدية\" والدعوة السلفية وغيرهم .أو يركز على التيار الحركي مثل السلفيـة العلميـة ، السلفيـة الحركيـة ، السلفيـة الجاميـة أو المدخلية.كل ذلك دون تجاهل السياق الزمني والتاريخي لمصر والمنطقة العربية وعلاقة التيار السلفي بجماعة الإخوان المسلمين  متى اتفقوا؟ ومتى اختلفوا؟ومواقفهم من المسارات السياسية الكبرى منذ عهد عبدالناصر وحتى العهد الخالي .. أسرارٌ مثيرة ومفاجآتٌ ستتكشف لك -أيها القارئ- وتتفجر!\nاسم المؤلف :- محمود الوروارى\nسنة النشر :- 2019", "/images/products/978977752354.webp", "978977752354", "سلفيو مصر", null, 275m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 918, "رضوى فرغلى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "التقيتُ آباء كثيرين لا يدخرون جهدًا أو مالًا أو عواطف لمساندة أبنائهم واحتواء مشاكلهم والبحث عن أي وسيلة تخفف عنهم الألم وتساعدهم على تحسين قدراتهم، وإن تنقصهم المعلومات والخبرة فإنهم يبحثون عن مصادرها ليحققوا أعلى درجة دعم لأولادهم. على الجانب الآخر، قابلتُ آباء وأمهات يسيطر عليهم الاكتئاب، أو الإحساس بالذنب ولوم أنفسهم، أو الغضب والإلقاء بالمسئولية على شخص ما، لما آل إليه مصير طفلهم ويغلب عليهم العِناد في الاعتراف بآدميته، فيعاملونه بقسوة لا يُعامل بها \"الحيوان\"! ومع ذلك فإن الصورة ليست سوداء تمامًا، لأنني لاحظتُ من خلال التواصل المباشر مع عائلات الأطفال المتأخرين أن بعض الأسر التي تُكن مشاعر سلبية للطفل، يتغير موقفها إيجابيًّا بعد خضوعهم لجلسات إرشاد نفسي حتى يتخطوا مرحلة الصدمة، لأنهم في النهاية بشر يحتاجون إلى المساندة النفسية. وراعيتُ في الكتاب أن يكون سلسًا مبسطًا ليناسب كل الأُسر من مختلف الفئات الاجتماعية، يأخذ بيدهم نحو فهم ظروف أبنائهم والمشكلات التي تواجههم وكيف نخفف منها.\nاسم المؤلف :- رضوى فرغلى\nسنة النشر :- 2019", "/images/products/9789772937608.webp", "9789772937608", "الصحة الجنسية والنفسية", null, 220m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 919, "محمد كسبر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مسيرة فلان العلاني في برشلونة - نتاج ورشة كتابة المصرية اللبنانية\n\"لكل منا لحظتان للميلاد، لحظة الميلاد الحقيقية، وهذه تفرض علينا ولا نختارها، ولحظة الميلاد المختارة وهذه هي التي نختارها بإرادتنا، قد يكون الميلاد في وظيفة طالما تمنيتها، أو امرأة طالما اشتهيتها، أو حتى سيارة حلمت باقتنائها.\nولقد شاهدت وعاصرت الكثير من البشر سعوا بشتى الطرق من أجل الحصول على هذه اللحظة، لحظة الميلاد المختارة، لكنهم ماتوا قبل الوصول إليها، سبقت الوفاة لحظة الميلاد، وكان هدفي ألا أكون واحدا منهم\".\n***\nهي رواية تُرجّع أصداء رواية البيكاريسك، من دون كيشوت وحتى خيري شلبي وبينهما الكثيرون، حيث السارد الصعلوك المتجول، السارد الرائي والذي لا يملك في رحلته سوى سيفٍ من خشب. لا فضل هنا للغة على أخرى، فالفصحى تلد العامية والعكس، عالمٌ عرضة للتهكم يردد أحيانًا صدى بعيدًا من روح ألبير قصيري الساخرة والعدمية ومن انحيازه للمدينة «المبتذلة» المختبئة تحت واجهتها المضيئة والكاذبة. طارق إمام\nاسم المؤلف :- محمد كسبر\nسنة النشر :- 2019", "/images/products/9789777952286.webp", "9789777952286", "مسيرة فلان العلانى", null, 200m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 920, "محمد غربى", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تعد مناهج البحث الإعلامي من المناهج العلمية الحديثة التي بدأ استخدامها بعد تطور الوسائل المختلفة في بداية القرن العشرين، حيث ارتبطت بحوث الإعلام بالتطورات العلمية والتكنولوجية التي ساهمت في بناء المجتمعات وتقدمها، بسبب تنوع وتقدم وسائل الاتصال والإعلام الجديدة مما تحدثه هذه الوسائل من تأثير على الجمهور، فضلًا عن التنافس بين هذه الوسائل ذاتها، الأمر الذي استدعى ظهور مراكز بحوث الرأي العام والدراسات الإعلامية للتعرف على اتجاهات الجمهور نحو هذه الوسائل، وكذلك معرفة الصورة الذهنية تجاهها. ويقدم هذا الكتاب نظرة شاملة ومتوازنة للإجراءات المنهجية في البحوث والدراسات الإعلامية المختلفة في معالجتها لقضايا ومشاكل المجتمع وصولًا إلى الدور الوظيفي للبحث العلمي في خدمة وتقدم المجتمعات الإنسانية.                                                           اسم المؤلف :- محمد حلمى , وجدى غريب                                سنة النشر :- 2019\n\nوجدى حلمى", "/images/products/9789777952293.webp", "9789777952293", "مناهج البحث الاعلامى", null, 385m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 921, "عباس محمود العقاد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"من هؤلاء الناظرين بأعينهم إلى النور بعد منتصفِ القرنِ التاسعَ عشرَ، بل في الطليعة من أولئك الناظرين البصراءِ إلى حقائقِ زمانِهم، نابغتُنا الريفيُّ الأزهريُّ الذي عَلِم عِلْمَ اليقين، بل آمن إيمانَ الدينِ المتين، أن «التقدمَ العصريّ» رهينٌ بعلوم لنا أهملناها وهجرناها، وعلومٍ للمعتدين علينا سبقونا إليها ولم نلحقهم في غير القليل منها، وهي حقيقةٌ من بديهيات أيامنا هذه بعد منتصف القرن العشرين، ولكنَّ نابغتَنا الريفيَّ الأزهريَّ -محمد عبده- كان يقررُها بعد منتصفِ القرنِ التاسعَ عشرَ فيجد أمامه من يخاطبُهم بمثل ذلك المقالِ الذي كتبه في صحيفةِ الأهرام الأسبوعيةِ، وتحرَّى فيه أن يكتبه بأسلوبه المخضرمِ بين القديم والحديث، فقال:\n«ليت شعري إذا كان هذا حالَنا بالنسبة إلى علوم قد أُرضعت ثُدِيَّ الإسلام وغُذيت بِلِبانِه وتربَّت في حِجْره وتُقلِّدت في إيوانِه منذ زمنٍ يزيد على ألف سنة... فما حالنا بالنسبة إلى علوم جديدةٍ مفيدةٍ هي لوازمُ حياتِنا في هذه الأزمان.... لا بد لنا من اكتسابها وبذلِ المجهود في طِلَابها؟\"..\nاسم المؤلف :- عباس محمود العقاد\nسنة النشر :- 2019", "/images/products/9789777952323.webp", "9789777952323", "محمد عبدة", null, 200m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 922, "أسعد خليل داغر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"يرمي كتاب \"تذكرة الكاتب\" إلى إصلاح غلطات شاع استعمالها في أقلام الكُتَّاب والأدباء والشُّعراء، وعلى ألسنة المتكلِّمين والخُطَبَاء. وقد سار مؤلِّفه في التصويب والتخطئة في ركاب فريق من علمائنا القدامى مال إلى التشدد، ولا يقبل من الألفاظ والتراكيب إلَّا ما نُقِلَ وسُمِعَ عن العرب، ووفق شروط ارتضاها. والذي دفع هذا الفريق إلى التشدد الخوف على اللغة من الضياع بما يدخل عليها، والحفاظ على نقائها خالية من أكدار اللحن وشوائب الغلط.\nوقد لقي الكتاب قبولا في أوساط الغيورين على اللغة العربية والمهتمين بها والذَّائدين عن حماها، فأثنى عليه العلَّامة أحمد باشا تيمور الذي قال مخاطبا مؤلِّفه: \"قرأتُ كتابَك \"تذكرة الكاتب\" وأنعمتُ النَّظر فيه امتثالًا لإشارتك، لا تطاولًا للحُكْمِ في مثله. فإذا قلتُ إنَّك أَجَدْتَ وأَفَدْتَ وأَصَبْتَ كُلَّ الإِصابة فيما قَصَدْتَ فإنَّما أقولُهُ على ما ظهر لي، ووصل إليه عِلْمِي، وفوق كُلِّ ذي عِلْمٍ عليم\".\nوقال الأستاذ عبد القادر المغربي عن الكتاب: وهو \"من خيرة الكتب التي أُلِّفَت في هذا الموضوع من حيث وفرة مواده، وإيجاز عبارته، وحُسْن دلالته على مواقع الصواب، بعد دلالته على مواقع الخطأ\"\nاسم المؤلف :- اسعد خليل داغر\nسنة النشر :- 2019", "/images/products/9789777952279.webp", "9789777952279", "تذكرة الكاتب", null, 185m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 923, "نور عبد المجيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"\"هل تظن أن الجريمة هى الشيء الوحيد الذي لا يولد كاملا؟\n أحمق من يظن هذا\nجرائم كثيرة وكبيرة كامله لهذا لم نعرف أو نسمع عنها شيئا..\nالناقص دوما هو السعادة\nهو الفرحة التي تنتظرها وتعمل من أجلها كثيرا..\nناقصة ونقصانها نعمة كبرى..\nنحن إن اكتفينا انتهينا\nبهاء الأشياء والمشاعر والعلاقات قد يكون أحيانا في النقصان لا الاكتمال..\nحتى \"البدر\" إن اكتمل غاب وعاد هلالا..\nقواعد ننساها وربما لجهلنا وضعفنا نتناساها\nاسم المؤلف :- نور عبد المجيد\nسنة النشر :- 2019", "/images/products/9789777952248.webp", "9789777952248", "انت منى", null, 275m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 924, "هالة البدري", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "دعوني أبوح لكم بسر عن نساء، في الليل، يأتين لزيارتي. لي مع كل واحدة منهن قصة طويلة. على الحائط لوحة ضخمة رسمتها جورجيا أوكيف أم الحداثة الأمريكية التي حاصرها حبيبها في خانة الأنثى فهربت إلى الصحراء لترسم، حتى رحلت عام 1986.\nفي مكتبتي رسالة ماجستير تجمعني بالشاعرة والروائية النمساوية إنجبورج باخمان، التي ماتت محترقة عام 1972 عن 47 عامًا في كوخها بإيطاليا. وفي المكتبة أيضًا روايات للكاتبة المصرية قوت القلوب الدمرداشية، التي انقلبت حياتها من أميرة إلى امرأة مطاردة، بسبب تحدي حبيبها لعبد الناصر، وماتت مقتولة على يد ابنها في روما عام 1968.يأتين إلى بيتي في المساء مُضمَّخات برغبة قوية في الحكي. يأتي معهن عشاقهن، وأصدقاؤهن، وأزواجهن. فتختلط حياتهم بحياتي، ويصبحون من أقرب أصدقائي، نكون عالمًا واحدًا، ليصبح السؤال فيه عما جمعنا معًا ذا معنى\nاسم المؤلف :- هالة البدرى\nسنة النشر :- 2019", "/images/products/9789777952255.webp", "9789777952255", "نساء في بينى", null, 225m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 925, "وسيم السيسي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا يكتسب الحديث قيمته إلا من خلال أمرين: إما جدته غير المسبوقة أو أهميته التي يستشعرها كل من القارئ والمؤلف .. وقد جمعنا لك – في الكتاب الذي بين يديك – الأمرين معًا: أولهما، الكتاب يضم تلك  الموضوعات التي لا يعرفها غير متخصصين على درجة عالية من التخصص، تعرض لك بأسلوب حميمي لا يخاطب عقلك فحسب، وإنما يتوجه كذلك إلى وجدانك؛ لأنه يكتب سيرة ذاتية لهذا الوطن العبقري الرائع الذي نحيا فوق أرضه.. في كل مجالات الحياة من دين وعقائد وعلوم واجتماع وسياسة واقتصاد..وثانيهما ليس هناك أهم من قراءة تاريخ غير انتقائي وغير مزيف وغير متحيز، يرسخ لقواعد الانتماء والعشق اللذين نستشعر الآن افتقادهما - لدى البعض - تجاه الوطن..\nالكتاب دعوة لأن تسجل كل حدث رائع في تاريخ الوطن، تستلهم منه الأمل والطاقة والقدرة على أن تضيف، وفي الوقت نفسه، دعوة أيضًا لأن نقرأ بوعي أخطاء الماضي ومآخذه، فنستلهم منها، جميعًا دون استثناء، العبرة والدرس؛ كي لا نقع فيها ثانية.. وهل هناك معلم أعظم من التاريخ!!\nاسم المؤلف :- وسيم السيسى\nسنة النشر :- 2019", "/images/products/9789777952262.webp", "9789777952262", "المسكوت عنه فى تاريخ", null, 200m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 926, "ابراهيم مصطفى تحقيق/ صلاح فضل تقديم / عبد العزيز النبوي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يهدف هذا الكتاب إلى تيسير النحو. وقد قدم له طه حسين بمقدمة قرظه فيها، بينما ذهب الدكتور شوقي ضيف إلى أن الكتاب، بالرغم مما قيل من أن مباحثه لا تضيف تيسيرات في النحو، فإنها تضيف تعليلات وافتراضات جديدة\nولعل أكثر ما وُجِّه إليه من نقد ما ذكره أحمد أحمد بدوي في مجلة الرسالة بعنوان “نقد كتاب إحياء النحو”\nوعلى الرغم من ذلك فإن الكتاب قد أثار قضية تيسير النحو، وكان أول كتاب يظهر في العالم العربي في العصر الحديث في نقد نظريات النحو التعليمية\nوالكتاب ببساطة دعوة إلى معاودة رؤية النحو في المدارس، بشكل مبسط، واضعًا إياه في خدمة اللغة العربية وتيسيرها، وإقامة جسور الفهم والمعرفة والمتعة بالدرس النحوي، الذي ينطلق بك في سلاسة لإدراك جمال اللغة وروعة تراكيبها. فهو كتاب جدير بقراءته، وتأمل أفكار مؤلفه\nاسم المؤلف :- ابراهيم مصطفى\nسنة النشر :- 2019", "/images/products/9789777952224.webp", "9789777952224", "احياء النحو", null, 170m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 927, "أحمد حسن السمان", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بقراءة هذا الكتاب سوف تدرك الفروق بين اعتبارات جمع وكتابة الأخبار للصحافة والإذاعة والتليفزيون ولمواقع الإنترنت وسمات غرف الأخبار في كل منها وتميز غرف الأخبار المدمجة عنها، كما ستعرف كيفية إجراء المقابلات مع المصادر وأنواعها وقواعدها وعملية بناء شبكة العلاقات. وعبر عدد من التدريبات العملية ستعرف أكثر من طريقة للوصول إلى الفكرة الخبرية التي تعد أساس العمل الصحفي. كما يحاول الكتاب الإجابة عن بعض الأسئلة منها؛ كيف تغيرت عملية جمع الأخبار في ظل تعقد بيئة العمل؟ كيف يُجري المحرر مقابلة قوية وناجحة باعتبارها أحد أهم أدوات جمع المعلومات الضرورية للكتابة للوسائط المتعددة؟ وما هي الكتابة الإعلامية التي تناسب غرف الأخبار المدمجة؟ هل أدت التطورات التكنولوجية ووفرة المعلومات إلى التقليل من أهمية المبادئ والقيم المهنية والأخلاقية أم زادت منها؟ وكيف يمكن تكوين شبكة علاقات قوية من المصادر؟ اسم المؤلف :- احمد حسن السمان سنة النشر :- 2019", "/images/products/9789777952200.webp", "9789777952200", "الكتابة للوسائط المتعددة وغرف الاخبار المدمجة", null, 275m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 928, "ولاء كمال", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحمسنا كثيراً حينما أخبرنا ولاء برغبته فى أن يكتب كتاباً عن جيلنا، وأن تكون كايروكي هى محور هذا الكتاب باعتبارها تجربة تعبر في مضمونها عن روح وأفكار كل من يشبهنا، وعلى الرغم من إدراكنا أن الكتاب سيحمل أكثر من مجرد سرد لرحلتنا الفنية والشخصية، إلا أن النتيجة فى النهاية فاجأتنا جميعاً.هذا الكتاب ليس عن كايروكي فقط، ولكنه عن الفن، الموسيقى، والإبداع. هو أيضاً كتاب عن الصداقة فى مواجهة الإحباط والتحديات، وكتاب عن الهوية والتاريخ. باختصار هذا كتاب عنا جميعاً كجيل يبحث عن صوته المتفرد وسط هذا العالم.نرجو أن تستمعوا بهذه الرحلة التي يأخذكم فيها الكاتب كما استمتعنا نحن برحلتنا معه طوال عامين كاملين\nاسم المؤلف :- ولاء كمال\nسنة النشر :- 2019", "/images/products/9789777952163.webp", "9789777952163", "ايامى مع كايروكى", null, 335m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 929, "ايمن فؤاد سيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تَعَدَّدَت الدِّراساتُ التي تَناوَلَت عَصْرَ سَلاطِين المـَمالِـيك في مِصْــر ، سَواءً التي كَتَــبَها المـُسْتَشْرِقُون أو الباحِثُون العَـرَب ، ودَرَسَت التَارِيخَ السِّياسِي والاقْتِصادِي والاجْتِماعِي والعَسْكَرِي وكذلك تارِيخَ النُّظُم والقَضَاء والدَّواوِين الإدارِيَّة ورُسُوم البَلاط ، وخاضَ بعضُها في التَّفاصِيل الدَّقِيقَة للأحْدَاث . لذلك أصْبَحَت الحاجَةُ ماسَّة إلى دِراسَةٍ شَامِلَةٍ تَتَناوَلُ الخـُطُوطَ العَرِيضَة لدَوْلَةِ سَلاطِـين المـَمالِـيك تُفِيدُ المـُــتَخَصِّص عن طَرِيق الإحالَة إلى أحْدَثِ الدِّراسات المـُــتَخَصِّصَة كما تُفِيدُ المـُــثَقَف الذي يَنْشُدُ التَّعَرُّفَ على طَبِيعَة هذا النِّظام الذي انْفَرَدَت به الدَّوْلَة الإسْلامِيَّـة.\nويَنْـقَسِمُ هذا الكتابُ إلى قِسْمَيْن رَئِيسَيْن ، تَناوَلَ القِسْمُ الأوَّل أصُولَ النِّظَام المـَمْلُوكي في مِصْـر والتَّارِيخَ السِّياسِي لدَوْلَة سَلاطِين المـَمالِـيك (البَحْرِيَّة والشَّراكِسَة) باسْتِعْرَاض الخـُطُوطِ العَرِيضَة والظَّواهِر الرَّئِيسَة لسِياسَات الدَّوْلَة مع تَحْلِيل أطْوارِ هذا التَّارِيخ دون الخـَوْضِ في التَّفاصِيل الدَّقِيقَة للأحْدَاث ، مع الإحَالَة على أحْدَث الدِّراسَات التي تَناوَلَت تَفْصِيلًا هذه الظَّواهِر والأحْدَاث . وتَناوَلَ القِسْمُ الثَّاني بعض الظَّواهِر الحـَضَارِيَّة للدَّوْلَة تَتَعَلَّقُ بالإنْتاجِ العِلْمِي والفِكْرِي وخَصَائِص المـَصَاحِف المـَمْلُوكِيَّة ونِظَام خَزائِن الكُتُب ثم التَّارِيخ العُمْراني في زَمَنِ سَلاطِين المـَمالِـيك وما يَخْتَصُّ منه بتَطَوُّر مَدِينَة القاهِرَة وامْتِدادِها ، وأخِيرًا نِظام المـَدارِس الذي سادَ وانْتَشَرَ في عَصْرِهِم\nالمؤلف :- ايمن فؤاد سيد\nسنة النشر :- 2019", "/images/products/9789777952149.webp", "9789777952149", "دولة سلاطين المماليك فى مصر", null, 275m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 930, "عمار على حسن", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تمزج هذه المجموعة بين الواقع البائس والخيال الجامح، صانعة عالما يتحرك فيه مقهورون وخائفون، وأيضا حالمون ومغامرون يكافحون من أجل حياة تليق بالبشر. تضم المجموعة أربع عشرة قصة تدور أحداثها في مكانين، الريف والمدينة، متراوحة بين قصص مكثفة، تتهادى في مشهد أو موقف أو حالة أو لحظة، وأخرى مطولة تضغط في سطورها ما يمكن إن طال أن يشكل رواية كاملة.\n المؤلف :- عمار على حسن\n سنة النشر :- 2019", "/images/products/9789777952231.webp", "9789777952231", "أخت روحى", null, 170m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 931, "أحمد أمين", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لكتاب «يوم الإسلام» مَزيَّة خاصَّة في مُجمَل أعمال أحمد أمين؛ إذ إنه الكتاب الأخير في مسيرته الفكرية والثقافية التي امتدَّت ما يقرُب من خمسين عامًا، وبهذا الكتاب يُكمل سِفرين كبيرين في مشروعه الفكري والاجتماعي لحضارة الإسلام، منذ النشأة، وحتى مراحل الازدهار، وصولًا لحالات الانكسار والصحوات الكبرى.\nفكتاب «يوم الإسلام» يشتمل على الإسلام أصوله وعوارضه في عصوره المختلفة، ويُشهَد له أنه يقف على مرحلة تاريخية طويلة وممتدَّة في مسيرة الفكر الإسلامي، ففيه حديث عن أُسس الإسلام، ومبادئه، ومراحل قيام الدولة، وحضارة الإسلام، والتحديات التي تواجه أبناءه، ووصف لحالات الصراع القديم والـمُمتد، ودفاع عن جوهر الدين الإسلامي والحضارة الإسلامية الوسطية، ونقد السياسة الأوربية، وأهم خطوات الإصلاح المنشودة، ودور الفرد وقيمته في المفهوم الإسلامي.\nوقد ألَّف أحمد أمين هذا الكتاب في الفترة الأخيرة من حياته، وكان قد أُصيب في عينيه، فنصحه الأطباء بتجنُّب القراءة وخصوصًا بالليل، فكان لا بد من الاستعانة بالغير لإنجاز ما يعِنُّ له من أفكار، وهي حالة وصفها – رحمه الله – بغير الـمُثمرة؛ لأنه كان يستطيع أن يتصفَّح الكتاب في ساعاتٍ ليقف على ما فيه وما يُفيده، أما قراءة الغير فلا تُجزي هذا الإجزاء.\nوقد عاش أحمد أمين حياةً حافلةً بالنشاط والعطاء، فألَّف وحقَّق وترجم عددًا كبيرًا من الكتب المهمة التي تأخذ مكان الصدارة بين أُمَّهات الكتب، لما تزخر به من الأفكار والآراء السديدة، فضلًا عن أسلوبٍ سلسٍ، عذْبٍ، لا تكلُّف فيه\n المؤلف :- احمد امين\n سنة النشر :- 2019", "/images/products/9789777952194.webp", "9789777952194", "يوم الاسلام", null, 225m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 932, "إحسان عبد القدوس", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ودون أن تحس وجدت نفسها تتركه.. وتترك ابنها وابنتها.. وتترك البيت.. وتهرب دون أن تفاتح أحدهما بما قررته.. بل إنها هي نفسها لم تكن تعلم ماذا قررت.. وأخذت تجوب الشوارع طوال النهار إلى أن وجدت نفسها تذهب إلى بيت أختها الكبرى وتعلنها أنها ستقيم عندها..\"\n المؤلف :- احسان عبد القدوس\n سنة النشر :- 2019", "/images/products/9789777952187.webp", "9789777952187", "وتاهت بعد العمر الطويل", null, 220m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 933, "جابر عصفور", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "والحق أن المناقشات التي أثارها \"زمن الرواية\" وردودي عليها، والمضي في تأصيل دلالات ما أقصد إليه من معانٍ ودلالات لهذا الزمن هي التي جعلتني أستبدل \"بزمن الرواية\" زمن القصّ، وأن أقرن العنوان الجديد بجملة نجيب محفوظ التي تصف القصّ، أو فن القصة بعامة، بأنه شعر الدنيا الحديثة وذلك على ما ورد في دفاعه عن الفن الذي أحبه، وخصص له حياته كلها، فكافأته الدنيا الحديثة بجائزة نوبل.\nوأظنني قدمت في الطبعة الجديدة من كتابي \"الجديد\" تأصيلا مختلفا لنشأة هذا الفن وتطوره في آن. فمن الواضح أنني لست مع المدرسَة التي ترى أننا استوردنا فن القصّ(Narration) من الغرب تماما، أو أن رواية \"زينب\" سنة 1913، هي الرواية الأولى في الأدب العربي الحديث، فأنا من الذين يؤمنون بأن فنَّ القصّ تأسَّس في الأدب العربي نتيجة عاملين: عامل داخلي يتصل بتقاليد القصّ العربي وأنواعه السردية المختلفة، ابتداء من السرد التاريخي، وليس انتهاء بالقصّ الرمزي الفلسفي والصوفي، فضلا عن الملاحم أو السِّير الشعبية. وإذا أنكرنا وجود هذا العامل كذَّبتنا روائع قصصية معترف بها في العالم كله مثل \"ألف ليلة وليلة\" أو ما يماثلها في التأثير. أما العامل الثاني فهو العامل الخارجي الذي يتصل بالرواية الأوربية وتقاليدها وتحوّلاتها في الوقت نفسه.\nوأظنُّ أن هذه النظرة تجمع بين الأصالة والمعاصرة في صياغةٍ منهجيةٍ، لا تنكر عظمة ترائها القصصي وفتنة العالم كله به، كما لا تنكر التفاعل الطويل والمستمر بين الموروث والوافد في التاريخ وبالتاريخ، وذلك على نحو يؤدي إلى التكامل في المنظورين بين فن القصّ الذي ظهرت بوادره في منتصف القرن التاسع عشر، أو في عمل موازٍ، وعبر مرور السنوات تطور هذا النوع من القصّ إلى أن صعد على يدي محمد حسين هيكل وأبناء جيله الذين أعادوا إنتاج النموذج الغربي الأوربي، في سياق صعود الوعي الوطني الذي كانت ثورة 1919 أحد انفجاراته\n المؤلف :- جابر عصفور\n سنة النشر :- 2019", "/images/products/9789777952101.webp", "9789777952101", "زمن القص", null, 300m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 934, "سامح فايز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "شهدت السنوات الأخيرة صعود عدد من الظواهر الأدبية المتعلقة بالقراءة فى مصر، كان أهمها انتشار نوعية معينة من الكتابات، مثل أدب الرعب والخيال العلمي، والكتابات الرومانسية، وأدب السيرة الذاتية، وسطوة السوشيال ميديا التي أثرت بشكل كبير على حركة صناعة الكتاب والنشر في مصر، وفي كتاب \" best seller - حكايات عن القراءة\"، يحاول المؤلف رصد جميع الظواهر المتعلقة بحركة الكتابة والقراءة وتقديم قراءة لها بشكل بسيط بعيدًا عن تعقيدات الكتابة الأكاديمية. ويقدم الكتاب شرحًا وافيًا لظاهرة \"البيست سيلر\" أو الكتب الأكثر مبيعًا، مع رصد لصعود تلك النوعية من الكتابات مع شرح لحقيقتها وهل هي الأكثر مبيعا بالفعل أم لا. هو كتاب مهم لكل مهتم بالقراءة في محاولة لمعرفة ما الذي حدث للقراءة منذ يناير 2011 وحتى الآن\n المؤلف :- سامح فايز\n سنة النشر :- 2019", "/images/products/9789777952217.webp", "9789777952217", "BEST SELLER - حكايات عن القراءة", null, 175m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 935, "عزت القمحاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما وقعت عيناه على فريدة أول مرة جمَّدته الدهشة «لقد عشت هذا من قبل» وأحس أن الحياة عادت عرضًا لطيفًا وأنه لم يفقد ملَكة رؤية\n الأشياء قبل وقوعها.\nكان متأكدًا من أنه يرى النداء الذي أطلقه ذلك الوجه من قبل. استشعر شيئًا حارًا، أقوى من الألفة التي كان يستشعرها بصحبة الإناث. وعندما دعاها بعد ذلك إلى شقته للمرة الأولى، جلس بجوارها على الكنبة يبتسم بعصبية، كان يحس نفسه مخادعًا، وأنها لم تقبل الدعوة إلا بدافع الإشفاق عليه من وحدتـه التي بالـغ في وصفها، لكنها هي التي قبَّلته أولًا\n المؤلف :- عزت القمحاوى\n سنة النشر :- 2019", "/images/products/9789777952170.webp", "9789777952170", "ما راه سامى يعقوب", null, 165m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 936, "رضوى موسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نعيش حياة واحدة من الممكن أن تتغير في لمح البصر وبدون سابق إنذار، لكن هل لديك القوة والقدرة على الصمود لمواجهة هذا التغير المفاجئ؟ هل تستطيع الابتسام في أشد لحظات احتياجك للانهيار؟\n هل تستطيع احتواء الخوف والغضب وإحساس العجز والصبر لقبول سعادة مؤجلة؟\n هذا الكتاب هو قصة حقيقية لبطل ألهمت شجاعته الآلاف.. زين الذي تعافى من مراحل متأخرة من السرطان 4 مرات.\n هذا الكتاب يظل قصة ملهمة لمن يمر بتجربة قاسية، أيًّا كانت\n المؤلف :- رضوى موسى\n سنة النشر :- 2019\n\nيوسف", "/images/products/9789777952132.webp", "9789777952132", "زين - حكاية عتمة ونور", null, 200m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 937, "محمد صلاح عزب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتحدث الرواية عن رجل حائر بين أكثر من امرأة، يتأرجح بينهن كبندول الساعة، لايعرف الاستقرار أو الراحة النفسية. يقدمها الكاتب في لغة سلسة وجذابة. هل هو مجني عليه أم أنه يجني على كل من تدخل في دائرته؟!.. علاقات إنسانية مرتبكة تشبه الزمن والمدينة التي لم تعرف الهدوء في أي لحظة في تاريخها!\nالمؤلف :- محمد صلاح العزب\nسنة النشر :- 2019", "/images/products/9789777952088.webp", "9789777952088", "كل شئ هادئ فى القاهرة", null, 250m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 938, "شيرين سامي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لم أكن أعرف أن بحثي عن نفسي يعني فقداني لها، حاولت أن أعيش دون أن أفكّر في ما أفعله، دون أن أعرف ما عليّ أن أفعله وما يجدر بي فعله، كافحت حتى أكون مثل الجميع، عانيت حتى لا أصغي لقلبي، لكن الشغف سحبني من أطراف ثيابي ومشيت فوق آلامي وعجزي وتحركت عكس علامات الطريق، من الظل إلى الشمس، مشيت في كل الممرات التي قد تؤدي إليَّ، ظننت أنني لا أخاف. والآن فقدت قدرتي ليس على الرؤية فحسب، لكن على الحركة والتفكير والكلام. الآن قدماي مثبّتتان على الأرض وظهري للجدار. لا أحتاج لأحد ولا أغفر لأحد. كل ما فيَّ لن يمنعني من التعرّف على الجزء الكافي مني الذي يمكّنني أن أتخذ قرارًا. حتى لو ابتلعني هذا القرار.\n المؤلف :- شيرين سامى\n سنة النشر :- 2019", "/images/products/9789777952040.webp", "9789777952040", "من ذاق عرف", null, 250m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 939, "أحمد الشهاوى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "المرأة أكثر رُقيًّا من الرجُل في مسألة الحُب ، إذ إن الحُبَّ هدفها، ومُبتغاها، وإذا ما غاب الحُبُّ عنها، تعيش حياةً يصيبها الفقد في كُلِّ شيء.وليت الرجل يعرف أنَّ المرأة تحتاجُ إلى العشق أولًا، ثم الوصل الجسدي، يأتي في مرتبةٍ تاليةٍ. وكثير منا يعيش ولا يعرف ما الحُب، ومامكانته؟ وقبل أن تعرف كيف تحب، عليك إدراك ما هو الحب؟ ولماذا نحب؛ لأنَّ الحُبَّ صار ضائعًا وغريبًا بين الناس مُمارسةً وسلوكًا.\nأحمد الشهاوي في هذا الكتاب يؤكد أن العشق فلسفة الفطرة التي يكون عليها المُحبُّ والمحبُوب؛ وهو أساسُ الفضائل وأصلُها ؛ لأنَّ النفسَ فُطِرت على العشق، فالعشق ديانةٌ يؤمنُ بها من في جوفه قلبٌ ينطقُ. والكتاب يؤكد أن لا حُب يحيا تحت مظلة شرطٍ أو طلبٍ أو غرَضٍ؛ لأننا عندما نعشقُ، يكون اليوم الذي نحياه بألفِ يومٍ مما كُنَّا عليه قبل العشق، لأن عُمر الإنسان يُقاسُ بما (قبل الحُب) ، وبما (بعد الحُب).\n المؤلف :- احمد الشهاوى\n سنة النشر :- 2019", "/images/products/9789777952125.webp", "9789777952125", "كن عاشقا", null, 185m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 940, "حازم مبروك", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا دين إلا الحب – شعر\nأَنَا يَا ابـنَ أمِّي مُؤمـنٌ بطَريقَتِي\nلا مِثْلَ مَا قالوا ولا مَا عَلَّلُوا\nأنَا مُؤْمِنٌ بِالرَّبِّ… فَرْحةِ ثَاكِلٍ\nشَبَعِ اليَتَامَى مُنجِزٍ مَـا أمَّلُوا\nأَنَـا لَا أَرَاهُ هُنَــاكَ لكِـنْ هَهُنــَا\nهُمْ أَبْعَدُوهُ وَحَرَّمُوهُ وَحَلَّلُوا\nلَا دِينَ إِلَّا الـحُب لَسْتُ بِصَابِئٍ\nلَكِـنْ بِهَـذَا دِيـنُــه يَـتـَنَـزَّلُ\nالمؤلف :- حازم مبروك\nسنة النشر :- 2019", "/images/products/9789777952118.webp", "9789777952118", "لا دين الا الحب", null, 125m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 941, "حمدى النورج", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كاد يرسخ في أذهان عشاق الرباعيات أن كل مجموعة منسوبة إلى عمر الخيام هي من بنات أفكار هذا الفيلسوف الشاعر، لولا مقال للأستاذ الروسي شكوفسكي عام 7981 أثبت أن اثنتين وثمانين منها واردة في دواوين غيره من شعراء الفرس، وأن نحو نصف هذا العدد لثلاثة من كبارهم، هم فريد الدين العطار، وحافظ، وجلال الدين الرومي، وأما النصف الآخر فلأربعين آخرين كأبي سعيد وابن سينا والفردوسي وأنوري وعبدالله الأنصاري، وقد لقبوها بـ \"الرباعيات المتشردة\". والظاهر أن مورديها في نسخهم كانوا يلفونها شبيهة بالرباعيات الخيامية فيضيفونها إليها بقصد أو بغير قصد. ولقد زاد عددها منذ ظهور تلك المقالة فبلغ 101.\n أما الرباعيات التي لا ريب في نسبتها إليه فلا تنيف عن الإحدى عشرة، وهي التي أردفها باسمه من ذكره من معاصريه في آثارهم الباقية\n حتى اليوم.المؤلف :- حمدى النورج\n سنة النشر :- 2019", "/images/products/9789777952064.webp", "9789777952064", "رباعيات عمر الخيام الفلكى الشاعر الفيلسوف الفارسى", null, 115m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 942, "يوسف كرم - تعليق - مصطفى النشار", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إن هذه السلسلة من كلاسيكيات الفلسفة تأليفًا وترجمة هي أبرز ما قامت عليه نهضتنا الحديثة، وهي ما تربت عليه الأجيال السابقة.\nوما أحوجنا اليوم لإعادة نشر هذه الكلاسيكيات من مؤلفات ومترجمات رائدة لتستفيد منها أجيالنا الشابة، وخاصة في ظل ندرة ما يكتبه المتخصصون المعاصرون في الفلسفة ومجالاتها المختلفة، وفي ظل غياب المنهج الفلسفي للتفكير في حياتنا المعاصرة، مما كان السبب المباشر لما نراه من تطرف وتعصب وجمود وعدم تقبل الآخر وفقدان القدرة على التحليل ونقد الأفكار.\nإن هؤلاء الفلاسفة كانوا يحاولون كشف واكتشاف وتفسير أسرار الوجود بعقولهم، وكان لهذه العقول الفضل في تطور الفهم عندهم حتى توصلوا إلى الكثير من أسرار الوجود واكتشاف أصل الوجود وعلته الأولى: \"الله\". ولعل ذلك الارتياد العقلي لأسرار الوجود والتوصل إلى اكتشاف حقيقة وجود \"الله\" هو ما أبهر الشراح والفلاسفة من المؤمنين بالديانات السماوية الثلاث: اليهودية والمسيحية والإسلام، فوقفوا فلسفاتهم الدينية على التوفيق بين ما توصل إليه فلاسفة اليونان بتأملاتهم المجردة وما أتى به وحي السماء في الكتب المقدسة.\nإن فلاسفة اليونان كانوا من خلال عقولهم المتأملة فقط قد نجحوا في التمهيد للإيمان بالأديان السماوية. والمهم هنا هو أن يتتبع القارئ العزيز كيف تطورت الفلسفة اليونانية من فيلسوف لآخر عبرالحوار والمناقشة والنقد من لاحقهم لسابقهم دون كلل أو ملل، ودون أن يغضب أحدهم من نقد أو أن يتعصب أحدهم لرأيه. إن الهدف النهائي من قرائتنا لتاريخ الفلسفة ليس ترديد أو حفظ ما يقوله الفلاسفة، وإنما هو اكتساب نمط التفكير الفلسفي الذي يقوم على التحليل والنقد والحوار الذي يحترم فيه الرأي والرأي الآخر، وكل ذلك بغرض الوصول إلى الحقيقة في كل مجالات الوجود والحياة حتى اليوم.\nالمؤلف :- يوسف كرم\nسنة النشر :- 2019", "/images/products/9789772937592.webp", "9789772937592", "تاريخ الفلسفة اليونانية", null, 300m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 943, "زينب عفيفي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نتظرته في اليقظة والمنام، وحينما تحقق الحلم كان نفس الرجل الذي عذب أمها في شبابها،\n وبقيت قراءة الروايات هي الحماية والسكن مع أمها الكفيفة، وشرفة غرفتها المطلة على حديقة\n البيت هي الباب الملكي لأبطال القصص والروايات الذين يؤنسون وحدتها كل ليلة،\n ويحولون العالم الهادئ من حولها إلى صخب\n المؤلف :- زينب عفيفى\n سنة النشر :- 2019", "/images/products/9789777952071.webp", "9789777952071", "احلم وانا بجوارك", null, 170m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 944, "Dina ELmessiri", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "Eyes of Wisdom - Small Steps to Transform your Life\nWhat does it take to transform your life to the better?\nJust by reading any book, or taking any course, or even by listening to wise people; None of  that will improve your life. However, by applying the knowledge and taking the action, you have the power to change your life! And what’s even better to change the lives of people around you. Knowing something is not enough. Knowing what you should do is not enough. You have to use what you do. It’s time to take action, to put into practice a new approach that focuses on results and measurable improvement. Visualize your outcome. Imagine the steps to get you there. Make a list. Take a first step, and another and another, even small steps count. Check mark the steps you have taken and celebrate every progress. Self development is an ongoing journey.\nThis book is designed to help you grow in confidence and self awareness and equip you to take a starring role in your own life.\nBe the best version of yourself. Feel optimistic everyday. Move towards the life you really want to live.\nAuthor: Dina Emissary\nYear of Publication : 2019", "/images/products/9789777951999.webp", "9789777951999", "EYES OF WISDOM SMALL STEPS TO TRANSFORM", null, 250m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false }
                });
        }

